(e) => setEmail(e.target.value)}\n                  required\n                  autoComplete=\"email\"\n                  autoFocus\n                />\n              </div>\n            </div>\n\n            {/* Password */}\n            <div style={styles.fieldGroup}>\n              <label style={styles.fieldLabel} htmlFor=\"password\">Mot de passe</label>\n              <div style={styles.inputWrap}>\n                <i className=\"fas fa-lock\" style={styles.inputIcon} />\n                <input\n                  id=\"password\"\n                  type={showPwd ? 'text' : 'password'}\n                  className=\"form-input\"\n                  style={{ ...styles.input, paddingRight: 44 }}\n                  placeholder=\"••••••••\"\n                  value={password}\n                  onChange={(e) => setPassword(e.target.value)}\n                  required\n                  autoComplete=\"current-password\"\n                />\n                <button\n                  type=\"button\"\n                  tabIndex={-1}\n                  style={styles.eyeBtn}\n                  onClick={() => setShowPwd((v) => !v)}\n                  title={showPwd ? 'Masquer' : 'Afficher'}\n                >\n                  <i className={`fas ${showPwd ? 'fa-eye-slash' : 'fa-eye'}`} />\n                </button>\n              </div>\n            </div>\n\n            {/* Submit */}\n            <button\n              type=\"submit\"\n              className=\"btn btn-primary\"\n              style={styles.submitBtn}\n              disabled={isLoading}\n            >\n              {isLoading ? (\n                <>\n                  <span className=\"spinner\" style={{ width: 16, height: 16, marginRight: 8 }} />\n                  Connexion en cours…\n                </>\n              ) : (\n                <>\n                  <i className=\"fas fa-right-to-bracket\" style={{ marginRight: 8 }} />\n                  Se connecter\n                </>\n              )}\n            </button>\n          </form>\n\n          {/* Footer note */}\n          <p style={styles.formFooter}>\n            Accès réservé aux utilisateurs autorisés par AIDES.\n          </p>\n        </div>\n      </div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  /* Layout */\n  page: {\n    minHeight: '100vh',\n    display: 'flex',\n    fontFamily: 'var(--font-sans)',\n  },\n\n  /* Left branding panel */\n  leftPanel: {\n    width: '45%',\n    background: 'linear-gradient(160deg, #1e2433 0%)',\n    display: 'flex',\n    flexDirection: 'column',\n    justifyContent: 'space-between',\n    padding: '48px 48px 32px',\n    position: 'relative',\n    overflow: 'hidden',\n  },\n  leftInner: {\n    display: 'flex',\n    flexDirection: 'column',\n  },\n  headline: {\n    fontSize: 32,\n    fontWeight: 800,\n    color: '#ffffff',\n    lineHeight: 1.25,\n    marginBottom: 16,\n  },\n  tagline: {\n    fontSize: 15,\n    color: 'rgba(255,255,255,0.7)',\n    lineHeight: 1.6,\n    marginBottom: 40,\n    maxWidth: 380,\n  },\n  features: {\n    display: 'flex',\n    flexDirection: 'column',\n    gap: 16,\n  },\n  featureRow: {\n    display: 'flex',\n    alignItems: 'center',\n    gap: 14,\n  },\n  featureIcon: {\n    width: 36,\n    height: 36,\n    borderRadius: '50%',\n    background: 'rgba(245,166,35,0.18)',\n    border: '1px solid rgba(245,166,35,0.35)',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    color: '#f5a623',\n    flexShrink: 0,\n  },\n  featureText: {\n    fontSize: 14,\n    color: 'rgba(255,255,255,0.85)',\n    fontWeight: 500,\n  },\n  attribution: {\n    fontSize: 12,\n    color: 'rgba(255,255,255,0.35)',\n    marginTop: 0,\n  },\n\n  /* Right form panel */\n  rightPanel: {\n    flex: 1,\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    background: '#f8fafc',\n    padding: '32px 24px',\n  },\n  formCard: {\n    background: '#ffffff',\n    borderRadius: 16,\n    boxShadow: '0 4px 32px rgba(0,0,0,0.10)',\n    padding: '40px 40px 32px',\n    width: '100%',\n    maxWidth: 420,\n  },\n  formHeader: {\n    textAlign: 'center',\n    marginBottom: 28,\n  },\n  formLogoWrap: {\n    marginBottom: 16,\n  },\n  formTitle: {\n    fontSize: 24,\n    fontWeight: 800,\n    color: '#1e2433',\n    margin: '0 0 6px',\n  },\n  formSubtitle: {\n    fontSize: 14,\n    color: '#6b7280',\n    margin: 0,\n  },\n\n  /* Error box */\n  errorBox: {\n    display: 'flex',\n    alignItems: 'center',\n    background: '#fef2f2',\n    border: '1px solid #fca5a5',\n    borderRadius: 8,\n    color: '#dc2626',\n    fontSize: 14,\n    padding: '10px 14px',\n    marginBottom: 20,\n  },\n\n  /* Form fields */\n  form: {\n    display: 'flex',\n    flexDirection: 'column',\n    gap: 20,\n  },\n  fieldGroup: {\n    display: 'flex',\n    flexDirection: 'column',\n    gap: 6,\n  },\n  fieldLabel: {\n    fontSize: 13,\n    fontWeight: 600,\n    color: '#374151',\n  },\n  inputWrap: {\n    position: 'relative',\n    display: 'flex',\n    alignItems: 'center',\n  },\n  inputIcon: {\n    position: 'absolute',\n    left: 12,\n    color: '#9ca3af',\n    fontSize: 14,\n    pointerEvents: 'none',\n  },\n  input: {\n    paddingLeft: 38,\n    width: '100%',\n    boxSizing: 'border-box',\n  },\n  eyeBtn: {\n    position: 'absolute',\n    right: 12,\n    background: 'none',\n    border: 'none',\n    color: '#9ca3af',\n    cursor: 'pointer',\n    padding: '0 2px',\n    fontSize: 14,\n    display: 'flex',\n    alignItems: 'center',\n  },\n\n  /* Submit */\n  submitBtn: {\n    width: '100%',\n    justifyContent: 'center',\n    padding: '12px 20px',\n    fontSize: 15,\n    fontWeight: 700,\n    marginTop: 4,\n  },\n\n  /* Footer */\n  formFooter: {\n    fontSize: 12,\n    color: '#9ca3af',\n    textAlign: 'center',\n    marginTop: 24,\n    marginBottom: 0,\n  },\n}\n","import { useState, type FormEvent } from 'react'\nimport { useNavigate } from 'react-router-dom'\nimport { registerWithToken, ApiError } from '@/api/api'\n\nexport default function RegisterPage() {\n  const navigate = useNavigate()\n\n  const [email, setEmail] = useState('')\n  const [token, setToken] = useState('')\n  const [password, setPassword] = useState('')\n  const [confirmPassword, setConfirmPassword] = useState('')\n  const [error, setError] = useState<string | null>(null)\n  const [success, setSuccess] = useState(false)\n  const [isLoading, setIsLoading] = useState(false)\n\n  async function handleSubmit(e: FormEvent) {\n    e.preventDefault()\n    setError(null)\n\n    if (password !== confirmPassword) {\n      setError(\"Les mots de passe ne correspondent pas.\")\n      return\n    }\n    if (password.length < 8) {\n      setError(\"Le mot de passe doit contenir au moins 8 caractères.\")\n      return\n    }\n\n    setIsLoading(true)\n    try {\n      await registerWithToken(email.trim(), token.trim(), password)\n      setSuccess(true)\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : \"Erreur lors de la création du compte.\")\n    } finally {\n      setIsLoading(false)\n    }\n  }\n\n  if (success) {\n    return (\n      <div style={styles.page}>\n        <div style={{ ...styles.card, textAlign: 'center' }}>\n          <div style={{ fontSize: 56, marginBottom: 16 }}>🎉</div>\n          <h2 style={{ fontSize: 'var(--text-2xl)', fontWeight: 700, color: 'var(--color-text)', marginBottom: 8 }}>\n            Compte créé avec succès !\n          </h2>\n          <p style={{ color: 'var(--color-text-muted)', marginBottom: 'var(--space-6)' }}>\n            Votre compte est activé. Vous pouvez maintenant vous connecter.\n          </p>\n          <button className=\"btn btn-primary\" style={{ width: '100%', justifyContent: 'center' }} onClick={() => navigate('/login')}>\n            <i className=\"fas fa-sign-in-alt\" style={{ marginRight: 8 }} />\n            Se connecter\n          </button>\n        </div>\n      </div>\n    )\n  }\n\n  return (\n    <div style={styles.page}>\n      <div style={styles.card}>\n        {/* Logo */}\n        <div style={{ textAlign: 'center', marginBottom: 'var(--space-8)' }}>\n          <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ width: 200, display: 'block', margin: '0 auto 16px' }} />\n          <p style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>\n            Activez votre compte avec le code reçu par email\n          </p>\n        </div>\n\n        {error && (\n          <div className=\"alert alert-error\" style={{ marginBottom: 'var(--space-4)' }}>\n            <i className=\"fas fa-exclamation-circle\" style={{ marginRight: 8 }} />\n            {error}\n          </div>\n        )}\n\n        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"email\">Adresse email professionnelle</label>\n            <input\n              id=\"email\"\n              type=\"email\"\n              className=\"form-input\"\n              placeholder=\"votre@equipetech.aides-mada.com\"\n              value={email}\n              onChange={(e) => setEmail(e.target.value)}\n              required\n              autoComplete=\"email\"\n              autoFocus\n            />\n          </div>\n\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"token\">\n              Code d'invitation\n              <span style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', marginLeft: 6 }}>\n                (6 chiffres reçus par email)\n              </span>\n            </label>\n            <input\n              id=\"token\"\n              type=\"text\"\n              className=\"form-input\"\n              placeholder=\"123456\"\n              value={token}\n              onChange={(e) => setToken(e.target.value.replace(/\\D/g, '').slice(0, 6))}\n              maxLength={6}\n              pattern=\"[0-9]{6}\"\n              required\n              style={{ letterSpacing: 8, fontWeight: 700, fontSize: 20, textAlign: 'center' }}\n            />\n          </div>\n\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"password\">Choisir un mot de passe</label>\n            <input\n              id=\"password\"\n              type=\"password\"\n              className=\"form-input\"\n              placeholder=\"Minimum 8 caractères\"\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              required\n              autoComplete=\"new-password\"\n            />\n          </div>\n\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"confirm\">Confirmer le mot de passe</label>\n            <input\n              id=\"confirm\"\n              type=\"password\"\n              className=\"form-input\"\n              placeholder=\"••••••••\"\n              value={confirmPassword}\n              onChange={(e) => setConfirmPassword(e.target.value)}\n              required\n              autoComplete=\"new-password\"\n            />\n          </div>\n\n          <button\n            type=\"submit\"\n            className=\"btn btn-primary\"\n            style={{ width: '100%', justifyContent: 'center', padding: '10px' }}\n            disabled={isLoading || token.length !== 6}\n          >\n            {isLoading ? (\n              <><span className=\"spinner\" style={{ width: 16, height: 16 }} /> Activation…</>\n            ) : (\n              <><i className=\"fas fa-user-check\" style={{ marginRight: 8 }} />Activer mon compte</>\n            )}\n          </button>\n        </form>\n\n        <p style={{ textAlign: 'center', marginTop: 'var(--space-4)', fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>\n          Vous avez déjà un compte ?{' '}\n          <button className=\"btn btn-ghost btn-sm\" onClick={() => navigate('/login')} style={{ display: 'inline', padding: 0 }}>\n            Se connecter\n          </button>\n        </p>\n      </div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  page: {\n    minHeight: '100vh',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    background: 'linear-gradient(135deg, #1e2433 0%, #2d3748 100%)',\n    padding: 'var(--space-4)',\n  },\n  card: {\n    background: 'var(--color-surface)',\n    borderRadius: 'var(--radius-xl)',\n    boxShadow: 'var(--shadow-lg)',\n    padding: 'var(--space-10)',\n    width: '100%',\n    maxWidth: 420,\n  },\n}\n","/**\n * Indicateur de statut réseau + synchronisation.\n * Affiché dans la topbar de l'éditeur et du dashboard.\n */\nimport { useNetworkStore } from '@/stores/networkStore'\nimport { syncService } from '@/services/syncService'\n\nexport default function SyncIndicator() {\n  const isOnline       = useNetworkStore((s) => s.isOnline)\n  const syncInProgress = useNetworkStore((s) => s.syncInProgress)\n  const pendingOps     = useNetworkStore((s) => s.pendingOps)\n  const lastSyncAt     = useNetworkStore((s) => s.lastSyncAt)\n\n  // ── Hors ligne ──────────────────────────────────────────────────────────────\n  if (!isOnline) {\n    return (\n      <div style={styles.pill('#dc2626', '#fef2f2')} title=\"Mode hors-ligne — modifications enregistrées localement\">\n        <span style={styles.dot('#dc2626')} />\n        <span>Hors ligne</span>\n        {pendingOps > 0 && (\n          <span style={styles.badge('#dc2626')}>{pendingOps}</span>\n        )}\n      </div>\n    )\n  }\n\n  // ── En ligne + synchronisation en cours ────────────────────────────────────\n  if (syncInProgress) {\n    return (\n      <div style={styles.pill('#f5a623', '#fffbeb')} title=\"Synchronisation en cours…\">\n        <span className=\"spinner\" style={{ width: 10, height: 10, borderWidth: 2 }} />\n        <span>Sync…</span>\n      </div>\n    )\n  }\n\n  // ── En ligne + opérations en attente ──────────────────────────────────────\n  if (pendingOps > 0) {\n    return (\n      <button\n        style={{ ...styles.pill('#f5a623', '#fffbeb'), cursor: 'pointer', border: 'none' }}\n        title={`${pendingOps} modification(s) à synchroniser — cliquez pour synchroniser`}\n        onClick={() => syncService.processSyncQueue()}\n      >\n        <span style={styles.dot('#f5a623')} />\n        <span>{pendingOps} en attente</span>\n        <i className=\"fas fa-rotate\" style={{ fontSize: 10, marginLeft: 2 }} />\n      </button>\n    )\n  }\n\n  // ── En ligne + tout synchronisé ────────────────────────────────────────────\n  const lastSync = lastSyncAt\n    ? new Date(lastSyncAt).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })\n    : null\n\n  return (\n    <div\n      style={styles.pill('#16a34a', '#f0fdf4')}\n      title={lastSync ? `Dernière sync à ${lastSync}` : 'Connecté'}\n    >\n      <span style={styles.dot('#16a34a')} />\n      <span>En ligne</span>\n      {lastSync && (\n        <span style={{ fontSize: 10, opacity: 0.7, marginLeft: 2 }}>{lastSync}</span>\n      )}\n    </div>\n  )\n}\n\n// ── Styles inline ──────────────────────────────────────────────────────────────\n\nconst styles = {\n  pill: (color: string, bg: string): React.CSSProperties => ({\n    display:      'inline-flex',\n    alignItems:   'center',\n    gap:          5,\n    padding:      '3px 10px',\n    borderRadius: 20,\n    background:   bg,\n    color,\n    fontSize:     12,\n    fontWeight:   600,\n    whiteSpace:   'nowrap',\n    userSelect:   'none',\n  }),\n  dot: (color: string): React.CSSProperties => ({\n    width:        7,\n    height:       7,\n    borderRadius: '50%',\n    background:   color,\n    flexShrink:   0,\n  }),\n  badge: (color: string): React.CSSProperties => ({\n    display:      'inline-flex',\n    alignItems:   'center',\n    justifyContent: 'center',\n    width:        18,\n    height:       18,\n    borderRadius: '50%',\n    background:   color,\n    color:        '#fff',\n    fontSize:     10,\n    fontWeight:   700,\n    marginLeft:   2,\n  }),\n}\n","import { NavLink, useNavigate } from 'react-router-dom'\nimport { useAuthStore } from '@/stores/authStore'\n\ninterface NavItem {\n  to: string\n  label: string\n  icon: string\n}\n\nconst mainNav: NavItem[] = [\n  { to: '/', label: 'Tableau de bord', icon: 'fa-gauge-high' },\n  { to: '/users', label: 'Utilisateurs', icon: 'fa-users' },\n]\n\ninterface Props {\n  isOpen?: boolean\n  onClose?: () => void\n}\n\nexport default function AppSidebar({ isOpen = false, onClose }: Props) {\n  const navigate = useNavigate()\n  const user = useAuthStore((s) => s.user)\n  const logout = useAuthStore((s) => s.logout)\n\n  function handleLogout() {\n    logout()\n    navigate('/login', { replace: true })\n  }\n\n  return (\n    <>\n      {/* Overlay for mobile */}\n      {isOpen && (\n        <div className=\"sidebar-overlay\" onClick={onClose} />\n      )}\n    <aside className={`sidebar${isOpen ? ' sidebar--open' : ''}`}>\n      {/* Logo */}\n      <div className=\"sidebar-logo\">\n        <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ width: '60%', maxWidth: 150, display: 'block', margin: '0 auto' }} />\n      </div>\n\n      {/* Navigation */}\n      <nav className=\"sidebar-nav\">\n        <div className=\"sidebar-section-label\">Navigation</div>\n        {mainNav.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            end\n            className={({ isActive }) =>\n              `sidebar-nav-item ${isActive ? 'active' : ''}`\n            }\n          >\n            <i className={`fas ${item.icon}`} style={{ width: 18, textAlign: 'center', fontSize: 13, flexShrink: 0 }} />\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n\n      {/* Footer — user info + logout */}\n      <div className=\"sidebar-footer\">\n        <div style={styles.userBlock}>\n          <div style={styles.avatar}>\n            {user?.initials ?? '?'}\n          </div>\n          <div style={styles.userInfo}>\n            <div style={styles.userName}>{user?.fullName ?? 'Utilisateur'}</div>\n            <div style={styles.userEmail}>{user?.email ?? ''}</div>\n          </div>\n        </div>\n        <button\n          className=\"btn btn-ghost\"\n          style={{ width: '100%', justifyContent: 'center', color: '#9ca3af', marginTop: 8 }}\n          onClick={handleLogout}\n        >\n          Déconnexion\n        </button>\n      </div>\n    </aside>\n    </>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  userBlock: {\n    display: 'flex',\n    alignItems: 'center',\n    gap: 10,\n  },\n  avatar: {\n    width: 34,\n    height: 34,\n    borderRadius: '50%',\n    background: 'var(--color-primary)',\n    color: '#fff',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    fontSize: 13,\n    fontWeight: 700,\n    flexShrink: 0,\n  },\n  userInfo: {\n    overflow: 'hidden',\n  },\n  userName: {\n    fontSize: 'var(--text-sm)',\n    fontWeight: 600,\n    color: '#f3f4f6',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  },\n  userEmail: {\n    fontSize: 'var(--text-xs)',\n    color: '#6b7280',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  },\n}\n","/**\n * Moteur de calculs financiers — port TypeScript du fichier HTML.\n * Toutes les valeurs monétaires sont en Ariary (entiers).\n * Les calculs se font 100% côté client, jamais stockés en base sauf snapshot.\n */\n\nimport type {\n  CompanySettings,\n  Product,\n  Material,\n  StaffMember,\n  Expense,\n  Investment,\n  AdditionalFunding,\n  InflationFactors,\n  IncomeStatement,\n  CashFlowStatement,\n  DepreciationTable,\n  LoanRepaymentTable,\n  Profitability,\n} from '@/types'\n\n// ─── Utilitaires ─────────────────────────────────────────────────────────────\n\n/** Arrondi à l'entier (Ariary = pas de décimales) */\nexport const round = (n: number) => Math.round(n)\n\n/** Formattage monétaire Ariary */\nexport const formatAriary = (n: number): string =>\n  new Intl.NumberFormat('fr-MG', {\n    style: 'decimal',\n    maximumFractionDigits: 0,\n  }).format(round(n)) + ' Ar'\n\n/** Formattage pourcentage */\nexport const formatPct = (n: number, decimals = 1): string =>\n  `${n.toFixed(decimals)} %`\n\n// ─── Inflation ────────────────────────────────────────────────────────────────\n\n/**\n * Calcule les facteurs d'inflation cumulatifs pour les années 1-5.\n * L'inflation An 1 est toujours 1.0 (base).\n * An 2 = 1 + infl2/100, An 3 = An 2 × (1 + infl3/100), etc.\n */\nexport function buildInflationFactors(settings: CompanySettings): InflationFactors {\n  const f2 = 1 + (settings.infl2 ?? 0) / 100\n  const f3 = f2 * (1 + (settings.infl3 ?? 0) / 100)\n  const f4 = f3 * (1 + (settings.infl4 ?? 0) / 100)\n  const f5 = f4 * (1 + (settings.infl5 ?? 0) / 100)\n  return { year1: 1, year2: f2, year3: f3, year4: f4, year5: f5 }\n}\n\nexport function inflationArray(factors: InflationFactors): number[] {\n  return [factors.year1, factors.year2, factors.year3, factors.year4, factors.year5]\n}\n\n// ─── Chiffre d'affaires ───────────────────────────────────────────────────────\n\n/**\n * Revenu annuel d'un produit pour l'année `yearIndex` (0-based = An 1).\n * qty An N = sum(monthlyQty) × growthRate cumulatif\n * revenu An N = qty An N × price × (facteur croissance propre au produit)\n */\nexport function productRevenueByYear(\n  product: Product,\n  yearIndex: number,\n): number {\n  const baseQty = product.monthlyQty.reduce((a, b) => a + b, 0)\n  // growthRates[0] = taux croissance An 2 vs An 1, etc.\n  let qtyFactor = 1\n  for (let y = 0; y < yearIndex; y++) {\n    qtyFactor *= 1 + (product.growthRates[y] ?? 0) / 100\n  }\n  return round(baseQty * qtyFactor * product.price)\n}\n\nexport function totalRevenueByYear(products: Product[]): number[] {\n  return Array.from({ length: 5 }, (_, y) =>\n    products.reduce((sum, p) => sum + productRevenueByYear(p, y), 0),\n  )\n}\n\n// ─── Coût des matières premières ─────────────────────────────────────────────\n\nexport function materialCostByYear(material: Material, yearIndex: number): number {\n  const baseQty = material.monthlyQty.reduce((a, b) => a + b, 0)\n  let qtyFactor = 1\n  for (let y = 0; y < yearIndex; y++) {\n    qtyFactor *= 1 + (material.growthRates[y] ?? 0) / 100\n  }\n  return round(baseQty * qtyFactor * material.unitCost)\n}\n\nexport function totalMaterialCostByYear(materials: Material[]): number[] {\n  return Array.from({ length: 5 }, (_, y) =>\n    materials.reduce((sum, m) => sum + materialCostByYear(m, y), 0),\n  )\n}\n\n// ─── Charges de personnel ─────────────────────────────────────────────────────\n\nexport function staffAnnualCost(staff: StaffMember): number {\n  return round(staff.monthlySalary * staff.headcount * 12 * (1 + staff.chargesRate / 100))\n}\n\n/**\n * Coût annuel d'un poste pour l'année `yearIndex` (0-based = An 1).\n * growthRates[0] = hausse salariale An 2 vs An 1 (taux individuel par poste).\n * Coût = base × ∏(1 + growthRate[y]).\n */\nexport function staffAnnualCostByYear(\n  staff: StaffMember,\n  yearIndex: number,\n): number {\n  const base = staffAnnualCost(staff)\n  let factor = 1\n  for (let y = 0; y < yearIndex; y++) {\n    factor *= 1 + ((staff.growthRates?.[y] ?? 0) / 100)\n  }\n  return round(base * factor)\n}\n\n/**\n * Masse salariale totale par année — croissance individuelle par poste.\n */\nexport function totalStaffCostByYear(staffMembers: StaffMember[]): number[] {\n  return Array.from({ length: 5 }, (_, y) =>\n    staffMembers.reduce((sum, s) => sum + staffAnnualCostByYear(s, y), 0),\n  )\n}\n\n// ─── Charges d'exploitation ───────────────────────────────────────────────────\n\nexport function expenseAnnualTotal(expense: Expense): number {\n  return round(expense.monthlyAmount * expense.seasonality.reduce((a, b) => a + b, 0))\n}\n\n/**\n * Total annuel d'une charge pour l'année `yearIndex` (0-based = An 1).\n * inflationGrowth[y] = taux de croissance individuel de la charge pour An y+2.\n */\nexport function expenseTotalByYear(expense: Expense, yearIndex: number): number {\n  let factor = 1\n  for (let y = 0; y < yearIndex; y++) {\n    factor *= 1 + (expense.inflationGrowth[y] ?? 0) / 100\n  }\n  return round(expenseAnnualTotal(expense) * factor)\n}\n\nexport function totalExpensesByYear(expenses: Expense[]): number[] {\n  return Array.from({ length: 5 }, (_, y) =>\n    expenses.reduce((sum, e) => sum + expenseTotalByYear(e, y), 0),\n  )\n}\n\n// ─── Amortissements ───────────────────────────────────────────────────────────\n\nexport function buildDepreciationTable(investments: Investment[]): DepreciationTable {\n  const byInvestment = investments.map((inv) => {\n    const annualDepreciation = inv.usefulLife > 0 ? inv.amount / inv.usefulLife : 0\n    const yearlyBook = Array.from({ length: 5 }, (_, y) => {\n      const remaining = inv.amount - annualDepreciation * (y + 1)\n      return Math.max(0, round(remaining))\n    })\n    return {\n      investmentId: inv.id,\n      annualDepreciation: round(annualDepreciation),\n      yearlyBook,\n    }\n  })\n\n  const totalAnnualDepreciation = byInvestment.reduce(\n    (sum, i) => sum + i.annualDepreciation,\n    0,\n  )\n\n  return { byInvestment, totalAnnualDepreciation }\n}\n\n// ─── Tableau d'amortissement d'emprunt ───────────────────────────────────────\n\ninterface LoanPayment {\n  capital: number\n  interest: number\n  balance: number\n}\n\nfunction computeLoanSchedule(\n  principal: number,\n  annualRatePct: number,\n  years: number,\n): LoanPayment[] {\n  if (principal <= 0 || annualRatePct <= 0 || years <= 0) {\n    return Array.from({ length: Math.max(years, 5) }, () => ({\n      capital: 0,\n      interest: 0,\n      balance: 0,\n    }))\n  }\n\n  const r = annualRatePct / 100\n  // Annuité constante (emprunt à remboursement annuel constant, méthode française)\n  const annuity = (principal * r * Math.pow(1 + r, years)) / (Math.pow(1 + r, years) - 1)\n\n  let balance = principal\n  const schedule: LoanPayment[] = []\n\n  for (let y = 0; y < Math.max(years, 5); y++) {\n    if (y >= years || balance <= 0) {\n      schedule.push({ capital: 0, interest: 0, balance: 0 })\n    } else {\n      const interest = round(balance * r)\n      const capital = round(annuity - interest)\n      balance = Math.max(0, round(balance - capital))\n      schedule.push({ capital, interest, balance })\n    }\n  }\n\n  return schedule\n}\n\nexport function buildLoanRepaymentTable(investments: Investment[]): LoanRepaymentTable {\n  const byLoan = investments\n    .filter((inv) => inv.financedLoan > 0)\n    .map((inv) => ({\n      label: inv.name,\n      principal: inv.financedLoan,\n      rate: inv.loanRate,\n      years: inv.loanYears,\n      annualPayments: computeLoanSchedule(inv.financedLoan, inv.loanRate, inv.loanYears),\n    }))\n\n  const totalInterestByYear = Array.from({ length: 5 }, (_, y) =>\n    byLoan.reduce((sum, l) => sum + (l.annualPayments[y]?.interest ?? 0), 0),\n  )\n\n  const totalCapitalByYear = Array.from({ length: 5 }, (_, y) =>\n    byLoan.reduce((sum, l) => sum + (l.annualPayments[y]?.capital ?? 0), 0),\n  )\n\n  return { byLoan, totalInterestByYear, totalCapitalByYear }\n}\n\n// ─── Compte de résultat ───────────────────────────────────────────────────────\n\nexport function buildIncomeStatement(\n  products: Product[],\n  materials: Material[],\n  staffMembers: StaffMember[],\n  expenses: Expense[],\n  investments: Investment[],\n  settings: CompanySettings,\n  loanTable?: LoanRepaymentTable,\n): IncomeStatement {\n  const revenueByYear = totalRevenueByYear(products)\n  const materialCostByYear = totalMaterialCostByYear(materials)\n  const grossMarginByYear = revenueByYear.map((r, y) => r - materialCostByYear[y])\n  const staffCostByYear = totalStaffCostByYear(staffMembers)\n  const expenseCostByYear = totalExpensesByYear(expenses)\n  const ebitdaByYear = grossMarginByYear.map(\n    (gm, y) => gm - staffCostByYear[y] - expenseCostByYear[y],\n  )\n\n  const depTable = buildDepreciationTable(investments)\n  // Amortissement réel par année : s'arrête quand la VNC atteint 0\n  const depreciationByYear = Array.from({ length: 5 }, (_, y) =>\n    depTable.byInvestment.reduce((sum, row, i) => {\n      const inv = investments[i]\n      const prevBook = y === 0 ? inv.amount : row.yearlyBook[y - 1]\n      const currBook = row.yearlyBook[y]\n      return sum + Math.max(0, prevBook - currBook)\n    }, 0),\n  )\n\n  const ebitByYear = ebitdaByYear.map((e, y) => e - depreciationByYear[y])\n\n  // Utiliser le tableau déjà calculé si fourni, sinon recalculer\n  const { totalInterestByYear } = loanTable ?? buildLoanRepaymentTable(investments)\n  const interestByYear = totalInterestByYear\n\n  const ebtByYear = ebitByYear.map((e, y) => e - interestByYear[y])\n\n  // Impôt selon le régime fiscal\n  const taxByYear = ebtByYear.map((ebt) => {\n    if (ebt <= 0) return 0\n    if (settings.taxRegime === 'IS') {\n      return round(ebt * (settings.taxRateIs / 100))\n    }\n    return round(ebt * (settings.taxRate / 100))\n  })\n\n  const netIncomeByYear = ebtByYear.map((ebt, y) => ebt - taxByYear[y])\n\n  return {\n    revenueByYear,\n    materialCostByYear,\n    grossMarginByYear,\n    staffCostByYear,\n    expenseCostByYear,\n    ebitdaByYear,\n    depreciationByYear,\n    ebitByYear,\n    interestByYear,\n    ebtByYear,\n    taxByYear,\n    netIncomeByYear,\n  }\n}\n\n// ─── Tableau de flux de trésorerie ────────────────────────────────────────────\n\nexport function buildCashFlowStatement(\n  incomeStatement: IncomeStatement,\n  investments: Investment[],\n  additionalFundings: AdditionalFunding[],\n  loanTable: LoanRepaymentTable,\n  settings: CompanySettings,\n): CashFlowStatement {\n  const { netIncomeByYear, depreciationByYear } = incomeStatement\n\n  // Flux opérationnel = résultat net + amortissements - variation BFR\n  // FDR = fondsRoulement initial (trésorerie de départ, ne réduit pas le flux opérationnel)\n  const bfr = settings.fondsRoulement ?? 0\n  // CAF = résultat net + amortissements (pas de déduction BFR ici — géré dans tresoInitiale)\n  const operatingCashFlowByYear = netIncomeByYear.map(\n    (net, y) => net + depreciationByYear[y],\n  )\n\n  // Flux d'investissement (An 1 seulement pour l'instant — pas de CAPEX récurrent)\n  const totalInvestment = investments.reduce((sum, i) => sum + i.amount, 0)\n  const investmentByYear = [totalInvestment, 0, 0, 0, 0]\n\n  // Financement initial (An 1)\n  const totalEquityY1 =\n    investments.reduce((sum, i) => sum + i.financedEquity, 0) +\n    (additionalFundings.find((f) => f.yearNumber === 1)?.equity ?? 0)\n  const totalLoanY1 =\n    investments.reduce((sum, i) => sum + i.financedLoan, 0) +\n    (additionalFundings.find((f) => f.yearNumber === 1)?.loan ?? 0)\n  const totalGrantY1 =\n    investments.reduce((sum, i) => sum + i.financedGrant, 0) +\n    (additionalFundings.find((f) => f.yearNumber === 1)?.grant ?? 0)\n\n  // Apports complémentaires An 2-5\n  const equityByYear = Array.from({ length: 5 }, (_, y) => {\n    if (y === 0) return totalEquityY1\n    return additionalFundings.find((f) => f.yearNumber === y + 1)?.equity ?? 0\n  })\n\n  const loanByYear = Array.from({ length: 5 }, (_, y) => {\n    if (y === 0) return totalLoanY1\n    const af = additionalFundings.find((f) => f.yearNumber === y + 1)\n    return af ? af.loan : 0\n  })\n\n  const grantByYear = Array.from({ length: 5 }, (_, y) => {\n    if (y === 0) return totalGrantY1\n    return additionalFundings.find((f) => f.yearNumber === y + 1)?.grant ?? 0\n  })\n\n  const loanRepaymentByYear = loanTable.totalCapitalByYear\n\n  const netCashByYear = operatingCashFlowByYear.map(\n    (op, y) =>\n      op - investmentByYear[y] + equityByYear[y] + loanByYear[y] + grantByYear[y] - loanRepaymentByYear[y],\n  )\n\n  // La trésorerie cumulative démarre depuis le fonds de roulement initial (An 0)\n  // pour être cohérente avec CashFlowSection : tresoInitiale = equity+loan+grant-invest+fdr\n  const cumulativeCashByYear = netCashByYear.reduce<number[]>((acc, val, y) => {\n    acc.push((y === 0 ? bfr : (acc[y - 1] ?? 0)) + val)\n    return acc\n  }, [])\n\n  return {\n    netIncomeByYear,\n    depreciationByYear,\n    operatingCashFlowByYear,\n    investmentByYear,\n    equityByYear,\n    loanByYear,\n    grantByYear,\n    loanRepaymentByYear,\n    netCashByYear,\n    cumulativeCashByYear,\n  }\n}\n\n// ─── Indicateurs de rentabilité ───────────────────────────────────────────────\n\n/**\n * VAN (Valeur Actuelle Nette) — actualise les flux opérationnels nets.\n * Investissement initial = An 0 (sortie).\n */\nexport function computeNPV(\n  operatingCashFlows: number[],\n  initialInvestment: number,\n  discountRatePct: number,\n): number {\n  const r = discountRatePct / 100\n  let npv = -initialInvestment\n  operatingCashFlows.forEach((cf, y) => {\n    npv += cf / Math.pow(1 + r, y + 1)\n  })\n  return round(npv)\n}\n\n/**\n * TRI (Taux de Rentabilité Interne) — Newton-Raphson, identique à v20.\n * Pas de limite haute sur le taux (TRI peut être > 1000 %).\n * Retourne null uniquement si non convergent ou sans solution.\n */\nexport function computeIRR(\n  operatingCashFlows: number[],\n  initialInvestment: number,\n): number | null {\n  const cashFlows = [-initialInvestment, ...operatingCashFlows]\n\n  // Vérification signe : doit avoir au moins un positif et un négatif\n  const hasPositive = cashFlows.some((cf) => cf > 0)\n  const hasNegative = cashFlows.some((cf) => cf < 0)\n  if (!hasPositive || !hasNegative) return null\n\n  let rate = 0.1\n  for (let iter = 0; iter < 200; iter++) {\n    let npv = 0\n    let dnpv = 0\n    cashFlows.forEach((cf, t) => {\n      const disc = Math.pow(1 + rate, t)\n      npv  += cf / disc\n      dnpv -= (t * cf) / (disc * (1 + rate))\n    })\n    const denom = Math.abs(dnpv) < 1e-9 ? 1e-9 : dnpv\n    const newRate = rate - npv / denom\n    if (!isFinite(newRate)) return null\n    if (Math.abs(newRate - rate) < 1e-7) return Math.round(newRate * 10000) / 100\n    // Seule limite : éviter les logs indéfinis (rate = -1 singularité)\n    if (newRate < -0.999) return null\n    rate = newRate\n  }\n  // Retourner la meilleure approximation après 200 itérations\n  return Math.round(rate * 10000) / 100\n}\n\n/**\n * Indice de profitabilité = VAN / Investissement initial + 1\n */\nexport function computeProfitabilityIndex(npv: number, initialInvestment: number): number {\n  if (initialInvestment === 0) return 0\n  return Math.round(((npv + initialInvestment) / initialInvestment) * 100) / 100\n}\n\n/**\n * Retour sur investissement en années (payback sur flux cumulatifs).\n */\nexport function computePayback(\n  operatingCashFlows: number[],\n  initialInvestment: number,\n): number | null {\n  let cumulative = -initialInvestment\n  for (let y = 0; y < operatingCashFlows.length; y++) {\n    cumulative += operatingCashFlows[y]\n    if (cumulative >= 0) return y + 1\n  }\n  return null\n}\n\n/**\n * Année du seuil de rentabilité (breakeven) — première année où résultat net > 0.\n */\nexport function computeBreakEvenYear(netIncomeByYear: number[]): number | null {\n  for (let y = 0; y < netIncomeByYear.length; y++) {\n    if (netIncomeByYear[y] > 0) return y + 1\n  }\n  return null\n}\n\n/**\n * Calcule tous les indicateurs de rentabilité en une seule passe.\n */\nexport function buildProfitability(\n  cashFlow: CashFlowStatement,\n  investments: Investment[],\n  settings: CompanySettings,\n): Profitability {\n  // v20 : investissement initial = fonds propres uniquement (total - emprunt - subvention)\n  const initialInvestment = investments.reduce((sum, i) => sum + i.financedEquity, 0)\n\n  // v20 : flux opérationnels = CAF - remboursement capital (net après service de la dette)\n  const { operatingCashFlowByYear, loanRepaymentByYear, netIncomeByYear } = cashFlow\n  const opCashFlows = operatingCashFlowByYear.map(\n    (caf, y) => caf - loanRepaymentByYear[y],\n  )\n\n  const npv = computeNPV(opCashFlows, initialInvestment, settings.discountRate)\n  const irr = computeIRR(opCashFlows, initialInvestment)\n  const profitabilityIndex = computeProfitabilityIndex(npv, initialInvestment)\n  const paybackYear = computePayback(opCashFlows, initialInvestment)\n  const breakEvenYear = computeBreakEvenYear(netIncomeByYear)\n\n  return { npv, irr, profitabilityIndex, paybackYear, breakEvenYear }\n}\n\n// ─── Bilan prévisionnel ───────────────────────────────────────────────────────\n\nexport interface BalanceSheet {\n  // ACTIF\n  fixedAssetsGross: number        // Immobilisations brutes (constant)\n  accumulatedDepreciationByYear: number[]  // Amortissements cumulés An 1-5\n  fixedAssetsNetByYear: number[]  // VNC = brut - amort cumulé\n  bfr: number                    // BFR (constant après An 1)\n  cashByYear: number[]           // Trésorerie = cumulativeCash\n  totalAssetsByYear: number[]    // TOTAL ACTIF\n\n  // PASSIF\n  initialCapital: number         // Capital social initial (constant)\n  cumulativeReservesByYear: number[] // Réserves = cumul résultats antérieurs\n  netIncomeByYear: number[]      // Résultat de l'exercice\n  loanBalanceByYear: number[]    // Emprunt restant dû\n  totalLiabilitiesByYear: number[] // TOTAL PASSIF\n}\n\nexport function buildBalanceSheet(\n  investments: Investment[],\n  depreciationTable: DepreciationTable,\n  loanRepaymentTable: LoanRepaymentTable,\n  cashFlow: CashFlowStatement,\n  incomeStatement: IncomeStatement,\n  settings: CompanySettings,\n): BalanceSheet {\n  const fixedAssetsGross = investments.reduce((s, i) => s + i.amount, 0)\n\n  // VNC par année = somme des yearlyBook de chaque investissement\n  // yearlyBook s'arrête à 0 une fois l'investissement totalement amorti\n  const fixedAssetsNetByYear = Array.from({ length: 5 }, (_, y) =>\n    depreciationTable.byInvestment.reduce((sum, row) => sum + (row.yearlyBook[y] ?? 0), 0),\n  )\n  const accumulatedDepreciationByYear = fixedAssetsNetByYear.map(\n    (vnc) => Math.max(0, fixedAssetsGross - vnc),\n  )\n\n  const bfr = settings.fondsRoulement ?? 0\n  const cashByYear = cashFlow.cumulativeCashByYear\n\n  const totalAssetsByYear = fixedAssetsNetByYear.map(\n    (net, y) => net + bfr + Math.max(0, cashByYear[y]),\n  )\n\n  // Capital = somme des fonds propres apportés (investissements + apports An 1-5)\n  const initialCapital = cashFlow.equityByYear.reduce((s, v) => s + v, 0)\n\n  // Réserves = résultats cumulés des années précédentes\n  const cumulativeReservesByYear = incomeStatement.netIncomeByYear.reduce<number[]>(\n    (acc, _net, y) => {\n      acc.push(y === 0 ? 0 : (acc[y - 1] ?? 0) + incomeStatement.netIncomeByYear[y - 1])\n      return acc\n    },\n    [],\n  )\n\n  // Emprunt restant dû = somme des balances de fin d'année\n  const loanBalanceByYear = Array.from({ length: 5 }, (_, y) =>\n    loanRepaymentTable.byLoan.reduce(\n      (sum, loan) => sum + (loan.annualPayments[y]?.balance ?? 0),\n      0,\n    ),\n  )\n\n  const totalLiabilitiesByYear = Array.from({ length: 5 }, (_, y) =>\n    initialCapital +\n    cumulativeReservesByYear[y] +\n    incomeStatement.netIncomeByYear[y] +\n    loanBalanceByYear[y],\n  )\n\n  return {\n    fixedAssetsGross,\n    accumulatedDepreciationByYear,\n    fixedAssetsNetByYear,\n    bfr,\n    cashByYear,\n    totalAssetsByYear,\n    initialCapital,\n    cumulativeReservesByYear,\n    netIncomeByYear: incomeStatement.netIncomeByYear,\n    loanBalanceByYear,\n    totalLiabilitiesByYear,\n  }\n}\n\n// ─── Plan de financement ──────────────────────────────────────────────────────\n\nexport interface FinancingPlan {\n  // RESSOURCES\n  cafByYear: number[]            // CAF = résultat net + amortissements\n  equityByYear: number[]         // Fonds propres apportés\n  loanByYear: number[]           // Emprunts contractés\n  grantByYear: number[]          // Subventions\n  totalResourcesByYear: number[] // Total ressources\n\n  // EMPLOIS\n  investmentByYear: number[]     // Investissements (An 1 uniquement)\n  loanRepaymentByYear: number[]  // Remboursements capital\n  bfrByYear: number[]            // Variation BFR (An 1 uniquement)\n  totalUsesByYear: number[]      // Total emplois\n\n  // SOLDE\n  balanceByYear: number[]        // Ressources - Emplois\n  cumulativeBalanceByYear: number[] // Solde cumulé\n}\n\nexport function buildFinancingPlan(\n  incomeStatement: IncomeStatement,\n  cashFlow: CashFlowStatement,\n  settings: CompanySettings,\n): FinancingPlan {\n  const cafByYear = incomeStatement.netIncomeByYear.map(\n    (net, y) => net + incomeStatement.depreciationByYear[y],\n  )\n\n  const bfr = settings.fondsRoulement ?? 0\n  const bfrByYear = [bfr, 0, 0, 0, 0]\n\n  const totalResourcesByYear = cafByYear.map(\n    (caf, y) =>\n      caf +\n      cashFlow.equityByYear[y] +\n      cashFlow.loanByYear[y] +\n      cashFlow.grantByYear[y],\n  )\n\n  const totalUsesByYear = cashFlow.investmentByYear.map(\n    (inv, y) => inv + cashFlow.loanRepaymentByYear[y] + bfrByYear[y],\n  )\n\n  const balanceByYear = totalResourcesByYear.map((r, y) => r - totalUsesByYear[y])\n\n  const cumulativeBalanceByYear = balanceByYear.reduce<number[]>((acc, val, y) => {\n    acc.push((acc[y - 1] ?? 0) + val)\n    return acc\n  }, [])\n\n  return {\n    cafByYear,\n    equityByYear: cashFlow.equityByYear,\n    loanByYear: cashFlow.loanByYear,\n    grantByYear: cashFlow.grantByYear,\n    totalResourcesByYear,\n    investmentByYear: cashFlow.investmentByYear,\n    loanRepaymentByYear: cashFlow.loanRepaymentByYear,\n    bfrByYear,\n    totalUsesByYear,\n    balanceByYear,\n    cumulativeBalanceByYear,\n  }\n}\n\n// ─── Ratios de rentabilité détaillés ─────────────────────────────────────────\n\nexport interface ProfitabilityRatios {\n  grossMarginPctByYear: number[]   // Marge brute %\n  ebitdaMarginPctByYear: number[]  // EBITDA margin %\n  netMarginPctByYear: number[]     // Marge nette %\n  breakEvenValueByYear: number[]   // Seuil de rentabilité en Ariary\n  breakEvenMonthByYear: number[]   // Point mort en mois\n}\n\nexport function buildProfitabilityRatios(\n  incomeStatement: IncomeStatement,\n): ProfitabilityRatios {\n  const safeDiv = (a: number, b: number) => (b !== 0 ? round((a / b) * 100) / 100 : 0)\n\n  const grossMarginPctByYear = incomeStatement.revenueByYear.map((r, y) =>\n    safeDiv(incomeStatement.grossMarginByYear[y], r) * 100,\n  )\n  const ebitdaMarginPctByYear = incomeStatement.revenueByYear.map((r, y) =>\n    safeDiv(incomeStatement.ebitdaByYear[y], r) * 100,\n  )\n  const netMarginPctByYear = incomeStatement.revenueByYear.map((r, y) =>\n    safeDiv(incomeStatement.netIncomeByYear[y], r) * 100,\n  )\n\n  // Seuil de rentabilité = Charges fixes / (1 - Charges variables / CA)\n  const breakEvenValueByYear = incomeStatement.revenueByYear.map((rev, y) => {\n    const varCosts = incomeStatement.materialCostByYear[y]\n    const fixedCosts =\n      incomeStatement.staffCostByYear[y] +\n      incomeStatement.expenseCostByYear[y] +\n      incomeStatement.depreciationByYear[y] +\n      incomeStatement.interestByYear[y]\n    if (rev === 0) return 0\n    const varRate = varCosts / rev\n    if (varRate >= 1) return 0\n    return round(fixedCosts / (1 - varRate))\n  })\n\n  // Point mort en mois = seuil / CA × 12\n  const breakEvenMonthByYear = breakEvenValueByYear.map((sr, y) => {\n    const rev = incomeStatement.revenueByYear[y]\n    if (rev === 0) return 12\n    return Math.min(12, Math.ceil((sr / rev) * 12))\n  })\n\n  return {\n    grossMarginPctByYear,\n    ebitdaMarginPctByYear,\n    netMarginPctByYear,\n    breakEvenValueByYear,\n    breakEvenMonthByYear,\n  }\n}\n\n// ─── Point d'entrée unique ────────────────────────────────────────────────────\n\nexport interface FullCalculationResult {\n  incomeStatement: IncomeStatement\n  depreciationTable: DepreciationTable\n  loanRepaymentTable: LoanRepaymentTable\n  cashFlowStatement: CashFlowStatement\n  profitability: Profitability\n  balanceSheet: BalanceSheet\n  financingPlan: FinancingPlan\n  profitabilityRatios: ProfitabilityRatios\n}\n\n/**\n * Lance tous les calculs en une passe à partir des données brutes d'une entreprise.\n * Appelé chaque fois que l'utilisateur modifie une donnée dans l'éditeur.\n */\nexport function computeAll(\n  settings: CompanySettings,\n  products: Product[],\n  materials: Material[],\n  staffMembers: StaffMember[],\n  expenses: Expense[],\n  investments: Investment[],\n  additionalFundings: AdditionalFunding[],\n): FullCalculationResult {\n  const depreciationTable = buildDepreciationTable(investments)\n  const loanRepaymentTable = buildLoanRepaymentTable(investments)\n\n  // Passer le tableau d'emprunt déjà calculé pour garantir\n  // que le compte de résultat utilise exactement les mêmes intérêts\n  // que le tableau de remboursement affiché\n  const incomeStatement = buildIncomeStatement(\n    products,\n    materials,\n    staffMembers,\n    expenses,\n    investments,\n    settings,\n    loanRepaymentTable,\n  )\n\n  const cashFlowStatement = buildCashFlowStatement(\n    incomeStatement,\n    investments,\n    additionalFundings,\n    loanRepaymentTable,\n    settings,\n  )\n\n  const profitability = buildProfitability(cashFlowStatement, investments, settings)\n  const balanceSheet = buildBalanceSheet(\n    investments,\n    depreciationTable,\n    loanRepaymentTable,\n    cashFlowStatement,\n    incomeStatement,\n    settings,\n  )\n  const financingPlan = buildFinancingPlan(incomeStatement, cashFlowStatement, settings)\n  const profitabilityRatios = buildProfitabilityRatios(incomeStatement)\n\n  return {\n    incomeStatement,\n    depreciationTable,\n    loanRepaymentTable,\n    cashFlowStatement,\n    profitability,\n    balanceSheet,\n    financingPlan,\n    profitabilityRatios,\n  }\n}\n\n\n// ─── Trésorerie mensuelle An 1 ────────────────────────────────────────────────\n\nexport interface MonthlyCashFlow {\n  encaissements: number[]      // CA mensuel (12 valeurs)\n  coutsVariables: number[]     // Coûts variables mensuels\n  personnelMensuel: number     // Personnel mensuel (constant)\n  autresCharges: number[]      // Charges mensuelles\n  impotMensuel: number         // Impôt / 12\n  fraisFinanciersMensuel: number  // Intérêts / 12\n  rembCapitalMensuel: number   // Remb. capital / 12\n  apportMois: number[]         // Apport An 1 en janvier seulement\n  soldeMensuel: number[]       // Solde net mensuel\n  soldeCumule: number[]        // Solde cumulé depuis tresoInitiale\n}\n\nexport function buildMonthlyCashFlow(\n  products: Product[],\n  materials: Material[],\n  staffMembers: StaffMember[],\n  expenses: Expense[],\n  incomeStatement: IncomeStatement,\n  loanRepaymentTable: LoanRepaymentTable,\n  additionalFundings: AdditionalFunding[],\n  tresoInitiale: number,\n): MonthlyCashFlow {\n  // CA mensuel = somme sur les produits de (prix × qty mensuelle[m])\n  const encaissements = Array.from({ length: 12 }, (_, m) =>\n    round(products.reduce((sum, p) => sum + p.price * (p.monthlyQty[m] ?? 0), 0)),\n  )\n\n  // Coûts variables mensuels\n  const coutsVariables = Array.from({ length: 12 }, (_, m) =>\n    round(materials.reduce((sum, mat) => sum + mat.unitCost * (mat.monthlyQty[m] ?? 0), 0)),\n  )\n\n  // Personnel mensuel brut chargé (identique chaque mois)\n  const personnelMensuel = round(\n    staffMembers.reduce((sum, s) => sum + s.monthlySalary * s.headcount * (1 + s.chargesRate / 100), 0),\n  )\n\n  // Charges d\\'exploitation mensuelles\n  const autresCharges = Array.from({ length: 12 }, (_, m) =>\n    round(expenses.reduce((sum, e) => sum + e.monthlyAmount * (e.seasonality[m] ?? 0), 0)),\n  )\n\n  // Frais répartis uniformément sur 12 mois\n  const impotMensuel = round(incomeStatement.taxByYear[0] / 12)\n  const fraisFinanciersMensuel = round(loanRepaymentTable.totalInterestByYear[0] / 12)\n  const rembCapitalMensuel = round(loanRepaymentTable.totalCapitalByYear[0] / 12)\n\n  // Apport complémentaire An 1 : versé en janvier (mois 0)\n  const af1 = additionalFundings.find((f) => f.yearNumber === 1)\n  const addTotalAn1 = af1 ? af1.equity + af1.loan + af1.grant : 0\n  const apportMois = Array.from({ length: 12 }, (_, m) => (m === 0 ? addTotalAn1 : 0))\n\n  // Solde mensuel net\n  const soldeMensuel = Array.from({ length: 12 }, (_, m) =>\n    encaissements[m]\n    - coutsVariables[m]\n    - personnelMensuel\n    - autresCharges[m]\n    - impotMensuel\n    - fraisFinanciersMensuel\n    - rembCapitalMensuel\n    + apportMois[m],\n  )\n\n  // Solde cumulé depuis trésorerie initiale\n  const soldeCumule: number[] = []\n  let running = tresoInitiale\n  for (let m = 0; m < 12; m++) {\n    running += soldeMensuel[m]\n    soldeCumule.push(Math.round(running))\n  }\n\n  return {\n    encaissements,\n    coutsVariables,\n    personnelMensuel,\n    autresCharges,\n    impotMensuel,\n    fraisFinanciersMensuel,\n    rembCapitalMensuel,\n    apportMois,\n    soldeMensuel: soldeMensuel.map(Math.round),\n    soldeCumule,\n  }\n}\n","import type { CompanySummary } from '@/types'\nimport { formatAriary } from '@/calculations/calculations'\n\ninterface Props {\n  company: CompanySummary\n  onOpen: () => void\n  onDelete: () => void\n  onDuplicate: () => void\n}\n\nexport default function CompanyCard({ company, onOpen, onDelete, onDuplicate }: Props) {\n  const snap = company.snapshot\n  const pct = snap?.completionPct ?? 0\n\n  return (\n    <div style={styles.card} onClick={onOpen} role=\"button\" tabIndex={0}\n      onKeyDown={(e) => e.key === 'Enter' && onOpen()}\n    >\n      {/* Header */}\n      <div style={styles.header}>\n        <div style={styles.avatarBg}>\n          <span style={styles.avatarText}>{company.name.charAt(0).toUpperCase()}</span>\n        </div>\n        <div style={{ flex: 1, overflow: 'hidden' }}>\n          <div style={styles.name}>{company.name}</div>\n          {company.secteur && <div style={styles.sector}>{company.secteur}</div>}\n        </div>\n        {/* Action buttons — stop propagation so click doesn't open editor */}\n        <div style={styles.actions} onClick={(e) => e.stopPropagation()}>\n          <button\n            className=\"btn btn-ghost btn-sm\"\n            title=\"Dupliquer\"\n            onClick={onDuplicate}\n          >\n            ⎘\n          </button>\n          <button\n            className=\"btn btn-ghost btn-sm\"\n            style={{ color: 'var(--color-danger)' }}\n            title=\"Supprimer\"\n            onClick={onDelete}\n          >\n            🗑\n          </button>\n        </div>\n      </div>\n\n      {/* Completion progress */}\n      <div style={{ marginBottom: 'var(--space-3)' }}>\n        <div style={styles.progressLabel}>\n          <span style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)' }}>Complétion</span>\n          <span style={{ fontSize: 'var(--text-xs)', fontWeight: 600 }}>{pct} %</span>\n        </div>\n        <div className=\"progress-bar-wrapper\">\n          <div\n            className=\"progress-bar-fill\"\n            style={{ width: `${pct}%`, background: pct === 100 ? 'var(--color-success)' : undefined }}\n          />\n        </div>\n      </div>\n\n      {/* KPIs */}\n      {snap ? (\n        <div style={styles.kpiRow}>\n          <KpiItem label=\"CA An 1\" value={formatAriary(snap.revenueY1)} />\n          <KpiItem label=\"Résultat\" value={formatAriary(snap.netIncomeY1)} positive={snap.netIncomeY1 >= 0} />\n          <KpiItem label=\"Tréso cum.\" value={formatAriary(snap.cashCumY1)} positive={snap.cashCumY1 >= 0} />\n        </div>\n      ) : (\n        <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', textAlign: 'center', padding: '4px 0' }}>\n          Aucune donnée — ouvrir pour commencer\n        </p>\n      )}\n\n      {/* Footer */}\n      {company.promoteur && (\n        <div style={styles.footer}>\n          <span>Promoteur : {company.promoteur}</span>\n          {company.lastModifiedBy && (\n            <span style={{ color: 'var(--color-text-muted)' }}>\n              · Modifié par {company.lastModifiedBy.initials}\n            </span>\n          )}\n        </div>\n      )}\n    </div>\n  )\n}\n\nfunction KpiItem({ label, value, positive }: { label: string; value: string; positive?: boolean }) {\n  const color =\n    positive === undefined\n      ? 'var(--color-text)'\n      : positive\n      ? 'var(--color-success)'\n      : 'var(--color-danger)'\n\n  return (\n    <div style={{ textAlign: 'center' }}>\n      <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)' }}>{label}</div>\n      <div style={{ fontSize: 11, fontWeight: 700, color }}>{value}</div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  card: {\n    background: 'var(--color-surface)',\n    border: '1px solid var(--color-border)',\n    borderRadius: 'var(--radius-md)',\n    padding: 'var(--space-4)',\n    cursor: 'pointer',\n    transition: 'box-shadow var(--transition-fast), border-color var(--transition-fast)',\n    display: 'flex',\n    flexDirection: 'column',\n    gap: 'var(--space-3)',\n  },\n  header: {\n    display: 'flex',\n    alignItems: 'flex-start',\n    gap: 'var(--space-3)',\n  },\n  avatarBg: {\n    width: 38,\n    height: 38,\n    borderRadius: 'var(--radius)',\n    background: 'var(--color-primary-light)',\n    display: 'flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    flexShrink: 0,\n  },\n  avatarText: {\n    fontSize: 18,\n    fontWeight: 700,\n    color: 'var(--color-primary)',\n  },\n  name: {\n    fontWeight: 600,\n    fontSize: 'var(--text-sm)',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  },\n  sector: {\n    fontSize: 'var(--text-xs)',\n    color: 'var(--color-text-muted)',\n    marginTop: 1,\n  },\n  actions: {\n    display: 'flex',\n    gap: 2,\n    flexShrink: 0,\n  },\n  progressLabel: {\n    display: 'flex',\n    justifyContent: 'space-between',\n    marginBottom: 4,\n  },\n  kpiRow: {\n    display: 'grid',\n    gridTemplateColumns: '1fr 1fr 1fr',\n    gap: 'var(--space-2)',\n    background: 'var(--color-surface-2)',\n    borderRadius: 'var(--radius)',\n    padding: 'var(--space-2)',\n  },\n  footer: {\n    display: 'flex',\n    gap: 'var(--space-2)',\n    fontSize: 'var(--text-xs)',\n    color: 'var(--color-text-muted)',\n    borderTop: '1px solid var(--color-border)',\n    paddingTop: 'var(--space-2)',\n  },\n}\n","import type { ProjectSummary, CompanySummary } from '@/types'\nimport CompanyCard from '@/components/dashboard/CompanyCard'\n\ninterface Props {\n  project: ProjectSummary\n  onDeleteProject: () => void\n  onAddCompany: () => void\n  onDeleteCompany: (companyId: number) => void\n  onDuplicateCompany: (companyId: number) => void\n  onOpenEditor: (companyId: number) => void\n}\n\nexport default function ProjectCard({\n  project,\n  onDeleteProject,\n  onAddCompany,\n  onDeleteCompany,\n  onDuplicateCompany,\n  onOpenEditor,\n}: Props) {\n  return (\n    <div className=\"card\">\n      {/* Project header */}\n      <div className=\"card-header\">\n        <div>\n          <div className=\"card-title\">{project.name}</div>\n          {project.description && (\n            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)', marginTop: 2 }}>\n              {project.description}\n            </p>\n          )}\n          <div style={styles.meta}>\n            <span>{project.companyCount} entreprise{project.companyCount !== 1 ? 's' : ''}</span>\n            {project.createdBy && <span>· Créé par {project.createdBy.fullName}</span>}\n          </div>\n        </div>\n        <div style={{ display: 'flex', gap: 'var(--space-2)', alignItems: 'center' }}>\n          <button className=\"btn btn-secondary btn-sm\" onClick={onAddCompany}>\n            + Entreprise\n          </button>\n          <button\n            className=\"btn btn-ghost btn-sm\"\n            style={{ color: 'var(--color-danger)' }}\n            onClick={onDeleteProject}\n            title=\"Supprimer le projet\"\n          >\n            🗑\n          </button>\n        </div>\n      </div>\n\n      {/* Companies grid */}\n      <div className=\"card-body\">\n        {project.companies.length === 0 ? (\n          <div className=\"empty-state\" style={{ padding: 'var(--space-8) var(--space-4)' }}>\n            <div style={{ fontSize: 32, marginBottom: 8, opacity: 0.3 }}>🏢</div>\n            <p style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>\n              Aucune entreprise dans ce projet.{' '}\n              <button\n                style={{ color: 'var(--color-primary)', fontWeight: 600, background: 'none', border: 'none', cursor: 'pointer' }}\n                onClick={onAddCompany}\n              >\n                Créer la première\n              </button>\n            </p>\n          </div>\n        ) : (\n          <div style={styles.grid}>\n            {project.companies.map((company: CompanySummary) => (\n              <CompanyCard\n                key={company.id}\n                company={company}\n                onOpen={() => onOpenEditor(company.id)}\n                onDelete={() => onDeleteCompany(company.id)}\n                onDuplicate={() => onDuplicateCompany(company.id)}\n              />\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  meta: {\n    display: 'flex',\n    gap: 'var(--space-2)',\n    fontSize: 'var(--text-xs)',\n    color: 'var(--color-text-muted)',\n    marginTop: 4,\n  },\n  grid: {\n    display: 'grid',\n    gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',\n    gap: 'var(--space-4)',\n  },\n}\n","import { useState, type FormEvent } from 'react'\nimport { projectApi } from '@/api/api'\nimport type { ProjectSummary } from '@/types'\n\ninterface Props {\n  onClose: () => void\n  onCreated: (project: ProjectSummary) => void\n}\n\nexport default function CreateProjectModal({ onClose, onCreated }: Props) {\n  const [name, setName] = useState('')\n  const [description, setDescription] = useState('')\n  const [isLoading, setIsLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n\n  async function handleSubmit(e: FormEvent) {\n    e.preventDefault()\n    setError(null)\n    setIsLoading(true)\n    try {\n      const project = await projectApi.create(name.trim(), description.trim())\n      onCreated(project)\n    } catch {\n      setError('Erreur lors de la création du projet.')\n    } finally {\n      setIsLoading(false)\n    }\n  }\n\n  return (\n    <div style={styles.overlay} onClick={onClose}>\n      <div style={styles.modal} onClick={(e) => e.stopPropagation()}>\n        <div style={styles.header}>\n          <h3 style={styles.title}>Nouveau projet</h3>\n          <button className=\"btn btn-ghost\" onClick={onClose}>✕</button>\n        </div>\n\n        {error && <div className=\"alert alert-error\" style={{ margin: '0 var(--space-6)' }}>{error}</div>}\n\n        <form onSubmit={handleSubmit} style={styles.form}>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"proj-name\">Nom du projet *</label>\n            <input\n              id=\"proj-name\"\n              className=\"form-input\"\n              value={name}\n              onChange={(e) => setName(e.target.value)}\n              placeholder=\"Ex : Plan de financement 2025\"\n              required\n              autoFocus\n            />\n          </div>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"proj-desc\">Description</label>\n            <textarea\n              id=\"proj-desc\"\n              className=\"form-input\"\n              value={description}\n              onChange={(e) => setDescription(e.target.value)}\n              placeholder=\"Description optionnelle…\"\n              rows={3}\n              style={{ resize: 'vertical' }}\n            />\n          </div>\n          <div style={styles.footer}>\n            <button type=\"button\" className=\"btn btn-secondary\" onClick={onClose}>Annuler</button>\n            <button type=\"submit\" className=\"btn btn-primary\" disabled={isLoading || !name.trim()}>\n              {isLoading ? 'Création…' : 'Créer le projet'}\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  overlay: {\n    position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)',\n    display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100,\n  },\n  modal: {\n    background: 'var(--color-surface)', borderRadius: 'var(--radius-lg)',\n    boxShadow: 'var(--shadow-lg)', width: '100%', maxWidth: 480,\n    display: 'flex', flexDirection: 'column', gap: 'var(--space-5)',\n    padding: 'var(--space-6)',\n  },\n  header: {\n    display: 'flex', alignItems: 'center', justifyContent: 'space-between',\n  },\n  title: {\n    fontSize: 'var(--text-lg)', fontWeight: 700,\n  },\n  form: {\n    display: 'flex', flexDirection: 'column', gap: 'var(--space-4)',\n  },\n  footer: {\n    display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-3)', paddingTop: 'var(--space-2)',\n  },\n}\n","import { useState, type FormEvent } from 'react'\nimport { companyApi } from '@/api/api'\nimport type { CompanySummary } from '@/types'\n\ninterface Props {\n  projectId: number\n  onClose: () => void\n  onCreated: (company: CompanySummary) => void\n}\n\nexport default function CreateCompanyModal({ projectId, onClose, onCreated }: Props) {\n  const [name, setName] = useState('')\n  const [secteur, setSecteur] = useState('')\n  const [promoteur, setPromoteur] = useState('')\n  const [isLoading, setIsLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n\n  async function handleSubmit(e: FormEvent) {\n    e.preventDefault()\n    setError(null)\n    setIsLoading(true)\n    try {\n      const company = await companyApi.create(projectId, name.trim(), secteur.trim(), promoteur.trim())\n      onCreated(company)\n    } catch {\n      setError(\"Erreur lors de la création de l'entreprise.\")\n    } finally {\n      setIsLoading(false)\n    }\n  }\n\n  return (\n    <div style={styles.overlay} onClick={onClose}>\n      <div style={styles.modal} onClick={(e) => e.stopPropagation()}>\n        <div style={styles.header}>\n          <h3 style={styles.title}>Nouvelle entreprise</h3>\n          <button className=\"btn btn-ghost\" onClick={onClose}>✕</button>\n        </div>\n\n        {error && <div className=\"alert alert-error\">{error}</div>}\n\n        <form onSubmit={handleSubmit} style={styles.form}>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"co-name\">Nom de l'entreprise *</label>\n            <input\n              id=\"co-name\"\n              className=\"form-input\"\n              value={name}\n              onChange={(e) => setName(e.target.value)}\n              placeholder=\"Ex : Élevage Miavaka\"\n              required\n              autoFocus\n            />\n          </div>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"co-secteur\">Secteur d'activité</label>\n            <input\n              id=\"co-secteur\"\n              className=\"form-input\"\n              value={secteur}\n              onChange={(e) => setSecteur(e.target.value)}\n              placeholder=\"Ex : Agriculture, Commerce, Services…\"\n            />\n          </div>\n          <div className=\"form-group\">\n            <label className=\"form-label\" htmlFor=\"co-promoteur\">Promoteur</label>\n            <input\n              id=\"co-promoteur\"\n              className=\"form-input\"\n              value={promoteur}\n              onChange={(e) => setPromoteur(e.target.value)}\n              placeholder=\"Nom du promoteur / porteur de projet\"\n            />\n          </div>\n          <div style={styles.footer}>\n            <button type=\"button\" className=\"btn btn-secondary\" onClick={onClose}>Annuler</button>\n            <button type=\"submit\" className=\"btn btn-primary\" disabled={isLoading || !name.trim()}>\n              {isLoading ? 'Création…' : 'Créer'}\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  overlay: {\n    position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)',\n    display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100,\n  },\n  modal: {\n    background: 'var(--color-surface)', borderRadius: 'var(--radius-lg)',\n    boxShadow: 'var(--shadow-lg)', width: '100%', maxWidth: 480,\n    display: 'flex', flexDirection: 'column', gap: 'var(--space-5)',\n    padding: 'var(--space-6)',\n  },\n  header: { display: 'flex', alignItems: 'center', justifyContent: 'space-between' },\n  title: { fontSize: 'var(--text-lg)', fontWeight: 700 },\n  form: { display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' },\n  footer: { display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-3)', paddingTop: 'var(--space-2)' },\n}\n","import { useState, useEffect, useCallback } from 'react'\nimport { useNavigate } from 'react-router-dom'\nimport { projectApi, companyApi } from '@/api/api'\nimport { syncService } from '@/services/syncService'\nimport { useNetworkStore } from '@/stores/networkStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport SyncIndicator from '@/components/ui/SyncIndicator'\nimport AppSidebar from '@/components/layout/AppSidebar'\nimport ProjectCard from '@/components/dashboard/ProjectCard'\nimport CreateProjectModal from '@/components/dashboard/CreateProjectModal'\nimport CreateCompanyModal from '@/components/dashboard/CreateCompanyModal'\nimport type { ProjectSummary } from '@/types'\n\nexport default function DashboardPage() {\n  const navigate = useNavigate()\n  const user = useAuthStore((s) => s.user)\n  const isOnline = useNetworkStore((s) => s.isOnline)\n\n  const [projects, setProjects] = useState<ProjectSummary[]>([])\n  const [isLoading, setIsLoading] = useState(true)\n  const [isOfflineMode, setIsOfflineMode] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [sidebarOpen, setSidebarOpen] = useState(false)\n\n  const [showCreateProject, setShowCreateProject] = useState(false)\n  const [createCompanyForProjectId, setCreateCompanyForProjectId] = useState<number | null>(null)\n\n  const loadProjects = useCallback(async () => {\n    if (isOnline) {\n      try {\n        const data = await projectApi.list()\n        setProjects(data)\n        setIsOfflineMode(false)\n        await syncService.saveDashboardCache(data)\n        setIsLoading(false)\n        return\n      } catch {\n        // Erreur réseau : basculer sur cache\n      }\n    }\n    const cached = await syncService.loadDashboardCache()\n    if (cached) {\n      setProjects(cached)\n      setIsOfflineMode(true)\n    } else {\n      setError('Pas de connexion et aucune donnée en cache.')\n    }\n    setIsLoading(false)\n  }, [isOnline])\n\n  useEffect(() => {\n    loadProjects()\n  }, [loadProjects])\n\n  async function handleDeleteProject(projectId: number) {\n    if (!confirm('Supprimer ce projet et toutes ses entreprises ?')) return\n    await projectApi.delete(projectId)\n    setProjects((prev) => prev.filter((p) => p.id !== projectId))\n  }\n\n  async function handleDeleteCompany(companyId: number, projectId: number) {\n    if (!confirm('Supprimer cette entreprise et toutes ses données ?')) return\n    await companyApi.delete(companyId)\n    setProjects((prev) =>\n      prev.map((p) =>\n        p.id === projectId\n          ? { ...p, companies: p.companies.filter((c) => c.id !== companyId), companyCount: p.companyCount - 1 }\n          : p,\n      ),\n    )\n  }\n\n  async function handleDuplicateCompany(companyId: number, projectId: number) {\n    const copy = await companyApi.duplicate(companyId)\n    setProjects((prev) =>\n      prev.map((p) =>\n        p.id === projectId\n          ? { ...p, companies: [...p.companies, copy], companyCount: p.companyCount + 1 }\n          : p,\n      ),\n    )\n  }\n\n  function handleOpenEditor(companyId: number) {\n    navigate(`/editor/${companyId}`)\n  }\n\n  return (\n    <div className=\"app-layout\">\n      <AppSidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />\n\n      <main className=\"main-content\">\n        {/* Mobile top bar */}\n        <div className=\"mobile-topbar\">\n          <button className=\"hamburger-btn\" onClick={() => setSidebarOpen(true)} aria-label=\"Ouvrir le menu\">\n            <i className=\"fas fa-bars\" />\n          </button>\n          <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ height: 32 }} />\n        </div>\n\n        {/* Header */}\n        <div className=\"flex items-center justify-between mb-6\">\n          <div>\n            <h2 className=\"section-title\" style={{ marginBottom: 4 }}>\n              Bonjour, {user?.firstName ?? 'Miavaka'} 👋\n            </h2>\n            <p className=\"section-subtitle\">Gérez vos projets et entreprises ici.</p>\n          </div>\n          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>\n            <SyncIndicator />\n            <button\n              className=\"btn btn-primary\"\n              onClick={() => setShowCreateProject(true)}\n              disabled={!isOnline}\n              title={!isOnline ? 'Connexion requise pour créer un projet' : undefined}\n            >\n              + Nouveau projet\n            </button>\n          </div>\n        </div>\n\n        {/* Bannière mode offline */}\n        {isOfflineMode && (\n          <div style={{ marginBottom: 'var(--space-4)', padding: 'var(--space-3) var(--space-4)', background: '#fffbeb', border: '1px solid #f5a623', borderRadius: 'var(--radius)', color: '#92400e', fontSize: 'var(--text-sm)', display: 'flex', alignItems: 'center', gap: 8 }}>\n            <i className=\"fas fa-database\" />\n            Mode hors-ligne — affichage du cache local. Reconnectez-vous pour voir les dernières modifications.\n          </div>\n        )}\n\n        {/* Error */}\n        {error && <div className=\"alert alert-error mb-4\">{error}</div>}\n\n        {/* Loading */}\n        {isLoading && (\n          <div className=\"loading-overlay\">\n            <div className=\"spinner\" />\n            Chargement des projets…\n          </div>\n        )}\n\n        {/* Empty state */}\n        {!isLoading && projects.length === 0 && (\n          <div className=\"empty-state\">\n            <div className=\"empty-state-icon\">📁</div>\n            <div className=\"empty-state-title\">Aucun projet</div>\n            <p className=\"empty-state-desc\">Créez votre premier projet pour commencer.</p>\n            <button\n              className=\"btn btn-primary\"\n              style={{ marginTop: 'var(--space-4)' }}\n              onClick={() => setShowCreateProject(true)}\n            >\n              + Créer un projet\n            </button>\n          </div>\n        )}\n\n        {/* Projects list */}\n        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n          {projects.map((project) => (\n            <ProjectCard\n              key={project.id}\n              project={project}\n              onOpenEditor={handleOpenEditor}\n              onDeleteProject={() => handleDeleteProject(project.id)}\n              onDeleteCompany={(companyId) => handleDeleteCompany(companyId, project.id)}\n              onDuplicateCompany={(companyId) => handleDuplicateCompany(companyId, project.id)}\n              onAddCompany={() => setCreateCompanyForProjectId(project.id)}\n            />\n          ))}\n        </div>\n\n        {/* Modals */}\n        {showCreateProject && (\n          <CreateProjectModal\n            onClose={() => setShowCreateProject(false)}\n            onCreated={(project) => {\n              setProjects((prev) => [...prev, project])\n              setShowCreateProject(false)\n            }}\n          />\n        )}\n        {createCompanyForProjectId !== null && (\n          <CreateCompanyModal\n            projectId={createCompanyForProjectId}\n            onClose={() => setCreateCompanyForProjectId(null)}\n            onCreated={(company) => {\n              setProjects((prev) =>\n                prev.map((p) =>\n                  p.id === createCompanyForProjectId\n                    ? { ...p, companies: [...p.companies, company], companyCount: p.companyCount + 1 }\n                    : p,\n                ),\n              )\n              setCreateCompanyForProjectId(null)\n            }}\n          />\n        )}\n      </main>\n    </div>\n  )\n}\n","import { create } from 'zustand'\nimport type {\n  CompanyFull,\n  Product,\n  Material,\n  StaffMember,\n  Expense,\n  Investment,\n  AdditionalFunding,\n  CompanySettings,\n} from '@/types'\n\ntype EditorSection =\n  | 'entreprise'\n  | 'products'\n  | 'materials'\n  | 'staff'\n  | 'expenses'\n  | 'investments'\n  | 'funding'\n  | 'results'\n  | 'cashflow'\n  | 'balance'\n  | 'profitability'\n  | 'financing'\n  | 'synthese'\n  | 'export'\n\ninterface CompanyState {\n  company: CompanyFull | null\n  activeSection: EditorSection\n  isSaving: boolean\n\n  // Load / reset\n  setCompany: (company: CompanyFull) => void\n  resetCompany: () => void\n\n  // Section navigation\n  setActiveSection: (section: EditorSection) => void\n\n  // Saving state\n  setSaving: (saving: boolean) => void\n\n  // Optimistic local updates (applied after API success)\n  updateSettings: (settings: CompanySettings) => void\n  updateCompanyMeta: (data: { name: string; secteur: string; promoteur: string }) => void\n\n  addProduct: (product: Product) => void\n  updateProduct: (id: number, data: Partial<Product>) => void\n  removeProduct: (id: number) => void\n\n  addMaterial: (material: Material) => void\n  updateMaterial: (id: number, data: Partial<Material>) => void\n  removeMaterial: (id: number) => void\n\n  addStaffMember: (staff: StaffMember) => void\n  updateStaffMember: (id: number, data: Partial<StaffMember>) => void\n  removeStaffMember: (id: number) => void\n\n  addExpense: (expense: Expense) => void\n  updateExpense: (id: number, data: Partial<Expense>) => void\n  removeExpense: (id: number) => void\n\n  addInvestment: (investment: Investment) => void\n  updateInvestment: (id: number, data: Partial<Investment>) => void\n  removeInvestment: (id: number) => void\n\n  updateAdditionalFundings: (fundings: AdditionalFunding[]) => void\n}\n\nexport const useCompanyStore = create<CompanyState>((set) => ({\n  company: null,\n  activeSection: 'entreprise',\n  isSaving: false,\n\n  setCompany: (company) => set({ company }),\n  resetCompany: () => set({ company: null, activeSection: 'entreprise' }),\n\n  setActiveSection: (section) => set({ activeSection: section }),\n  setSaving: (saving) => set({ isSaving: saving }),\n\n  updateSettings: (settings) =>\n    set((state) => ({\n      company: state.company ? { ...state.company, settings } : null,\n    })),\n\n  updateCompanyMeta: (data) =>\n    set((state) => ({\n      company: state.company ? { ...state.company, ...data } : null,\n    })),\n\n  // ─── Products ───────────────────────────────────────────────────────────\n  addProduct: (product) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, products: [...state.company.products, product] }\n        : null,\n    })),\n\n  updateProduct: (id, data) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            products: state.company.products.map((p) =>\n              p.id === id ? { ...p, ...data } : p,\n            ),\n          }\n        : null,\n    })),\n\n  removeProduct: (id) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            products: state.company.products.filter((p) => p.id !== id),\n          }\n        : null,\n    })),\n\n  // ─── Materials ──────────────────────────────────────────────────────────\n  addMaterial: (material) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, materials: [...state.company.materials, material] }\n        : null,\n    })),\n\n  updateMaterial: (id, data) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            materials: state.company.materials.map((m) =>\n              m.id === id ? { ...m, ...data } : m,\n            ),\n          }\n        : null,\n    })),\n\n  removeMaterial: (id) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            materials: state.company.materials.filter((m) => m.id !== id),\n          }\n        : null,\n    })),\n\n  // ─── Staff members ──────────────────────────────────────────────────────\n  addStaffMember: (staff) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, staffMembers: [...state.company.staffMembers, staff] }\n        : null,\n    })),\n\n  updateStaffMember: (id, data) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            staffMembers: state.company.staffMembers.map((s) =>\n              s.id === id ? { ...s, ...data } : s,\n            ),\n          }\n        : null,\n    })),\n\n  removeStaffMember: (id) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            staffMembers: state.company.staffMembers.filter((s) => s.id !== id),\n          }\n        : null,\n    })),\n\n  // ─── Expenses ───────────────────────────────────────────────────────────\n  addExpense: (expense) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, expenses: [...state.company.expenses, expense] }\n        : null,\n    })),\n\n  updateExpense: (id, data) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            expenses: state.company.expenses.map((e) =>\n              e.id === id ? { ...e, ...data } : e,\n            ),\n          }\n        : null,\n    })),\n\n  removeExpense: (id) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            expenses: state.company.expenses.filter((e) => e.id !== id),\n          }\n        : null,\n    })),\n\n  // ─── Investments ─────────────────────────────────────────────────────────\n  addInvestment: (investment) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, investments: [...state.company.investments, investment] }\n        : null,\n    })),\n\n  updateInvestment: (id, data) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            investments: state.company.investments.map((i) =>\n              i.id === id ? { ...i, ...data } : i,\n            ),\n          }\n        : null,\n    })),\n\n  removeInvestment: (id) =>\n    set((state) => ({\n      company: state.company\n        ? {\n            ...state.company,\n            investments: state.company.investments.filter((i) => i.id !== id),\n          }\n        : null,\n    })),\n\n  // ─── Additional fundings ─────────────────────────────────────────────────\n  updateAdditionalFundings: (fundings) =>\n    set((state) => ({\n      company: state.company\n        ? { ...state.company, additionalFundings: fundings }\n        : null,\n    })),\n}))\n","import { useNavigate } from 'react-router-dom'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { useAuthStore } from '@/stores/authStore'\n\ninterface SectionItem {\n  id: string\n  label: string\n  icon: string\n  description: string\n}\n\ninterface SectionGroup {\n  label: string\n  items: SectionItem[]\n}\n\nconst sectionGroups: SectionGroup[] = [\n  {\n    label: 'Données de base',\n    items: [\n      { id: 'entreprise',    label: 'Entreprise',          icon: 'fa-building-user',       description: 'Régime fiscal, paramètres de l\\'entreprise' },\n      { id: 'products',      label: 'Produits & Ventes',   icon: 'fa-chart-line',           description: \"Chiffre d\\'affaires prévisionnel\" },\n      { id: 'materials',     label: 'Matières premières',  icon: 'fa-boxes-stacked',        description: 'Coûts des matières' },\n      { id: 'staff',         label: 'Personnel',            icon: 'fa-users',                description: 'Masse salariale & taux de croissance' },\n      { id: 'expenses',      label: 'Autres charges',       icon: 'fa-receipt',              description: \"Charges d\\'exploitation\" },\n      { id: 'investments',   label: 'Investissements',      icon: 'fa-building',             description: 'Immobilisations & financement' },\n    ],\n  },\n  {\n    label: 'Tableaux financiers',\n    items: [\n      { id: 'results',       label: 'Compte de résultats', icon: 'fa-table-list',           description: 'Compte de résultat prévisionnel' },\n      { id: 'cashflow',      label: 'Trésorerie',           icon: 'fa-water',                description: 'Flux de trésorerie & remboursements' },\n      { id: 'balance',       label: 'Bilans',               icon: 'fa-scale-balanced',       description: 'Bilan prévisionnel 5 ans' },\n      { id: 'profitability', label: 'Rentabilité',          icon: 'fa-chart-pie',            description: 'VAN, TRI, ratios & indicateurs' },\n      { id: 'financing',     label: 'Plan de financement',  icon: 'fa-diagram-project',      description: 'Ressources et emplois' },\n    ],\n  },\n  {\n    label: 'Rapport',\n    items: [\n      { id: 'synthese',      label: 'Synthèse',             icon: 'fa-file-lines',           description: \"Vue d\\'ensemble complète du business plan\" },\n      { id: 'export',        label: 'Export Excel',         icon: 'fa-file-excel',           description: 'Export complet en fichier Excel' },\n    ],\n  },\n]\n\ninterface Props {\n  companyName: string\n  isOpen?: boolean\n  onClose?: () => void\n}\n\nexport default function EditorSidebar({ companyName: _companyName, isOpen = false, onClose }: Props) {\n  const navigate = useNavigate()\n  const activeSection = useCompanyStore((s) => s.activeSection)\n  const setActiveSection = useCompanyStore((s) => s.setActiveSection)\n  const logout = useAuthStore((s) => s.logout)\n\n  function handleLogout() {\n    logout()\n    navigate('/login', { replace: true })\n  }\n\n  function handleSectionClick(sectionId: string) {\n    setActiveSection(sectionId as Parameters<typeof setActiveSection>[0])\n    onClose?.()\n  }\n\n  return (\n    <>\n      {isOpen && (\n        <div className=\"sidebar-overlay\" onClick={onClose} />\n      )}\n    <aside className={`sidebar${isOpen ? ' sidebar--open' : ''}`}>\n      {/* Logo */}\n      <div className=\"sidebar-logo\" style={{ cursor: 'pointer' }} onClick={() => navigate('/')}>\n        <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ width: '60%', maxWidth: 150, display: 'block', margin: '0 auto 4px' }} />\n      </div>\n\n      {/* Sections nav */}\n      <nav className=\"sidebar-nav\" style={{ flex: 1, overflowY: 'auto' }}>\n        {sectionGroups.map((group) => (\n          <div key={group.label}>\n            <div className=\"sidebar-section-label\">{group.label}</div>\n            {group.items.map((section) => (\n              <button\n                key={section.id}\n                className={`sidebar-nav-item ${activeSection === section.id ? 'active' : ''}`}\n                style={{ width: '100%', textAlign: 'left', border: 'none', cursor: 'pointer' }}\n                onClick={() => handleSectionClick(section.id)}\n                title={section.description}\n              >\n                <i className={`fas ${section.icon}`} style={{ width: 18, textAlign: 'center', fontSize: 13, flexShrink: 0 }} />\n                {section.label}\n              </button>\n            ))}\n          </div>\n        ))}\n      </nav>\n\n      {/* Footer */}\n      <div className=\"sidebar-footer\">\n        <button\n          className=\"btn btn-ghost\"\n          style={{ width: '100%', justifyContent: 'center', color: '#9ca3af' }}\n          onClick={handleLogout}\n        >\n          Déconnexion\n        </button>\n      </div>\n    </aside>\n    </>\n  )\n}\n","/**\n * Couche API offline-aware.\n *\n * Pour chaque opération :\n *  - En ligne  → appel serveur + mise à jour du cache IndexedDB\n *  - Hors ligne → mise à jour du cache IndexedDB + ajout à la queue de sync\n *\n * Les composants utilisent ces fonctions au lieu des fonctions `api.ts` directement.\n */\nimport {\n  productApi,\n  materialApi,\n  staffMemberApi,\n  expenseApi,\n  investmentApi,\n  additionalFundingApi,\n  companyApi,\n} from '@/api/api'\nimport { syncService } from '@/services/syncService'\nimport { useNetworkStore } from '@/stores/networkStore'\nimport { generateTempId } from '@/db/localDb'\nimport type {\n  Product,\n  Material,\n  StaffMember,\n  Expense,\n  Investment,\n  AdditionalFunding,\n  CompanySettings,\n} from '@/types'\n\n// ─── Helper ───────────────────────────────────────────────────────────────────\n\nfunction isOnline(): boolean {\n  return useNetworkStore.getState().isOnline\n}\n\n// Valeurs par défaut pour les entités créées hors-ligne\nconst DEFAULTS = {\n  product: {\n    price: 0,\n    monthlyQty: Array<number>(12).fill(0),\n    growthRates: Array<number>(5).fill(0),\n    sortOrder: 0,\n  } satisfies Omit<Product, 'id' | 'name'>,\n\n  material: {\n    unitCost: 0,\n    monthlyQty: Array<number>(12).fill(0),\n    growthRates: Array<number>(5).fill(0),\n    sortOrder: 0,\n  } satisfies Omit<Material, 'id' | 'name'>,\n\n  staff: {\n    monthlySalary: 0,\n    headcount: 1,\n    chargesRate: 13,\n    growthRates: Array<number>(4).fill(0),\n    sortOrder: 0,\n  } satisfies Omit<StaffMember, 'id' | 'roleName'>,\n\n  expense: {\n    monthlyAmount: 0,\n    seasonality: Array<number>(12).fill(1),\n    inflationGrowth: Array<number>(5).fill(0),\n    sortOrder: 0,\n  } satisfies Omit<Expense, 'id' | 'name'>,\n\n  investment: {\n    amount: 0,\n    usefulLife: 5,\n    financedEquity: 0,\n    financedLoan: 0,\n    financedGrant: 0,\n    loanRate: 0,\n    loanYears: 5,\n    sortOrder: 0,\n  } satisfies Omit<Investment, 'id' | 'name'>,\n}\n\n// ─── Produits ─────────────────────────────────────────────────────────────────\n\nexport const offlineProductApi = {\n  async create(\n    companyId: number,\n    data: { name: string; price?: number; monthlyQty?: number[]; growthRates?: number[] },\n  ): Promise<Product> {\n    if (isOnline()) {\n      const product = await productApi.create(companyId, data)\n      await syncService.addEntityToCache(companyId, 'product', product)\n      return product\n    }\n    const id = generateTempId()\n    const product: Product = { ...DEFAULTS.product, ...data, id }\n    await syncService.addEntityToCache(companyId, 'product', product)\n    await syncService.enqueue({\n      method: 'POST',\n      path: `/companies/${companyId}/products`,\n      body: data,\n      tempId: id,\n      entity: 'product',\n      companyId,\n    })\n    return product\n  },\n\n  async update(id: number, companyId: number, data: Partial<Product>): Promise<Product> {\n    if (isOnline()) {\n      const product = await productApi.update(id, data)\n      await syncService.updateEntityInCache(companyId, 'product', id, product)\n      return product\n    }\n    await syncService.updateEntityInCache(companyId, 'product', id, data)\n    const cached = await syncService.loadCompanyCache(companyId)\n    const found = cached?.products.find((p) => p.id === id)\n    const updated: Product = { ...(found ?? { id, ...DEFAULTS.product, name: '' }), ...data }\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/products/${id}`,\n      body: data,\n      entity: 'product',\n      companyId,\n    })\n    return updated\n  },\n\n  async delete(id: number, companyId: number): Promise<void> {\n    await syncService.removeEntityFromCache(companyId, 'product', id)\n    if (isOnline()) {\n      await productApi.delete(id)\n    } else if (id > 0) {\n      // Ne pas queuer les suppressions d'entités jamais synchronisées (ID négatif)\n      await syncService.enqueue({\n        method: 'DELETE',\n        path: `/products/${id}`,\n        body: null,\n        entity: 'product',\n        companyId,\n      })\n    }\n  },\n}\n\n// ─── Matières premières ───────────────────────────────────────────────────────\n\nexport const offlineMaterialApi = {\n  async create(\n    companyId: number,\n    data: { name: string; unitCost?: number; monthlyQty?: number[]; growthRates?: number[] },\n  ): Promise<Material> {\n    if (isOnline()) {\n      const mat = await materialApi.create(companyId, data)\n      await syncService.addEntityToCache(companyId, 'material', mat)\n      return mat\n    }\n    const id = generateTempId()\n    const mat: Material = { ...DEFAULTS.material, ...data, id }\n    await syncService.addEntityToCache(companyId, 'material', mat)\n    await syncService.enqueue({\n      method: 'POST',\n      path: `/companies/${companyId}/materials`,\n      body: data,\n      tempId: id,\n      entity: 'material',\n      companyId,\n    })\n    return mat\n  },\n\n  async update(id: number, companyId: number, data: Partial<Material>): Promise<Material> {\n    if (isOnline()) {\n      const mat = await materialApi.update(id, data)\n      await syncService.updateEntityInCache(companyId, 'material', id, mat)\n      return mat\n    }\n    await syncService.updateEntityInCache(companyId, 'material', id, data)\n    const cached = await syncService.loadCompanyCache(companyId)\n    const found = cached?.materials.find((m) => m.id === id)\n    const updated: Material = { ...(found ?? { id, ...DEFAULTS.material, name: '' }), ...data }\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/materials/${id}`,\n      body: data,\n      entity: 'material',\n      companyId,\n    })\n    return updated\n  },\n\n  async delete(id: number, companyId: number): Promise<void> {\n    await syncService.removeEntityFromCache(companyId, 'material', id)\n    if (isOnline()) {\n      await materialApi.delete(id)\n    } else if (id > 0) {\n      await syncService.enqueue({\n        method: 'DELETE',\n        path: `/materials/${id}`,\n        body: null,\n        entity: 'material',\n        companyId,\n      })\n    }\n  },\n}\n\n// ─── Personnel ────────────────────────────────────────────────────────────────\n\nexport const offlineStaffApi = {\n  async create(\n    companyId: number,\n    data: { roleName: string; monthlySalary?: number; headcount?: number; chargesRate?: number },\n  ): Promise<StaffMember> {\n    if (isOnline()) {\n      const staff = await staffMemberApi.create(companyId, data)\n      await syncService.addEntityToCache(companyId, 'staff', staff)\n      return staff\n    }\n    const id = generateTempId()\n    const staff: StaffMember = { ...DEFAULTS.staff, ...data, id }\n    await syncService.addEntityToCache(companyId, 'staff', staff)\n    await syncService.enqueue({\n      method: 'POST',\n      path: `/companies/${companyId}/staff-members`,\n      body: data,\n      tempId: id,\n      entity: 'staff',\n      companyId,\n    })\n    return staff\n  },\n\n  async update(id: number, companyId: number, data: Partial<StaffMember>): Promise<StaffMember> {\n    if (isOnline()) {\n      const staff = await staffMemberApi.update(id, data)\n      await syncService.updateEntityInCache(companyId, 'staff', id, staff)\n      return staff\n    }\n    await syncService.updateEntityInCache(companyId, 'staff', id, data)\n    const cached = await syncService.loadCompanyCache(companyId)\n    const found = cached?.staffMembers.find((s) => s.id === id)\n    const updated: StaffMember = { ...(found ?? { id, ...DEFAULTS.staff, roleName: '' }), ...data }\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/staff-members/${id}`,\n      body: data,\n      entity: 'staff',\n      companyId,\n    })\n    return updated\n  },\n\n  async delete(id: number, companyId: number): Promise<void> {\n    await syncService.removeEntityFromCache(companyId, 'staff', id)\n    if (isOnline()) {\n      await staffMemberApi.delete(id)\n    } else if (id > 0) {\n      await syncService.enqueue({\n        method: 'DELETE',\n        path: `/staff-members/${id}`,\n        body: null,\n        entity: 'staff',\n        companyId,\n      })\n    }\n  },\n}\n\n// ─── Charges ──────────────────────────────────────────────────────────────────\n\nexport const offlineExpenseApi = {\n  async create(\n    companyId: number,\n    data: { name: string; monthlyAmount?: number; seasonality?: number[]; inflationGrowth?: number[] },\n  ): Promise<Expense> {\n    if (isOnline()) {\n      const exp = await expenseApi.create(companyId, data)\n      await syncService.addEntityToCache(companyId, 'expense', exp)\n      return exp\n    }\n    const id = generateTempId()\n    const exp: Expense = { ...DEFAULTS.expense, ...data, id }\n    await syncService.addEntityToCache(companyId, 'expense', exp)\n    await syncService.enqueue({\n      method: 'POST',\n      path: `/companies/${companyId}/expenses`,\n      body: data,\n      tempId: id,\n      entity: 'expense',\n      companyId,\n    })\n    return exp\n  },\n\n  async update(id: number, companyId: number, data: Partial<Expense>): Promise<Expense> {\n    if (isOnline()) {\n      const exp = await expenseApi.update(id, data)\n      await syncService.updateEntityInCache(companyId, 'expense', id, exp)\n      return exp\n    }\n    await syncService.updateEntityInCache(companyId, 'expense', id, data)\n    const cached = await syncService.loadCompanyCache(companyId)\n    const found = cached?.expenses.find((e) => e.id === id)\n    const updated: Expense = { ...(found ?? { id, ...DEFAULTS.expense, name: '' }), ...data }\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/expenses/${id}`,\n      body: data,\n      entity: 'expense',\n      companyId,\n    })\n    return updated\n  },\n\n  async delete(id: number, companyId: number): Promise<void> {\n    await syncService.removeEntityFromCache(companyId, 'expense', id)\n    if (isOnline()) {\n      await expenseApi.delete(id)\n    } else if (id > 0) {\n      await syncService.enqueue({\n        method: 'DELETE',\n        path: `/expenses/${id}`,\n        body: null,\n        entity: 'expense',\n        companyId,\n      })\n    }\n  },\n}\n\n// ─── Investissements ──────────────────────────────────────────────────────────\n\nexport const offlineInvestmentApi = {\n  async create(\n    companyId: number,\n    data: { name: string; amount?: number; usefulLife?: number; financedEquity?: number; financedLoan?: number; financedGrant?: number; loanRate?: number; loanYears?: number },\n  ): Promise<Investment> {\n    if (isOnline()) {\n      const inv = await investmentApi.create(companyId, data)\n      await syncService.addEntityToCache(companyId, 'investment', inv)\n      return inv\n    }\n    const id = generateTempId()\n    const inv: Investment = { ...DEFAULTS.investment, ...data, id }\n    await syncService.addEntityToCache(companyId, 'investment', inv)\n    await syncService.enqueue({\n      method: 'POST',\n      path: `/companies/${companyId}/investments`,\n      body: data,\n      tempId: id,\n      entity: 'investment',\n      companyId,\n    })\n    return inv\n  },\n\n  async update(id: number, companyId: number, data: Partial<Investment>): Promise<Investment> {\n    if (isOnline()) {\n      const inv = await investmentApi.update(id, data)\n      await syncService.updateEntityInCache(companyId, 'investment', id, inv)\n      return inv\n    }\n    await syncService.updateEntityInCache(companyId, 'investment', id, data)\n    const cached = await syncService.loadCompanyCache(companyId)\n    const found = cached?.investments.find((i) => i.id === id)\n    const updated: Investment = { ...(found ?? { id, ...DEFAULTS.investment, name: '' }), ...data }\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/investments/${id}`,\n      body: data,\n      entity: 'investment',\n      companyId,\n    })\n    return updated\n  },\n\n  async delete(id: number, companyId: number): Promise<void> {\n    await syncService.removeEntityFromCache(companyId, 'investment', id)\n    if (isOnline()) {\n      await investmentApi.delete(id)\n    } else if (id > 0) {\n      await syncService.enqueue({\n        method: 'DELETE',\n        path: `/investments/${id}`,\n        body: null,\n        entity: 'investment',\n        companyId,\n      })\n    }\n  },\n}\n\n// ─── Apports complémentaires ──────────────────────────────────────────────────\n\nexport const offlineFundingApi = {\n  async update(companyId: number, data: AdditionalFunding[]): Promise<AdditionalFunding[]> {\n    if (isOnline()) {\n      const result = await additionalFundingApi.update(companyId, data)\n      await syncService.patchCompanyCache(companyId, (c) => {\n        c.additionalFundings = result\n        return c\n      })\n      return result\n    }\n    // Offline : remplacer entièrement dans le cache\n    await syncService.patchCompanyCache(companyId, (c) => {\n      c.additionalFundings = data\n      return c\n    })\n    await syncService.enqueue({\n      method: 'PUT',\n      path: `/companies/${companyId}/additional-fundings`,\n      body: data,\n      entity: 'funding',\n      companyId,\n    })\n    return data\n  },\n}\n\n// ─── Informations entreprise ──────────────────────────────────────────────────\n\nexport const offlineCompanyApi = {\n  async updateMeta(\n    companyId: number,\n    data: { name: string; secteur: string; promoteur: string },\n  ): Promise<{ name: string; secteur: string; promoteur: string }> {\n    if (isOnline()) {\n      const result = await companyApi.updateMeta(companyId, data)\n      await syncService.patchCompanyCache(companyId, (c) => {\n        c.name = data.name\n        c.secteur = data.secteur\n        c.promoteur = data.promoteur\n        return c\n      })\n      return result as unknown as { name: string; secteur: string; promoteur: string }\n    }\n    await syncService.patchCompanyCache(companyId, (c) => {\n      c.name = data.name\n      c.secteur = data.secteur\n      c.promoteur = data.promoteur\n      return c\n    })\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/companies/${companyId}/meta`,\n      body: data,\n      entity: 'settings',\n      companyId,\n    })\n    return data\n  },\n}\n\n// ─── Paramètres ───────────────────────────────────────────────────────────────\n\nexport const offlineSettingsApi = {\n  async update(companyId: number, data: CompanySettings): Promise<CompanySettings> {\n    if (isOnline()) {\n      const result = await companyApi.updateSettings(companyId, data)\n      await syncService.patchCompanyCache(companyId, (c) => {\n        c.settings = result\n        return c\n      })\n      return result\n    }\n    await syncService.patchCompanyCache(companyId, (c) => {\n      c.settings = data\n      return c\n    })\n    await syncService.enqueue({\n      method: 'PATCH',\n      path: `/companies/${companyId}/settings`,\n      body: data,\n      entity: 'settings',\n      companyId,\n    })\n    const cached = await syncService.loadCompanyCache(companyId)\n    return (cached?.settings ?? data) as CompanySettings\n  },\n}\n","import { useState } from 'react'\n\ninterface HelpButtonProps {\n  title: string\n  content: string\n}\n\nexport default function HelpButton({ title, content }: HelpButtonProps) {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div style={{ position: 'relative', display: 'inline-block' }}>\n      <button\n        type=\"button\"\n        onClick={() => setOpen((v) => !v)}\n        title=\"Aide\"\n        style={{\n          width: 22,\n          height: 22,\n          borderRadius: '50%',\n          border: '1.5px solid var(--color-border)',\n          background: 'var(--color-surface)',\n          color: 'var(--color-text-muted)',\n          fontSize: 12,\n          fontWeight: 700,\n          cursor: 'pointer',\n          display: 'inline-flex',\n          alignItems: 'center',\n          justifyContent: 'center',\n          lineHeight: 1,\n          flexShrink: 0,\n          transition: 'border-color 0.15s, color 0.15s',\n        }}\n        onMouseEnter={(e) => {\n          const btn = e.currentTarget\n          btn.style.borderColor = 'var(--color-primary)'\n          btn.style.color = 'var(--color-primary)'\n        }}\n        onMouseLeave={(e) => {\n          const btn = e.currentTarget\n          btn.style.borderColor = 'var(--color-border)'\n          btn.style.color = 'var(--color-text-muted)'\n        }}\n      >\n        ?\n      </button>\n\n      {open && (\n        <div\n          style={{\n            position: 'absolute',\n            top: '100%',\n            left: 0,\n            marginTop: 8,\n            zIndex: 50,\n            minWidth: 280,\n            maxWidth: 360,\n            background: 'var(--color-surface)',\n            border: '1px solid var(--color-border)',\n            borderRadius: 'var(--radius-md)',\n            boxShadow: '0 4px 16px rgba(0,0,0,0.12)',\n            padding: 'var(--space-4)',\n          }}\n        >\n          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 'var(--space-2)' }}>\n            <strong style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text)' }}>{title}</strong>\n            <button\n              type=\"button\"\n              onClick={() => setOpen(false)}\n              style={{\n                background: 'none',\n                border: 'none',\n                cursor: 'pointer',\n                fontSize: 14,\n                color: 'var(--color-text-muted)',\n                padding: '0 2px',\n                lineHeight: 1,\n              }}\n            >\n              ✕\n            </button>\n          </div>\n          <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', lineHeight: 1.7, whiteSpace: 'pre-line' }}>\n            {content}\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n","import { useState, useEffect, useRef } from 'react'\n\ninterface NumInputProps {\n  defaultValue: number\n  onBlur: (value: number) => void\n  className?: string\n  style?: React.CSSProperties\n  min?: number\n  step?: number\n  placeholder?: string\n  disabled?: boolean\n}\n\nfunction parseNum(raw: string): number {\n  // Remove all spaces (including non-breaking spaces), replace comma with dot\n  const cleaned = raw.replace(/[\\s ]/g, '').replace(',', '.')\n  return parseFloat(cleaned) || 0\n}\n\nexport default function NumInput({\n  defaultValue,\n  onBlur,\n  className,\n  style,\n  min,\n  step,\n  placeholder,\n  disabled,\n}: NumInputProps) {\n  const isDecimal = step !== undefined && Number(step) < 1\n  const [display, setDisplay] = useState<string>(() => {\n    if (isDecimal) {\n      return new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 2 }).format(defaultValue)\n    }\n    return new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 0 }).format(defaultValue)\n  })\n  const [editing, setEditing] = useState(false)\n  const prevDefault = useRef(defaultValue)\n\n  useEffect(() => {\n    if (!editing && defaultValue !== prevDefault.current) {\n      prevDefault.current = defaultValue\n      if (isDecimal) {\n        setDisplay(new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 2 }).format(defaultValue))\n      } else {\n        setDisplay(new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 0 }).format(defaultValue))\n      }\n    }\n  }, [defaultValue, editing, isDecimal])\n\n  function handleFocus(e: React.FocusEvent<HTMLInputElement>) {\n    setEditing(true)\n    // Show raw number for clean editing\n    setDisplay(String(defaultValue))\n    e.target.select()\n  }\n\n  function handleBlur(e: React.FocusEvent<HTMLInputElement>) {\n    setEditing(false)\n    const parsed = parseNum(e.target.value)\n    // Format with thousands separator\n    if (isDecimal) {\n      setDisplay(new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 2 }).format(parsed))\n    } else {\n      setDisplay(new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 0 }).format(parsed))\n    }\n    onBlur(parsed)\n  }\n\n  return (\n    <input\n      type=\"text\"\n      inputMode={isDecimal ? 'decimal' : 'numeric'}\n      className={className}\n      style={style}\n      value={display}\n      placeholder={placeholder}\n      disabled={disabled}\n      min={min}\n      onChange={(e) => setDisplay(e.target.value)}\n      onFocus={handleFocus}\n      onBlur={handleBlur}\n    />\n  )\n}\n","import { useState, type FormEvent } from 'react'\nimport { offlineSettingsApi, offlineCompanyApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport type { CompanySettings } from '@/types'\nimport HelpButton from '@/components/ui/HelpButton'\nimport NumInput from '@/components/ui/NumInput'\n\nconst DEFAULT_SETTINGS: CompanySettings = {\n  infl2: 3, infl3: 3, infl4: 3, infl5: 3,\n  discountRate: 10,\n  taxRegime: 'IR',\n  taxRate: 20,\n  taxRateIs: 20,\n  fondsRoulement: 0,\n}\n\nexport default function SettingsSection() {\n  const company     = useCompanyStore((s) => s.company)!\n  const updateSettings    = useCompanyStore((s) => s.updateSettings)\n  const updateCompanyMeta = useCompanyStore((s) => s.updateCompanyMeta)\n\n  const [form, setForm] = useState<CompanySettings>(company.settings ?? DEFAULT_SETTINGS)\n  const [meta, setMeta] = useState({\n    name:      company.name      ?? '',\n    secteur:   company.secteur   ?? '',\n    promoteur: company.promoteur ?? '',\n  })\n  const [isSaving, setIsSaving] = useState(false)\n  const [saved, setSaved]       = useState(false)\n\n  function handleChange(field: keyof CompanySettings, value: string) {\n    setForm((prev) => ({\n      ...prev,\n      [field]: field === 'taxRegime' ? value : parseFloat(value) || 0,\n    }))\n    setSaved(false)\n  }\n\n  function handleMeta(field: keyof typeof meta, value: string) {\n    setMeta((prev) => ({ ...prev, [field]: value }))\n    setSaved(false)\n  }\n\n  async function handleSave(e: FormEvent) {\n    e.preventDefault()\n    setIsSaving(true)\n    try {\n      const [updatedSettings] = await Promise.all([\n        offlineSettingsApi.update(company.id, form),\n        offlineCompanyApi.updateMeta(company.id, meta),\n      ])\n      updateSettings(updatedSettings)\n      updateCompanyMeta(meta)\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2000)\n    } finally {\n      setIsSaving(false)\n    }\n  }\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n          <div>\n            <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n              <i className=\"fas fa-building-user\" style={{ marginRight: 8, color: '#f5a623' }} />\n              Entreprise\n            </h3>\n            <p className=\"section-subtitle\">\n              {meta.name}\n              {meta.secteur   ? ` · ${meta.secteur}`              : ''}\n              {meta.promoteur ? ` · Promoteur : ${meta.promoteur}` : ''}\n            </p>\n          </div>\n          <HelpButton\n            title=\"Paramètres entreprise\"\n            content={\"Définissez les informations de base de votre entreprise.\\n\\n => Régime fiscal : IR = Impôt sur le Revenu (entreprise individuelle), IS = Impôt sur les Sociétés.\\n\\n=> Taux d'actualisation : Taux utilisé pour calculer la VAN. En général 10% pour Madagascar.\\n\\n=> Fonds de roulement : Capital de départ supplémentaire pour couvrir les premiers mois d'exploitation.\"}\n          />\n        </div>\n        {saved && <span className=\"badge badge-success\">✓ Enregistré</span>}\n      </div>\n\n      <form onSubmit={handleSave}>\n        <div style={styles.grid}>\n\n          {/* ── Informations entreprise (EN PREMIER) ── */}\n          <div className=\"card\">\n            <div className=\"card-header\">\n              <span className=\"card-title\" style={{ fontSize: 'var(--text-md)' }}>\n                Informations entreprise\n              </span>\n            </div>\n            <div className=\"card-body\" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>\n              <div className=\"form-group\">\n                <label className=\"form-label\">Nom de l'entreprise</label>\n                <input\n                  className=\"form-input\"\n                  value={meta.name}\n                  placeholder=\"Ex : Boulangerie Rabe\"\n                  onChange={(e) => handleMeta('name', e.target.value)}\n                />\n              </div>\n              <div className=\"form-group\">\n                <label className=\"form-label\">Secteur d'activité</label>\n                <input\n                  className=\"form-input\"\n                  value={meta.secteur}\n                  placeholder=\"Ex : Commerce, Agriculture…\"\n                  onChange={(e) => handleMeta('secteur', e.target.value)}\n                />\n              </div>\n              <div className=\"form-group\">\n                <label className=\"form-label\">Promoteur / Responsable</label>\n                <input\n                  className=\"form-input\"\n                  value={meta.promoteur}\n                  placeholder=\"Ex : Rabe Jean\"\n                  onChange={(e) => handleMeta('promoteur', e.target.value)}\n                />\n              </div>\n            </div>\n          </div>\n\n          {/* ── Régime fiscal ── */}\n          <div className=\"card\">\n            <div className=\"card-header\">\n              <span className=\"card-title\" style={{ fontSize: 'var(--text-md)' }}>Régime fiscal</span>\n            </div>\n            <div className=\"card-body\" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>\n              <div className=\"form-group\">\n                <label className=\"form-label\">Régime d'imposition</label>\n                <select\n                  className=\"form-select\"\n                  value={form.taxRegime}\n                  onChange={(e) => handleChange('taxRegime', e.target.value)}\n                >\n                  <option value=\"IR\">IR – Impôt sur le Revenu</option>\n                  <option value=\"IS\">IS – Impôt sur les Sociétés</option>\n                </select>\n              </div>\n              <div className=\"flex items-center justify-between gap-4\">\n                <label className=\"form-label\" style={{ marginBottom: 0 }}>Taux IR</label>\n                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>\n                  <input type=\"number\" className=\"form-input\" style={{ width: 80, textAlign: 'right' }}\n                    step=\"0.5\" min=\"0\" max=\"100\" value={form.taxRate}\n                    onChange={(e) => handleChange('taxRate', e.target.value)} />\n                  <span style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>%</span>\n                </div>\n              </div>\n              <div className=\"flex items-center justify-between gap-4\">\n                <label className=\"form-label\" style={{ marginBottom: 0 }}>Taux IS</label>\n                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>\n                  <input type=\"number\" className=\"form-input\" style={{ width: 80, textAlign: 'right' }}\n                    step=\"0.5\" min=\"0\" max=\"100\" value={form.taxRateIs}\n                    onChange={(e) => handleChange('taxRateIs', e.target.value)} />\n                  <span style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>%</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          {/* ── Paramètres financiers ── */}\n          <div className=\"card\">\n            <div className=\"card-header\">\n              <span className=\"card-title\" style={{ fontSize: 'var(--text-md)' }}>Paramètres financiers</span>\n            </div>\n            <div className=\"card-body\" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>\n              <div className=\"flex items-center justify-between gap-4\">\n                <label className=\"form-label\" style={{ marginBottom: 0 }}>\n                  <i className=\"fas fa-percent\" style={{ marginRight: 6, fontSize: 11, color: 'var(--color-accent)' }} />\n                  Taux d'actualisation (VAN)\n                </label>\n                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>\n                  <input type=\"number\" className=\"form-input\" style={{ width: 80, textAlign: 'right' }}\n                    step=\"0.5\" min=\"0\" max=\"100\" value={form.discountRate}\n                    onChange={(e) => handleChange('discountRate', e.target.value)} />\n                  <span style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>%</span>\n                </div>\n              </div>\n              <div className=\"flex items-center justify-between gap-4\">\n                <label className=\"form-label\" style={{ marginBottom: 0 }}>\n                  <i className=\"fas fa-coins\" style={{ marginRight: 6, fontSize: 11, color: 'var(--color-accent)' }} />\n                  Fonds de roulement initial\n                </label>\n                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>\n                  <NumInput className=\"form-input\" style={{ width: 120, textAlign: 'right' }}\n                    step={1000} min={0} defaultValue={form.fondsRoulement}\n                    onBlur={(v) => handleChange('fondsRoulement', String(v))} />\n                  <span style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>Ar</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n        </div>\n\n        <div style={{ marginTop: 'var(--space-6)', display: 'flex', justifyContent: 'flex-end' }}>\n          <button type=\"submit\" className=\"btn btn-primary btn-lg\" disabled={isSaving}>\n            {isSaving ? 'Enregistrement…' : '💾 Enregistrer'}\n          </button>\n        </div>\n      </form>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  grid: {\n    display: 'grid',\n    gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',\n    gap: 'var(--space-4)',\n  },\n}\n","import { useState, useRef } from 'react'\nimport { offlineProductApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary } from '@/calculations/calculations'\nimport type { Product } from '@/types'\nimport NumInput from '@/components/ui/NumInput'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst MONTHS = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc']\nconst GROWTH_YEARS = ['An 2','An 3','An 4','An 5']\n\nexport default function ProductsSection() {\n  const company       = useCompanyStore((s) => s.company)!\n  const addProduct    = useCompanyStore((s) => s.addProduct)\n  const updateProduct = useCompanyStore((s) => s.updateProduct)\n  const removeProduct = useCompanyStore((s) => s.removeProduct)\n\n  const [isAdding, setIsAdding] = useState(false)\n  const [newName, setNewName]   = useState('')\n  const [saving, setSaving]     = useState(false)\n  const [saved, setSaved]       = useState(false)\n  const arrayRefs = useRef<Record<string, HTMLInputElement | null>>({})\n\n  async function handleAddProduct() {\n    if (!newName.trim()) return\n    setIsAdding(true)\n    try {\n      const p = await offlineProductApi.create(company.id, { name: newName.trim() })\n      addProduct(p)\n      setNewName('')\n    } finally { setIsAdding(false) }\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm('Supprimer ce produit ?')) return\n    await offlineProductApi.delete(id, company.id)\n    removeProduct(id)\n  }\n\n  async function handleField(product: Product, field: keyof Product, value: unknown) {\n    const updated = await offlineProductApi.update(product.id, company.id, { [field]: value } as Partial<Product>)\n    updateProduct(product.id, updated)\n  }\n\n  async function handleQty(productId: number, idx: number, val: number) {\n    const fresh = useCompanyStore.getState().company?.products.find((p) => p.id === productId)\n    if (!fresh) return\n    const qty = [...fresh.monthlyQty]\n    qty[idx] = val\n    const updated = await offlineProductApi.update(productId, company.id, { monthlyQty: qty })\n    updateProduct(productId, updated)\n  }\n\n  async function handleGrowth(productId: number, idx: number, val: number) {\n    const fresh = useCompanyStore.getState().company?.products.find((p) => p.id === productId)\n    if (!fresh) return\n    const rates = [...fresh.growthRates]\n    rates[idx] = val\n    const updated = await offlineProductApi.update(productId, company.id, { growthRates: rates })\n    updateProduct(productId, updated)\n  }\n\n  async function handleSaveAll() {\n    setSaving(true)\n    try {\n      for (const product of useCompanyStore.getState().company?.products ?? []) {\n        const monthlyQty = Array.from({ length: 12 }, (_, i) =>\n          parseInt(arrayRefs.current[`${product.id}-qty-${i}`]?.value || '0', 10) || 0,\n        )\n        const growthRates = [\n          ...Array.from({ length: 4 }, (_, i) =>\n            parseFloat(arrayRefs.current[`${product.id}-growth-${i}`]?.value || '0') || 0,\n          ),\n          product.growthRates[4] ?? 0,\n        ]\n        const updated = await offlineProductApi.update(product.id, company.id, { monthlyQty, growthRates })\n        updateProduct(product.id, updated)\n      }\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2500)\n    } finally {\n      setSaving(false)\n    }\n  }\n\n  const totalQty     = (p: Product) => p.monthlyQty.reduce((a, b) => a + b, 0)\n  const totalRevenue = (p: Product) => totalQty(p) * p.price\n\n  return (\n    <div>\n      <div style={{ marginBottom: 'var(--space-5)', display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n            <i className=\"fas fa-chart-line\" style={{ marginRight: 8, color: 'var(--color-primary)' }} />\n            Produits & Chiffre d'affaires\n          </h3>\n          <p className=\"section-subtitle\">Prix unitaire, quantités mensuelles et taux de croissance An 2-5.</p>\n        </div>\n        <HelpButton\n          title=\"Produits & Ventes\"\n          content={\"Saisissez vos produits ou services avec leur prix unitaire.\\n\\n=> Quantités mensuelles : Nombre d'unités vendues par mois pour la première année.\\n\\n=> Taux de croissance annuel : Pourcentage d'augmentation des ventes d'une année à l'autre (ex: 5% par an).\"}\n        />\n      </div>\n\n      {/* Barre ajout + bouton enregistrer unique */}\n      <div style={addBarStyle}>\n        <input\n          className=\"form-input\"\n          style={{ flex: 1, maxWidth: 320 }}\n          placeholder=\"Nom du produit / service…\"\n          value={newName}\n          onChange={(e) => setNewName(e.target.value)}\n          onKeyDown={(e) => e.key === 'Enter' && handleAddProduct()}\n        />\n        <button className=\"btn btn-primary\" onClick={handleAddProduct} disabled={isAdding || !newName.trim()}>\n          <i className=\"fas fa-plus\" style={{ marginRight: 6 }} />\n          {isAdding ? 'Ajout…' : 'Ajouter'}\n        </button>\n        {company.products.length > 0 && (\n          <button\n            type=\"button\"\n            onClick={handleSaveAll}\n            disabled={saving}\n            style={saved ? saveAllBtnOk : saveAllBtn}\n          >\n            <i className={`fas ${saved ? 'fa-check-circle' : 'fa-floppy-disk'}`} style={{ marginRight: 6 }} />\n            {saving ? 'Enregistrement…' : saved ? 'Enregistré !' : 'Enregistrer tout'}\n          </button>\n        )}\n      </div>\n\n      {company.products.length === 0 && (\n        <div className=\"empty-state\">\n          <div className=\"empty-state-icon\"><i className=\"fas fa-chart-line\" /></div>\n          <div className=\"empty-state-title\">Aucun produit</div>\n          <p className=\"empty-state-desc\">Ajoutez vos produits ou services ci-dessus.</p>\n        </div>\n      )}\n\n      {company.products.map((product) => (\n        <div key={product.id} className=\"card\" style={{ marginBottom: 'var(--space-5)' }}>\n          <div className=\"card-header\">\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, flexWrap: 'wrap' }}>\n              <input\n                className=\"form-input\"\n                style={{ fontWeight: 600, maxWidth: 240 }}\n                defaultValue={product.name}\n                onBlur={(e) => handleField(product, 'name', e.target.value)}\n              />\n              <label className=\"form-label\" style={{ marginBottom: 0, whiteSpace: 'nowrap' }}>Prix unitaire</label>\n              <NumInput\n                className=\"form-input\"\n                style={{ width: 130, textAlign: 'right' }}\n                defaultValue={product.price}\n                min={0}\n                onBlur={(v) => handleField(product, 'price', v)}\n              />\n              <span style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>Ar</span>\n            </div>\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>\n              <div className=\"kpi-card\" style={{ padding: '4px 12px' }}>\n                <div className=\"kpi-label\">CA An 1</div>\n                <div className=\"kpi-value\" style={{ fontSize: 'var(--text-base)' }}>{formatAriary(totalRevenue(product))}</div>\n              </div>\n              <button\n                onClick={() => handleDelete(product.id)}\n                title=\"Supprimer ce produit\"\n                style={{ background: 'var(--color-danger-bg)', border: '1px solid var(--color-danger)', borderRadius: 'var(--radius-md)', padding: '7px 12px', color: 'var(--color-danger)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 600 }}\n              >\n                <span style={{ fontSize: 16, fontWeight: 700, lineHeight: 1 }}>✕</span>\n              </button>\n            </div>\n          </div>\n\n          <div className=\"card-body\" style={{ overflowX: 'auto' }}>\n            <table style={{ borderCollapse: 'collapse', width: '100%', minWidth: 920 }}>\n              <thead>\n                <tr style={{ borderBottom: '2px solid var(--color-border)' }}>\n                  <th style={thLabel}>Libellé</th>\n                  {MONTHS.map((m) => <th key={m} style={thCell}>{m}</th>)}\n                  <th style={thTotal}>Total An 1</th>\n                  <th style={thSep} />\n                  {GROWTH_YEARS.map((y) => (\n                    <th key={y} style={{ ...thCell, color: 'var(--color-primary)', fontWeight: 700 }}>{y} %</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                <tr style={{ background: 'var(--color-surface-2)' }}>\n                  <td style={tdLabel}>Qté vendue / mois</td>\n                  {product.monthlyQty.map((v, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={inputStyle}\n                        ref={(el) => { arrayRefs.current[`${product.id}-qty-${i}`] = el }}\n                        step={1}\n                        min={0}\n                        defaultValue={v}\n                        onBlur={(e) => handleQty(product.id, i, parseInt(e.target.value, 10) || 0)}\n                      />\n                    </td>\n                  ))}\n                  <td style={{ ...tdTotal, fontWeight: 700 }}>{totalQty(product).toLocaleString('fr')}</td>\n                  <td style={tdSep} />\n                  {product.growthRates.slice(0, 4).map((r, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        ref={(el) => { arrayRefs.current[`${product.id}-growth-${i}`] = el }}\n                        style={{ ...inputStyle, color: 'var(--color-primary)', fontWeight: 600 }}\n                        step={0.5}\n                        defaultValue={r}\n                        onBlur={(e) => handleGrowth(product.id, i, parseFloat(e.target.value) || 0)}\n                      />\n                    </td>\n                  ))}\n                </tr>\n                <tr>\n                  <td style={{ ...tdLabel, color: 'var(--color-text-muted)', fontWeight: 400 }}>CA mensuel (Ar)</td>\n                  {product.monthlyQty.map((v, i) => (\n                    <td key={i} style={{ ...tdCell, fontSize: 10, color: 'var(--color-text-muted)' }}>\n                      {(v * product.price).toLocaleString('fr')}\n                    </td>\n                  ))}\n                  <td style={{ ...tdTotal, background: '#eaf5e6', fontWeight: 700, color: 'var(--color-primary)' }}>\n                    {formatAriary(totalRevenue(product))}\n                  </td>\n                  <td style={tdSep} />\n                  {GROWTH_YEARS.map((_, i) => <td key={i} style={tdCell} />)}\n                </tr>\n              </tbody>\n            </table>\n            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', margin: '8px 0 0' }}>\n              Quantités vendues An 1 par mois · La ligne CA est calculée automatiquement · Croissance % pour An 2 à 5\n            </p>\n          </div>\n        </div>\n      ))}\n    </div>\n  )\n}\n\nconst thLabel: React.CSSProperties  = { textAlign: 'left',   padding: '6px 10px', fontSize: 11, fontWeight: 700, color: '#374151', whiteSpace: 'nowrap', minWidth: 140, background: '#f8fafc' }\nconst thCell: React.CSSProperties   = { textAlign: 'center', padding: '6px 2px',  fontSize: 10, fontWeight: 700, color: '#374151', minWidth: 52, background: '#f8fafc' }\nconst thTotal: React.CSSProperties  = { textAlign: 'right',  padding: '6px 10px', fontSize: 10, fontWeight: 700, color: '#1a1a1a', minWidth: 100, background: '#eaf5e6', whiteSpace: 'nowrap' }\nconst thSep: React.CSSProperties    = { width: 14, background: '#e2e8f0' }\nconst tdLabel: React.CSSProperties  = { padding: '5px 10px', fontSize: 'var(--text-xs)', fontWeight: 600, color: '#1a1a1a', whiteSpace: 'nowrap' }\nconst tdCell: React.CSSProperties   = { padding: '3px 2px',  textAlign: 'center' }\nconst tdTotal: React.CSSProperties  = { padding: '5px 10px', textAlign: 'right', fontSize: 'var(--text-sm)', color: '#1a1a1a', background: '#f0fdf4' }\nconst tdSep: React.CSSProperties    = { width: 14, background: '#e2e8f0' }\nconst inputStyle: React.CSSProperties = { width: '100%', textAlign: 'right', fontSize: 'var(--text-xs)' }\nconst addBarStyle: React.CSSProperties = { display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-5)', background: 'var(--color-surface)', border: '1px solid var(--color-border)', borderRadius: 'var(--radius-md)', padding: 'var(--space-4)' }\nconst saveAllBtn: React.CSSProperties = { background: '#f0fdf4', border: '1px solid #86efac', borderRadius: 6, padding: '6px 16px', color: '#16a34a', cursor: 'pointer', fontSize: 13, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap' }\nconst saveAllBtnOk: React.CSSProperties = { ...saveAllBtn, background: '#dcfce7', border: '1px solid #4ade80', color: '#15803d' }\n","import { useState, useRef } from 'react'\nimport { offlineMaterialApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary } from '@/calculations/calculations'\nimport type { Material } from '@/types'\nimport NumInput from '@/components/ui/NumInput'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst MONTHS = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc']\nconst GROWTH_YEARS = ['An 2','An 3','An 4','An 5']\n\nexport default function MaterialsSection() {\n  const company        = useCompanyStore((s) => s.company)!\n  const addMaterial    = useCompanyStore((s) => s.addMaterial)\n  const updateMaterial = useCompanyStore((s) => s.updateMaterial)\n  const removeMaterial = useCompanyStore((s) => s.removeMaterial)\n\n  const [newName, setNewName]   = useState('')\n  const [isAdding, setIsAdding] = useState(false)\n  const [saving, setSaving]     = useState(false)\n  const [saved, setSaved]       = useState(false)\n  const arrayRefs = useRef<Record<string, HTMLInputElement | null>>({})\n\n  async function handleAdd() {\n    if (!newName.trim()) return\n    setIsAdding(true)\n    try {\n      const mat = await offlineMaterialApi.create(company.id, { name: newName.trim() })\n      addMaterial(mat)\n      setNewName('')\n    } finally { setIsAdding(false) }\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm('Supprimer cette matière ?')) return\n    await offlineMaterialApi.delete(id, company.id)\n    removeMaterial(id)\n  }\n\n  async function handleField(mat: Material, field: keyof Material, value: unknown) {\n    const updated = await offlineMaterialApi.update(mat.id, company.id, { [field]: value } as Partial<Material>)\n    updateMaterial(mat.id, updated)\n  }\n\n  async function handleQty(matId: number, idx: number, val: number) {\n    const fresh = useCompanyStore.getState().company?.materials.find((m) => m.id === matId)\n    if (!fresh) return\n    const qty = [...fresh.monthlyQty]\n    qty[idx] = val\n    const updated = await offlineMaterialApi.update(matId, company.id, { monthlyQty: qty })\n    updateMaterial(matId, updated)\n  }\n\n  async function handleGrowth(matId: number, idx: number, val: number) {\n    const fresh = useCompanyStore.getState().company?.materials.find((m) => m.id === matId)\n    if (!fresh) return\n    const rates = [...fresh.growthRates]\n    rates[idx] = val\n    const updated = await offlineMaterialApi.update(matId, company.id, { growthRates: rates })\n    updateMaterial(matId, updated)\n  }\n\n  async function handleSaveAll() {\n    setSaving(true)\n    try {\n      for (const mat of useCompanyStore.getState().company?.materials ?? []) {\n        const monthlyQty = Array.from({ length: 12 }, (_, i) =>\n          parseInt(arrayRefs.current[`${mat.id}-qty-${i}`]?.value || '0', 10) || 0,\n        )\n        const growthRates = [\n          ...Array.from({ length: 4 }, (_, i) =>\n            parseFloat(arrayRefs.current[`${mat.id}-growth-${i}`]?.value || '0') || 0,\n          ),\n          mat.growthRates[4] ?? 0,\n        ]\n        const updated = await offlineMaterialApi.update(mat.id, company.id, { monthlyQty, growthRates })\n        updateMaterial(mat.id, updated)\n      }\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2500)\n    } finally {\n      setSaving(false)\n    }\n  }\n\n  const totalQty  = (m: Material) => m.monthlyQty.reduce((a, b) => a + b, 0)\n  const totalCost = (m: Material) => totalQty(m) * m.unitCost\n\n  return (\n    <div>\n      <div style={{ marginBottom: 'var(--space-5)', display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n            <i className=\"fas fa-boxes-stacked\" style={{ marginRight: 8, color: 'var(--color-primary)' }} />\n            Matières premières\n          </h3>\n          <p className=\"section-subtitle\">Coûts unitaires, quantités mensuelles et taux de croissance An 2-5.</p>\n        </div>\n        <HelpButton\n          title=\"Matières premières\"\n          content={\"Saisissez vos matières premières ou consommables.\\n\\n=> Coût unitaire : Prix d'achat pour une unité.\\n\\n=> Quantités mensuelles : Quantité consommée par mois.\\n\\n=> Taux de croissance : Évolution du coût ou de la quantité sur 5 ans.\"}\n        />\n      </div>\n\n      {/* Barre ajout + bouton enregistrer unique */}\n      <div style={addBarStyle}>\n        <input\n          className=\"form-input\"\n          style={{ flex: 1, maxWidth: 320 }}\n          placeholder=\"Nom de la matière…\"\n          value={newName}\n          onChange={(e) => setNewName(e.target.value)}\n          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}\n        />\n        <button className=\"btn btn-primary\" onClick={handleAdd} disabled={isAdding || !newName.trim()}>\n          <i className=\"fas fa-plus\" style={{ marginRight: 6 }} />\n          {isAdding ? 'Ajout…' : 'Ajouter'}\n        </button>\n        {company.materials.length > 0 && (\n          <button\n            type=\"button\"\n            onClick={handleSaveAll}\n            disabled={saving}\n            style={saved ? saveAllBtnOk : saveAllBtn}\n          >\n            <i className={`fas ${saved ? 'fa-check-circle' : 'fa-floppy-disk'}`} style={{ marginRight: 6 }} />\n            {saving ? 'Enregistrement…' : saved ? 'Enregistré !' : 'Enregistrer tout'}\n          </button>\n        )}\n      </div>\n\n      {company.materials.length === 0 && (\n        <div className=\"empty-state\">\n          <div className=\"empty-state-icon\"><i className=\"fas fa-boxes-stacked\" /></div>\n          <div className=\"empty-state-title\">Aucune matière première</div>\n          <p className=\"empty-state-desc\">Ajoutez vos matières ou intrants ci-dessus.</p>\n        </div>\n      )}\n\n      {company.materials.map((mat) => (\n        <div key={mat.id} className=\"card\" style={{ marginBottom: 'var(--space-5)' }}>\n          <div className=\"card-header\">\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, flexWrap: 'wrap' }}>\n              <input\n                className=\"form-input\"\n                style={{ fontWeight: 600, maxWidth: 240 }}\n                defaultValue={mat.name}\n                onBlur={(e) => handleField(mat, 'name', e.target.value)}\n              />\n              <label className=\"form-label\" style={{ marginBottom: 0, whiteSpace: 'nowrap' }}>Coût unitaire</label>\n              <NumInput\n                className=\"form-input\"\n                style={{ width: 120, textAlign: 'right' }}\n                defaultValue={mat.unitCost}\n                min={0}\n                onBlur={(v) => handleField(mat, 'unitCost', v)}\n              />\n              <span style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>Ar</span>\n            </div>\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>\n              <div className=\"kpi-card\" style={{ padding: '4px 12px' }}>\n                <div className=\"kpi-label\">Coût An 1</div>\n                <div className=\"kpi-value\" style={{ fontSize: 'var(--text-base)' }}>{formatAriary(totalCost(mat))}</div>\n              </div>\n              <button\n                onClick={() => handleDelete(mat.id)}\n                title=\"Supprimer\"\n                style={{ background: 'var(--color-danger-bg)', border: '1px solid var(--color-danger)', borderRadius: 'var(--radius-md)', padding: '7px 12px', color: 'var(--color-danger)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 600 }}\n              >\n                <span style={{ fontSize: 16, fontWeight: 700, lineHeight: 1 }}>✕</span>\n              </button>\n            </div>\n          </div>\n\n          <div className=\"card-body\" style={{ overflowX: 'auto' }}>\n            <table style={{ borderCollapse: 'collapse', width: '100%', minWidth: 920 }}>\n              <thead>\n                <tr style={{ borderBottom: '2px solid var(--color-border)' }}>\n                  <th style={thLabel}>Libellé</th>\n                  {MONTHS.map((m) => <th key={m} style={thCell}>{m}</th>)}\n                  <th style={thTotal}>Total An 1</th>\n                  <th style={thSep} />\n                  {GROWTH_YEARS.map((y) => (\n                    <th key={y} style={{ ...thCell, color: 'var(--color-primary)', fontWeight: 700 }}>{y} %</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                <tr style={{ background: 'var(--color-surface-2)' }}>\n                  <td style={tdLabel}>Quantité / mois</td>\n                  {mat.monthlyQty.map((v, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={inputStyle}\n                        ref={(el) => { arrayRefs.current[`${mat.id}-qty-${i}`] = el }}\n                        step={1}\n                        min={0}\n                        defaultValue={v}\n                        onBlur={(e) => handleQty(mat.id, i, parseInt(e.target.value, 10) || 0)}\n                      />\n                    </td>\n                  ))}\n                  <td style={{ ...tdTotal, fontWeight: 700 }}>{totalQty(mat).toLocaleString('fr')}</td>\n                  <td style={tdSep} />\n                  {mat.growthRates.slice(0, 4).map((r, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        ref={(el) => { arrayRefs.current[`${mat.id}-growth-${i}`] = el }}\n                        style={{ ...inputStyle, color: 'var(--color-primary)', fontWeight: 600 }}\n                        step={0.5}\n                        defaultValue={r}\n                        onBlur={(e) => handleGrowth(mat.id, i, parseFloat(e.target.value) || 0)}\n                      />\n                    </td>\n                  ))}\n                </tr>\n              </tbody>\n            </table>\n            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', margin: '8px 0 0' }}>\n              Quantités An 1 mois par mois · Taux de croissance % pour An 2 à 5\n            </p>\n          </div>\n        </div>\n      ))}\n    </div>\n  )\n}\n\nconst thLabel: React.CSSProperties  = { textAlign: 'left',   padding: '6px 10px', fontSize: 11, fontWeight: 700, color: '#374151', whiteSpace: 'nowrap', minWidth: 130, background: '#f8fafc' }\nconst thCell: React.CSSProperties   = { textAlign: 'center', padding: '6px 2px',  fontSize: 10, fontWeight: 700, color: '#374151', minWidth: 52, background: '#f8fafc' }\nconst thTotal: React.CSSProperties  = { textAlign: 'right',  padding: '6px 10px', fontSize: 10, fontWeight: 700, color: '#1a1a1a', minWidth: 90, background: '#eaf5e6', whiteSpace: 'nowrap' }\nconst thSep: React.CSSProperties    = { width: 14, background: '#e2e8f0' }\nconst tdLabel: React.CSSProperties  = { padding: '5px 10px', fontSize: 'var(--text-xs)', fontWeight: 600, color: '#1a1a1a', whiteSpace: 'nowrap' }\nconst tdCell: React.CSSProperties   = { padding: '3px 2px',  textAlign: 'center' }\nconst tdTotal: React.CSSProperties  = { padding: '5px 10px', textAlign: 'right', fontSize: 'var(--text-sm)', color: '#1a1a1a', background: '#eaf5e6' }\nconst tdSep: React.CSSProperties    = { width: 14, background: '#e2e8f0' }\nconst inputStyle: React.CSSProperties = { width: '100%', textAlign: 'right', fontSize: 'var(--text-xs)' }\nconst addBarStyle: React.CSSProperties = { display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-5)', background: 'var(--color-surface)', border: '1px solid var(--color-border)', borderRadius: 'var(--radius-md)', padding: 'var(--space-4)' }\nconst saveAllBtn: React.CSSProperties = { background: '#f0fdf4', border: '1px solid #86efac', borderRadius: 6, padding: '6px 16px', color: '#16a34a', cursor: 'pointer', fontSize: 13, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap' }\nconst saveAllBtnOk: React.CSSProperties = { ...saveAllBtn, background: '#dcfce7', border: '1px solid #4ade80', color: '#15803d' }\n","import { useState, useRef } from 'react'\nimport { offlineStaffApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary, staffAnnualCost, staffAnnualCostByYear } from '@/calculations/calculations'\nimport type { StaffMember } from '@/types'\nimport NumInput from '@/components/ui/NumInput'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst GROWTH_YEARS = ['An 2', 'An 3', 'An 4', 'An 5']\n\nexport default function StaffSection() {\n  const company           = useCompanyStore((s) => s.company)!\n  const addStaffMember    = useCompanyStore((s) => s.addStaffMember)\n  const updateStaffMember = useCompanyStore((s) => s.updateStaffMember)\n  const removeStaffMember = useCompanyStore((s) => s.removeStaffMember)\n\n  const [newRole, setNewRole]   = useState('')\n  const [isAdding, setIsAdding] = useState(false)\n  const [saving, setSaving]     = useState(false)\n  const [saved, setSaved]       = useState(false)\n  const arrayRefs = useRef<Record<string, HTMLInputElement | null>>({})\n\n  async function handleAdd() {\n    if (!newRole.trim()) return\n    setIsAdding(true)\n    try {\n      const staff = await offlineStaffApi.create(company.id, { roleName: newRole.trim() })\n      addStaffMember(staff)\n      setNewRole('')\n    } finally {\n      setIsAdding(false)\n    }\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm('Supprimer ce poste ?')) return\n    await offlineStaffApi.delete(id, company.id)\n    removeStaffMember(id)\n  }\n\n  async function handleField(staff: StaffMember, field: keyof StaffMember, value: unknown) {\n    const updated = await offlineStaffApi.update(staff.id, company.id, { [field]: value } as Partial<StaffMember>)\n    updateStaffMember(staff.id, updated)\n  }\n\n  async function handleGrowth(staffId: number, idx: number, val: number) {\n    const fresh = useCompanyStore.getState().company?.staffMembers.find((s) => s.id === staffId)\n    if (!fresh) return\n    const rates = [...(fresh.growthRates ?? [0, 0, 0, 0])]\n    rates[idx] = val\n    const updated = await offlineStaffApi.update(staffId, company.id, { growthRates: rates })\n    updateStaffMember(staffId, updated)\n  }\n\n  async function handleSaveAll() {\n    setSaving(true)\n    try {\n      for (const s of useCompanyStore.getState().company?.staffMembers ?? []) {\n        const growthRates = Array.from({ length: 4 }, (_, i) =>\n          parseFloat(arrayRefs.current[`${s.id}-growth-${i}`]?.value || '0') || 0,\n        )\n        const updated = await offlineStaffApi.update(s.id, company.id, { growthRates })\n        updateStaffMember(s.id, updated)\n      }\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2500)\n    } finally {\n      setSaving(false)\n    }\n  }\n\n  const totalMasseSalariale = company.staffMembers.reduce((sum, s) => sum + staffAnnualCost(s), 0)\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n          <div>\n            <h3 className=\"section-title\" style={{ marginBottom: 4 }}>👥 Charges de personnel</h3>\n            <p className=\"section-subtitle\">Postes, salaires, effectifs, charges sociales et croissance An 2–5.</p>\n          </div>\n          <HelpButton\n            title=\"Personnel\"\n            content={\"Enregistrez les postes et salaires de votre équipe.\\n\\n=> Salaire mensuel brut : Salaire de base par personne par mois.\\n\\n=> Charges sociales : Taux de cotisations patronales (CNAPS, etc.), généralement 13% à Madagascar.\\n\\n=> Taux de croissance : Augmentation salariale prévue d'une année à l'autre.\"}\n          />\n        </div>\n        {company.staffMembers.length > 0 && (\n          <div className=\"kpi-card\" style={{ textAlign: 'right' }}>\n            <div className=\"kpi-label\">Masse salariale An 1</div>\n            <div className=\"kpi-value\">{formatAriary(totalMasseSalariale)}</div>\n          </div>\n        )}\n      </div>\n\n      {/* Barre ajout + bouton enregistrer unique */}\n      <div style={styles.addBar}>\n        <input\n          className=\"form-input\"\n          style={{ flex: 1, maxWidth: 320 }}\n          placeholder=\"Intitulé du poste…\"\n          value={newRole}\n          onChange={(e) => setNewRole(e.target.value)}\n          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}\n        />\n        <button className=\"btn btn-primary\" onClick={handleAdd} disabled={isAdding || !newRole.trim()}>\n          {isAdding ? '…' : '+ Ajouter un poste'}\n        </button>\n        {company.staffMembers.length > 0 && (\n          <button\n            type=\"button\"\n            onClick={handleSaveAll}\n            disabled={saving}\n            style={saved ? styles.saveOk : styles.save}\n          >\n            <i className={`fas ${saved ? 'fa-check-circle' : 'fa-floppy-disk'}`} style={{ marginRight: 6 }} />\n            {saving ? 'Enregistrement…' : saved ? 'Enregistré !' : 'Enregistrer tout'}\n          </button>\n        )}\n      </div>\n\n      {company.staffMembers.length === 0 && (\n        <div className=\"empty-state\">\n          <div className=\"empty-state-icon\">👥</div>\n          <div className=\"empty-state-title\">Aucun poste</div>\n          <p className=\"empty-state-desc\">Ajoutez vos postes salariaux ci-dessus.</p>\n        </div>\n      )}\n\n      {company.staffMembers.length > 0 && (\n        <div className=\"card\">\n          <div className=\"table-wrapper\">\n            <table style={{ minWidth: 900 }}>\n              <thead>\n                <tr>\n                  <th style={{ minWidth: 180 }}>Poste / Fonction</th>\n                  <th style={{ textAlign: 'right', minWidth: 130 }}>Salaire/mois (Ar)</th>\n                  <th style={{ textAlign: 'right', minWidth: 70 }}>Effectif</th>\n                  <th style={{ textAlign: 'right', minWidth: 80 }}>Charges (%)</th>\n                  <th style={{ textAlign: 'right', minWidth: 110 }}>Coût An 1</th>\n                  <th style={{ width: 14, background: 'var(--color-border)', padding: 0 }} />\n                  {GROWTH_YEARS.map((y) => (\n                    <th key={y} style={{ textAlign: 'center', minWidth: 65, color: 'var(--color-primary)', fontWeight: 700 }}>\n                      {y} %\n                    </th>\n                  ))}\n                  <th />\n                </tr>\n              </thead>\n              <tbody>\n                {company.staffMembers.map((s) => (\n                  <tr key={s.id}>\n                    <td>\n                      <input\n                        className=\"editable-cell\"\n                        style={{ width: '100%', minWidth: 160 }}\n                        defaultValue={s.roleName}\n                        onBlur={(e) => handleField(s, 'roleName', e.target.value)}\n                      />\n                    </td>\n                    <td style={{ textAlign: 'right' }}>\n                      <NumInput\n                        className=\"editable-cell\"\n                        style={{ width: 120, textAlign: 'right' }}\n                        defaultValue={s.monthlySalary}\n                        min={0}\n                        onBlur={(v) => handleField(s, 'monthlySalary', v)}\n                      />\n                    </td>\n                    <td style={{ textAlign: 'right' }}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={{ width: 60, textAlign: 'right' }}\n                        defaultValue={s.headcount}\n                        min={1}\n                        onBlur={(e) => handleField(s, 'headcount', parseInt(e.target.value, 10) || 1)}\n                      />\n                    </td>\n                    <td style={{ textAlign: 'right' }}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={{ width: 70, textAlign: 'right' }}\n                        step=\"0.5\"\n                        defaultValue={s.chargesRate}\n                        min={0}\n                        onBlur={(e) => handleField(s, 'chargesRate', parseFloat(e.target.value) || 0)}\n                      />\n                    </td>\n                    <td style={{ textAlign: 'right', fontWeight: 600 }}>\n                      {formatAriary(staffAnnualCost(s))}\n                    </td>\n                    <td style={{ width: 14, background: 'var(--color-border)', padding: 0 }} />\n                    {(s.growthRates ?? [0, 0, 0, 0]).slice(0, 4).map((r, i) => (\n                      <td key={i} style={{ textAlign: 'center', padding: '3px 2px' }}>\n                        <input\n                          type=\"number\"\n                          className=\"editable-cell\"\n                          style={{ width: 58, textAlign: 'right', color: 'var(--color-primary)', fontWeight: 600, fontSize: 'var(--text-xs)' }}\n                          step=\"0.5\"\n                          ref={(el) => { arrayRefs.current[`${s.id}-growth-${i}`] = el }}\n                          defaultValue={r}\n                          onBlur={(e) => handleGrowth(s.id, i, parseFloat(e.target.value) || 0)}\n                        />\n                      </td>\n                    ))}\n                    <td style={{ padding: '4px 2px' }}>\n                      <button\n                        className=\"btn btn-ghost btn-sm\"\n                        style={{ color: 'var(--color-danger)', fontWeight: 700, fontSize: 16 }}\n                        onClick={() => handleDelete(s.id)}\n                      >\n                        ✕\n                      </button>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n              <tfoot>\n                <tr>\n                  <td colSpan={4} style={{ fontWeight: 600 }}>Total masse salariale An 1</td>\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(totalMasseSalariale)}</td>\n                  <td style={{ width: 14, background: 'var(--color-border)', padding: 0 }} />\n                  {[1, 2, 3, 4].map((yearIdx) => (\n                    <td key={yearIdx} style={{ textAlign: 'center', fontSize: 'var(--text-xs)', color: 'var(--color-primary)', fontWeight: 700 }}>\n                      {formatAriary(company.staffMembers.reduce((sum, s) => sum + staffAnnualCostByYear(s, yearIdx), 0))}\n                    </td>\n                  ))}\n                  <td />\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  addBar: {\n    display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-5)',\n    background: 'var(--color-surface)', border: '1px solid var(--color-border)',\n    borderRadius: 'var(--radius-md)', padding: 'var(--space-4)',\n  },\n  save: {\n    background: '#f0fdf4', border: '1px solid #86efac', borderRadius: 6,\n    padding: '6px 16px', color: '#16a34a', cursor: 'pointer', fontSize: 13,\n    fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap',\n  },\n  saveOk: {\n    background: '#dcfce7', border: '1px solid #4ade80', borderRadius: 6,\n    padding: '6px 16px', color: '#15803d', cursor: 'pointer', fontSize: 13,\n    fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap',\n  },\n}\n","import { useState, useRef } from 'react'\nimport { offlineExpenseApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary, expenseAnnualTotal } from '@/calculations/calculations'\nimport type { Expense } from '@/types'\nimport NumInput from '@/components/ui/NumInput'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst MONTHS = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc']\nconst GROWTH_YEARS = ['An 2','An 3','An 4','An 5']\n\nexport default function ExpensesSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const addExpense = useCompanyStore((s) => s.addExpense)\n  const updateExpense = useCompanyStore((s) => s.updateExpense)\n  const removeExpense = useCompanyStore((s) => s.removeExpense)\n\n  const [newName, setNewName]   = useState('')\n  const [isAdding, setIsAdding] = useState(false)\n  const [saving, setSaving]     = useState(false)\n  const [saved, setSaved]       = useState(false)\n  const arrayRefs = useRef<Record<string, HTMLInputElement | null>>({})\n\n  async function handleAdd() {\n    if (!newName.trim()) return\n    setIsAdding(true)\n    try {\n      const exp = await offlineExpenseApi.create(company.id, { name: newName.trim() })\n      addExpense(exp)\n      setNewName('')\n    } finally { setIsAdding(false) }\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm('Supprimer cette charge ?')) return\n    await offlineExpenseApi.delete(id, company.id)\n    removeExpense(id)\n  }\n\n  async function handleField(exp: Expense, field: keyof Expense, value: unknown) {\n    const updated = await offlineExpenseApi.update(exp.id, company.id, { [field]: value } as Partial<Expense>)\n    updateExpense(exp.id, updated)\n  }\n\n  async function handleSeasonality(expId: number, idx: number, val: number) {\n    const freshExp = useCompanyStore.getState().company?.expenses.find((e) => e.id === expId)\n    if (!freshExp) return\n    const seas = [...freshExp.seasonality]\n    seas[idx] = val\n    const updated = await offlineExpenseApi.update(expId, company.id, { seasonality: seas })\n    updateExpense(expId, updated)\n  }\n\n  async function handleInflation(expId: number, idx: number, val: number) {\n    const freshExp = useCompanyStore.getState().company?.expenses.find((e) => e.id === expId)\n    if (!freshExp) return\n    const inf = [...freshExp.inflationGrowth]\n    inf[idx] = val\n    const updated = await offlineExpenseApi.update(expId, company.id, { inflationGrowth: inf })\n    updateExpense(expId, updated)\n  }\n\n  async function handleSaveAll() {\n    setSaving(true)\n    try {\n      for (const exp of useCompanyStore.getState().company?.expenses ?? []) {\n        const seasonality = Array.from({ length: 12 }, (_, i) =>\n          parseFloat(arrayRefs.current[`${exp.id}-seas-${i}`]?.value || '0') || 0,\n        )\n        const inflationGrowth = Array.from({ length: 4 }, (_, i) =>\n          parseFloat(arrayRefs.current[`${exp.id}-inf-${i}`]?.value || '0') || 0,\n        ).concat([exp.inflationGrowth[4] ?? 0])\n        const updated = await offlineExpenseApi.update(exp.id, company.id, { seasonality, inflationGrowth })\n        updateExpense(exp.id, updated)\n      }\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2500)\n    } finally {\n      setSaving(false)\n    }\n  }\n\n  const totalCharges = company.expenses.reduce((sum, e) => sum + expenseAnnualTotal(e), 0)\n\n  return (\n    <div>\n      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 'var(--space-5)' }}>\n        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n          <div>\n            <h3 className=\"section-title\" style={{ marginBottom: 4 }}>💸 Charges d'exploitation</h3>\n            <p className=\"section-subtitle\">Saisonnalité mensuelle et taux de croissance annuel An 2-5.</p>\n          </div>\n          <HelpButton\n            title=\"Charges d'exploitation\"\n            content={\"Listez toutes vos charges fixes et variables.\\n\\n=> Montant mensuel : Charge moyenne par mois.\\n\\n=> Saisonnalité : Coefficients mensuels si la charge varie selon les saisons (1 = normal, 0 = pas de charge ce mois).\\n\\n => Croissance annuelle : Évolution de la charge sur 5 ans (inflation incluse).\"}\n          />\n        </div>\n        {company.expenses.length > 0 && (\n          <div className=\"kpi-card\" style={{ textAlign: 'right' }}>\n            <div className=\"kpi-label\">Total charges An 1</div>\n            <div className=\"kpi-value\">{formatAriary(totalCharges)}</div>\n          </div>\n        )}\n      </div>\n\n      {/* Barre ajout + bouton enregistrer unique */}\n      <div style={addBarStyle}>\n        <input\n          className=\"form-input\"\n          style={{ flex: 1, maxWidth: 320 }}\n          placeholder=\"Nom de la charge…\"\n          value={newName}\n          onChange={(e) => setNewName(e.target.value)}\n          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}\n        />\n        <button className=\"btn btn-primary\" onClick={handleAdd} disabled={isAdding || !newName.trim()}>\n          {isAdding ? '…' : '+ Ajouter'}\n        </button>\n        {company.expenses.length > 0 && (\n          <button\n            type=\"button\"\n            onClick={handleSaveAll}\n            disabled={saving}\n            style={saved ? saveAllBtnOk : saveAllBtn}\n          >\n            <i className={`fas ${saved ? 'fa-check-circle' : 'fa-floppy-disk'}`} style={{ marginRight: 6 }} />\n            {saving ? 'Enregistrement…' : saved ? 'Enregistré !' : 'Enregistrer tout'}\n          </button>\n        )}\n      </div>\n\n      {company.expenses.length === 0 && (\n        <div className=\"empty-state\">\n          <div className=\"empty-state-icon\">💸</div>\n          <div className=\"empty-state-title\">Aucune charge</div>\n          <p className=\"empty-state-desc\">Loyer, électricité, communication…</p>\n        </div>\n      )}\n\n      {company.expenses.map((exp) => (\n        <div key={exp.id} className=\"card\" style={{ marginBottom: 'var(--space-5)' }}>\n          {/* En-tête carte */}\n          <div className=\"card-header\">\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1 }}>\n              <input\n                className=\"form-input\"\n                style={{ fontWeight: 600, maxWidth: 240 }}\n                defaultValue={exp.name}\n                onBlur={(e) => handleField(exp, 'name', e.target.value)}\n              />\n              <span className=\"form-label\" style={{ marginBottom: 0, whiteSpace: 'nowrap' }}>Montant mensuel</span>\n              <NumInput\n                className=\"form-input\"\n                style={{ width: 130, textAlign: 'right' }}\n                defaultValue={exp.monthlyAmount}\n                min={0}\n                onBlur={(v) => handleField(exp, 'monthlyAmount', v)}\n              />\n              <span style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>Ar</span>\n            </div>\n            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>\n              <div className=\"kpi-card\" style={{ padding: '4px 10px' }}>\n                <div className=\"kpi-label\">Total An 1</div>\n                <div className=\"kpi-value\" style={{ fontSize: 'var(--text-base)' }}>\n                  {formatAriary(expenseAnnualTotal(exp))}\n                </div>\n              </div>\n              <button\n                onClick={() => handleDelete(exp.id)}\n                title=\"Supprimer cette charge\"\n                style={{ background: 'var(--color-danger-bg)', border: '1px solid var(--color-danger)', borderRadius: 'var(--radius-md)', padding: '7px 12px', color: 'var(--color-danger)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 600 }}\n              >\n                <span style={{ fontSize: 16, fontWeight: 700, lineHeight: 1 }}>✕</span>\n              </button>\n            </div>\n          </div>\n\n          {/* Tableau saisonnalité + croissance */}\n          <div className=\"card-body\" style={{ overflowX: 'auto' }}>\n            <table style={{ borderCollapse: 'collapse', width: '100%', minWidth: 900 }}>\n              <thead>\n                <tr>\n                  <th style={thLabel}>Libellé</th>\n                  {MONTHS.map((m) => <th key={m} style={thCell}>{m}</th>)}\n                  <th style={thSep} />\n                  {GROWTH_YEARS.map((y) => (\n                    <th key={y} style={{ ...thCell, color: 'var(--color-primary)' }}>{y}</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td style={tdLabel}>Saisonnalité</td>\n                  {exp.seasonality.map((v, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={inputStyle}\n                        ref={(el) => { arrayRefs.current[`${exp.id}-seas-${i}`] = el }}\n                        step={0.5}\n                        min={0}\n                        max={1}\n                        defaultValue={v}\n                        onBlur={(e) => handleSeasonality(exp.id, i, parseFloat(e.target.value) || 0)}\n                      />\n                    </td>\n                  ))}\n                  <td style={tdSep} />\n                  {exp.inflationGrowth.slice(0, 4).map((r, i) => (\n                    <td key={i} style={tdCell}>\n                      <input\n                        type=\"number\"\n                        className=\"editable-cell\"\n                        style={{ ...inputStyle, color: 'var(--color-primary)' }}\n                        step={0.5}\n                        defaultValue={r}\n                        ref={(el) => { arrayRefs.current[`${exp.id}-inf-${i}`] = el }}\n                        onBlur={(e) => handleInflation(exp.id, i, parseFloat(e.target.value) || 0)}\n                      />\n                    </td>\n                  ))}\n                </tr>\n              </tbody>\n            </table>\n            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', margin: '8px 0 0' }}>\n              Saisonnalité : 1 = mois actif, 0 = mois absent (ex. charge trimestrielle = 0.33) · Croissance % pour An 2 à An 5\n            </p>\n          </div>\n        </div>\n      ))}\n    </div>\n  )\n}\n\nconst thLabel: React.CSSProperties = { textAlign: 'left', padding: '4px 8px', fontSize: 11, fontWeight: 600, color: 'var(--color-text-muted)', whiteSpace: 'nowrap', minWidth: 130 }\nconst thCell: React.CSSProperties  = { textAlign: 'center', padding: '4px 2px', fontSize: 10, fontWeight: 600, color: 'var(--color-text-muted)', minWidth: 52 }\nconst thSep: React.CSSProperties   = { width: 12, background: 'var(--color-border)' }\nconst tdLabel: React.CSSProperties = { padding: '4px 8px', fontSize: 'var(--text-xs)', fontWeight: 600, color: 'var(--color-text)', whiteSpace: 'nowrap' }\nconst tdCell: React.CSSProperties  = { padding: '2px 2px', textAlign: 'center' }\nconst tdSep: React.CSSProperties   = { width: 12, background: 'var(--color-surface-2)' }\nconst inputStyle: React.CSSProperties = { width: '100%', textAlign: 'right', fontSize: 'var(--text-xs)' }\nconst addBarStyle: React.CSSProperties = { display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-5)', background: 'var(--color-surface)', border: '1px solid var(--color-border)', borderRadius: 'var(--radius-md)', padding: 'var(--space-4)' }\nconst saveAllBtn: React.CSSProperties = { background: '#f0fdf4', border: '1px solid #86efac', borderRadius: 6, padding: '6px 16px', color: '#16a34a', cursor: 'pointer', fontSize: 13, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap' }\nconst saveAllBtnOk: React.CSSProperties = { ...saveAllBtn, background: '#dcfce7', border: '1px solid #4ade80', color: '#15803d' }\n","import { useState } from 'react'\nimport { offlineInvestmentApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary } from '@/calculations/calculations'\nimport type { Investment } from '@/types'\nimport NumInput from '@/components/ui/NumInput'\nimport HelpButton from '@/components/ui/HelpButton'\n\nexport default function InvestmentsSection() {\n  const company        = useCompanyStore((s) => s.company)!\n  const addInvestment  = useCompanyStore((s) => s.addInvestment)\n  const updateInvestment = useCompanyStore((s) => s.updateInvestment)\n  const removeInvestment = useCompanyStore((s) => s.removeInvestment)\n\n  const [newName, setNewName]   = useState('')\n  const [isAdding, setIsAdding] = useState(false)\n\n  async function handleAdd() {\n    if (!newName.trim()) return\n    setIsAdding(true)\n    try {\n      const inv = await offlineInvestmentApi.create(company.id, { name: newName.trim() })\n      addInvestment(inv)\n      setNewName('')\n    } finally {\n      setIsAdding(false)\n    }\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm('Supprimer cet investissement ?')) return\n    await offlineInvestmentApi.delete(id, company.id)\n    removeInvestment(id)\n  }\n\n  async function handleField(inv: Investment, field: keyof Investment, value: unknown) {\n    const updated = await offlineInvestmentApi.update(inv.id, company.id, { [field]: value })\n    updateInvestment(inv.id, updated)\n  }\n\n  const totalInvest = company.investments.reduce((s, i) => s + i.amount, 0)\n  const totalEquity = company.investments.reduce((s, i) => s + i.financedEquity, 0)\n  const totalLoan   = company.investments.reduce((s, i) => s + i.financedLoan, 0)\n  const totalGrant  = company.investments.reduce((s, i) => s + i.financedGrant, 0)\n  const totalFinanced = totalEquity + totalLoan + totalGrant\n\n  // Validation par ligne : diff = financement - montant\n  function rowDiff(inv: Investment) {\n    return (inv.financedEquity + inv.financedLoan + inv.financedGrant) - inv.amount\n  }\n\n  const errorRows = company.investments.filter((inv) => rowDiff(inv) !== 0)\n  const hasErrors = errorRows.length > 0\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n          <div>\n            <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n              <i className=\"fas fa-building\" style={{ marginRight: 8, color: '#3b82f6' }} />\n              Investissements & Financement\n            </h3>\n            <p className=\"section-subtitle\">Immobilisations, durée d'amortissement et plan de financement.</p>\n          </div>\n          <HelpButton\n            title=\"Investissements & Financement\"\n            content={\"Déclarez vos immobilisations et leur plan de financement.\\n\\n=> Montant : Coût total de l'investissement.\\n\\n=> Durée d'amortissement : Nombre d'années pour amortir l'actif (ex: 5 ans pour matériel).\\n\\n=> Fonds propres + Subvention + Emprunt : La somme doit être ÉGALE au montant. L'indicateur 'Équilibre' vous le confirme.\\n\\n=> Taux et durée d'emprunt : S'appliquent uniquement à la part financée par emprunt.\"}\n          />\n        </div>\n      </div>\n\n      {/* Alerte globale si au moins un investissement non équilibré */}\n      {hasErrors && (\n        <div style={{\n          display: 'flex', alignItems: 'flex-start', gap: 12,\n          padding: 'var(--space-4)',\n          background: '#fef2f2',\n          border: '1px solid #fca5a5',\n          borderRadius: 'var(--radius-md)',\n          marginBottom: 'var(--space-5)',\n        }}>\n          <i className=\"fas fa-triangle-exclamation\" style={{ color: '#dc2626', fontSize: 18, marginTop: 2, flexShrink: 0 }} />\n          <div>\n            <div style={{ fontWeight: 700, color: '#dc2626', fontSize: 'var(--text-sm)', marginBottom: 4 }}>\n              Financement déséquilibré — {errorRows.length} investissement{errorRows.length > 1 ? 's' : ''}\n            </div>\n            <div style={{ color: '#7f1d1d', fontSize: 'var(--text-xs)', lineHeight: 1.6 }}>\n              {errorRows.map((inv) => {\n                const diff = rowDiff(inv)\n                return (\n                  <div key={inv.id}>\n                    • <strong>{inv.name}</strong> : financement = {formatAriary(inv.financedEquity + inv.financedLoan + inv.financedGrant)},\n                    montant = {formatAriary(inv.amount)} →{' '}\n                    <strong style={{ color: diff > 0 ? '#b45309' : '#dc2626' }}>\n                      {diff > 0 ? `+${formatAriary(diff)} en trop` : `${formatAriary(Math.abs(diff))} manquant`}\n                    </strong>\n                  </div>\n                )\n              })}\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Summary KPIs */}\n      {company.investments.length > 0 && (\n        <div className=\"kpi-grid\" style={{ marginBottom: 'var(--space-5)' }}>\n          <div className=\"kpi-card\">\n            <div className=\"kpi-label\">Total investissement</div>\n            <div className=\"kpi-value\">{formatAriary(totalInvest)}</div>\n          </div>\n          <div className=\"kpi-card\">\n            <div className=\"kpi-label\">Fonds propres</div>\n            <div className=\"kpi-value\">{formatAriary(totalEquity)}</div>\n          </div>\n          <div className=\"kpi-card\">\n            <div className=\"kpi-label\">Subventions</div>\n            <div className=\"kpi-value\">{formatAriary(totalGrant)}</div>\n          </div>\n          <div className=\"kpi-card\">\n            <div className=\"kpi-label\">Emprunts</div>\n            <div className=\"kpi-value\">{formatAriary(totalLoan)}</div>\n          </div>\n          {/* Indicateur global d'équilibre */}\n          <div className=\"kpi-card\" style={{\n            border: `1px solid ${hasErrors ? '#fca5a5' : '#86efac'}`,\n            background: hasErrors ? '#fef2f2' : '#f0fdf4',\n          }}>\n            <div className=\"kpi-label\">Total financé</div>\n            <div className=\"kpi-value\" style={{ color: hasErrors ? '#dc2626' : '#16a34a' }}>\n              {formatAriary(totalFinanced)}\n            </div>\n            <div style={{ fontSize: 'var(--text-xs)', marginTop: 4, color: hasErrors ? '#dc2626' : '#16a34a', fontWeight: 600 }}>\n              {hasErrors\n                ? `Écart : ${formatAriary(Math.abs(totalFinanced - totalInvest))}`\n                : '✓ Équilibré'}\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Add bar */}\n      <div style={styles.addBar}>\n        <input className=\"form-input\" style={{ flex: 1, maxWidth: 320 }}\n          placeholder=\"Nom de l'investissement…\" value={newName}\n          onChange={(e) => setNewName(e.target.value)}\n          onKeyDown={(e) => e.key === 'Enter' && handleAdd()} />\n        <button className=\"btn btn-primary\" onClick={handleAdd} disabled={isAdding || !newName.trim()}>\n          {isAdding ? '…' : '+ Ajouter'}\n        </button>\n      </div>\n\n      {company.investments.length === 0 && (\n        <div className=\"empty-state\">\n          <div className=\"empty-state-icon\">🏗</div>\n          <div className=\"empty-state-title\">Aucun investissement</div>\n        </div>\n      )}\n\n      {/* Investments table */}\n      {company.investments.length > 0 && (\n        <div className=\"card\">\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Désignation</th>\n                  <th style={{ textAlign: 'right' }}>Montant (Ar)</th>\n                  <th style={{ textAlign: 'right' }}>Durée amort.</th>\n                  <th style={{ textAlign: 'right' }}>Fonds propres</th>\n                  <th style={{ textAlign: 'right' }}>Subvention</th>\n                  <th style={{ textAlign: 'right' }}>Emprunt</th>\n                  <th style={{ textAlign: 'right' }}>Taux (%)</th>\n                  <th style={{ textAlign: 'right' }}>Durée empr.</th>\n                  <th style={{ textAlign: 'center', minWidth: 90 }}>Équilibre</th>\n                  <th />\n                </tr>\n              </thead>\n              <tbody>\n                {company.investments.map((inv) => {\n                  const diff    = rowDiff(inv)\n                  const isOk    = diff === 0\n                  const rowBg   = !isOk ? '#fff5f5' : undefined\n\n                  return (\n                    <tr key={inv.id} style={{ background: rowBg }}>\n                      <td>\n                        <input className=\"editable-cell\" style={{ width: '100%', minWidth: 160 }}\n                          defaultValue={inv.name}\n                          onBlur={(e) => handleField(inv, 'name', e.target.value)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <NumInput className=\"editable-cell\" style={{ width: 110, textAlign: 'right' }}\n                          defaultValue={inv.amount} min={0}\n                          onBlur={(v) => handleField(inv, 'amount', v)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <input type=\"number\" className=\"editable-cell\" style={{ width: 60, textAlign: 'right' }}\n                          defaultValue={inv.usefulLife} min={1}\n                          onBlur={(e) => handleField(inv, 'usefulLife', parseInt(e.target.value, 10) || 1)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <NumInput className=\"editable-cell\" style={{ width: 100, textAlign: 'right' }}\n                          defaultValue={inv.financedEquity} min={0}\n                          onBlur={(v) => handleField(inv, 'financedEquity', v)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <NumInput className=\"editable-cell\" style={{ width: 100, textAlign: 'right' }}\n                          defaultValue={inv.financedGrant} min={0}\n                          onBlur={(v) => handleField(inv, 'financedGrant', v)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <NumInput className=\"editable-cell\" style={{ width: 100, textAlign: 'right' }}\n                          defaultValue={inv.financedLoan} min={0}\n                          onBlur={(v) => handleField(inv, 'financedLoan', v)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <input type=\"number\" className=\"editable-cell\" style={{ width: 60, textAlign: 'right' }}\n                          step=\"0.5\" defaultValue={inv.loanRate} min={0}\n                          onBlur={(e) => handleField(inv, 'loanRate', parseFloat(e.target.value) || 0)} />\n                      </td>\n                      <td style={{ textAlign: 'right' }}>\n                        <input type=\"number\" className=\"editable-cell\" style={{ width: 60, textAlign: 'right' }}\n                          defaultValue={inv.loanYears} min={1}\n                          onBlur={(e) => handleField(inv, 'loanYears', parseInt(e.target.value, 10) || 1)} />\n                      </td>\n\n                      {/* Colonne équilibre */}\n                      <td style={{ textAlign: 'center' }}>\n                        {isOk ? (\n                          <span style={{\n                            display: 'inline-flex', alignItems: 'center', gap: 4,\n                            color: '#16a34a', fontWeight: 700, fontSize: 'var(--text-xs)',\n                          }}>\n                            <i className=\"fas fa-check-circle\" />\n                            Équilibré\n                          </span>\n                        ) : (\n                          <span style={{\n                            display: 'inline-flex', alignItems: 'center', gap: 4,\n                            color: '#dc2626', fontWeight: 700, fontSize: 'var(--text-xs)',\n                          }}\n                            title={`Financement = ${formatAriary(inv.financedEquity + inv.financedLoan + inv.financedGrant)} | Montant = ${formatAriary(inv.amount)}`}\n                          >\n                            <i className=\"fas fa-circle-exclamation\" />\n                            {diff > 0 ? `+${formatAriary(diff)}` : `−${formatAriary(Math.abs(diff))}`}\n                          </span>\n                        )}\n                      </td>\n\n                      <td>\n                        <button className=\"btn btn-ghost btn-sm\" style={{ color: 'var(--color-danger)', fontWeight: 700, fontSize: 16 }}\n                          onClick={() => handleDelete(inv.id)}>✕</button>\n                      </td>\n                    </tr>\n                  )\n                })}\n              </tbody>\n              <tfoot>\n                <tr>\n                  <td style={{ fontWeight: 600 }}>Total</td>\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(totalInvest)}</td>\n                  <td />\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(totalEquity)}</td>\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(totalGrant)}</td>\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(totalLoan)}</td>\n                  <td /><td />\n                  {/* Bilan total */}\n                  <td style={{ textAlign: 'center' }}>\n                    {!hasErrors ? (\n                      <span style={{ color: '#16a34a', fontWeight: 700, fontSize: 'var(--text-xs)' }}>\n                        <i className=\"fas fa-check-circle\" style={{ marginRight: 4 }} />\n                        OK\n                      </span>\n                    ) : (\n                      <span style={{ color: '#dc2626', fontWeight: 700, fontSize: 'var(--text-xs)' }}>\n                        <i className=\"fas fa-circle-exclamation\" style={{ marginRight: 4 }} />\n                        Erreur\n                      </span>\n                    )}\n                  </td>\n                  <td />\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  addBar: {\n    display: 'flex', alignItems: 'center', gap: 'var(--space-3)',\n    marginBottom: 'var(--space-5)',\n    background: 'var(--color-surface)',\n    border: '1px solid var(--color-border)',\n    borderRadius: 'var(--radius-md)',\n    padding: 'var(--space-4)',\n  },\n}\n","import { useState } from 'react'\nimport { offlineFundingApi } from '@/api/offlineApi'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { formatAriary } from '@/calculations/calculations'\nimport type { AdditionalFunding } from '@/types'\n\nexport default function FundingSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const updateAdditionalFundings = useCompanyStore((s) => s.updateAdditionalFundings)\n\n  // Local draft — user edits here, save sends all 5 rows at once\n  const [draft, setDraft] = useState<AdditionalFunding[]>(() => {\n    // Ensure we always have 5 rows (An 1-5)\n    return Array.from({ length: 5 }, (_, i) => {\n      const year = i + 1\n      return company.additionalFundings.find((f) => f.yearNumber === year) ?? {\n        yearNumber: year, equity: 0, loan: 0, loanRate: 0, loanYears: 0, grant: 0,\n      }\n    })\n  })\n\n  const [isSaving, setIsSaving] = useState(false)\n  const [saved, setSaved] = useState(false)\n\n  function handleChange(yearIndex: number, field: keyof AdditionalFunding, value: string) {\n    setDraft((prev) => {\n      const next = [...prev]\n      next[yearIndex] = {\n        ...next[yearIndex],\n        [field]: field === 'yearNumber' ? parseInt(value, 10) : parseFloat(value) || 0,\n      }\n      return next\n    })\n    setSaved(false)\n  }\n\n  async function handleSave() {\n    setIsSaving(true)\n    try {\n      const updated = await offlineFundingApi.update(company.id, draft)\n      updateAdditionalFundings(updated)\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2000)\n    } finally {\n      setIsSaving(false)\n    }\n  }\n\n  const totalByYear = draft.map((f) => f.equity + f.loan + f.grant)\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>💰 Apports complémentaires An 1-5</h3>\n          <p className=\"section-subtitle\">\n            Fonds propres, emprunts et subventions additionnels pour chaque année.\n            L'An 1 complète le financement des investissements.\n          </p>\n        </div>\n        {saved && <span className=\"badge badge-success\">✓ Enregistré</span>}\n      </div>\n\n      <div className=\"card\">\n        <div className=\"table-wrapper\">\n          <table>\n            <thead>\n              <tr>\n                <th>Année</th>\n                <th style={{ textAlign: 'right' }}>Fonds propres (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Emprunt (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Taux emprunt (%)</th>\n                <th style={{ textAlign: 'right' }}>Durée (ans)</th>\n                <th style={{ textAlign: 'right' }}>Subvention (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Total</th>\n              </tr>\n            </thead>\n            <tbody>\n              {draft.map((row, i) => (\n                <tr key={row.yearNumber}>\n                  <td style={{ fontWeight: 600 }}>An {row.yearNumber}</td>\n                  <td style={{ textAlign: 'right' }}>\n                    <input type=\"number\" className=\"editable-cell\" style={{ width: 110, textAlign: 'right' }}\n                      value={row.equity} min={0}\n                      onChange={(e) => handleChange(i, 'equity', e.target.value)} />\n                  </td>\n                  <td style={{ textAlign: 'right' }}>\n                    <input type=\"number\" className=\"editable-cell\" style={{ width: 110, textAlign: 'right' }}\n                      value={row.loan} min={0}\n                      onChange={(e) => handleChange(i, 'loan', e.target.value)} />\n                  </td>\n                  <td style={{ textAlign: 'right' }}>\n                    <input type=\"number\" className=\"editable-cell\" style={{ width: 70, textAlign: 'right' }}\n                      step=\"0.5\" value={row.loanRate} min={0}\n                      onChange={(e) => handleChange(i, 'loanRate', e.target.value)} />\n                  </td>\n                  <td style={{ textAlign: 'right' }}>\n                    <input type=\"number\" className=\"editable-cell\" style={{ width: 60, textAlign: 'right' }}\n                      value={row.loanYears} min={0}\n                      onChange={(e) => handleChange(i, 'loanYears', e.target.value)} />\n                  </td>\n                  <td style={{ textAlign: 'right' }}>\n                    <input type=\"number\" className=\"editable-cell\" style={{ width: 110, textAlign: 'right' }}\n                      value={row.grant} min={0}\n                      onChange={(e) => handleChange(i, 'grant', e.target.value)} />\n                  </td>\n                  <td style={{ textAlign: 'right', fontWeight: 600 }}>\n                    {formatAriary(totalByYear[i])}\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n            <tfoot>\n              <tr>\n                <td colSpan={6} style={{ fontWeight: 600 }}>Total général</td>\n                <td style={{ textAlign: 'right', fontWeight: 700 }}>\n                  {formatAriary(totalByYear.reduce((a, b) => a + b, 0))}\n                </td>\n              </tr>\n            </tfoot>\n          </table>\n        </div>\n      </div>\n\n      <div style={{ marginTop: 'var(--space-5)', display: 'flex', justifyContent: 'flex-end' }}>\n        <button className=\"btn btn-primary btn-lg\" onClick={handleSave} disabled={isSaving}>\n          {isSaving ? 'Enregistrement…' : '💾 Enregistrer les apports'}\n        </button>\n      </div>\n    </div>\n  )\n}\n","import { useMemo } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { computeAll, formatAriary, formatPct } from '@/calculations/calculations'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst YEARS = ['An 1', 'An 2', 'An 3', 'An 4', 'An 5']\n\nexport default function ResultsSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(\n      settings,\n      company.products,\n      company.materials,\n      company.staffMembers,\n      company.expenses,\n      company.investments,\n      company.additionalFundings,\n    )\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">📊</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres économiques pour voir les résultats.</p>\n      </div>\n    )\n  }\n\n  const { incomeStatement: IS, profitability: KPI, depreciationTable: DEP, loanRepaymentTable: LOAN, profitabilityRatios: PR } = result\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n            <i className=\"fas fa-table-list\" style={{ marginRight: 8, color: 'var(--color-primary)' }} />\n            Compte de résultat prévisionnel\n          </h3>\n          <p className=\"section-subtitle\">Calculé automatiquement depuis vos données — mise à jour en temps réel.</p>\n        </div>\n        <HelpButton\n          title=\"Compte de résultat\"\n          content={\"Le compte de résultat montre la rentabilité de votre activité année par année.\\n\\n => Calcul du Chiffres d'Affaire (CA): \\n ° Quantité An 1 = ∑ quantité par mois \\n ° CA An 1 = Prix unitaire × Quantité An 1 \\n ° CA An N = CA An N-1 x (1 + Taux de croissance An N)\\n\\n=> Calcul des Coûts Variables (CV): \\n° Quantité achetée An 1 = ∑ quantité achetée par mois \\n ° CV An 1 = Quantité achetée An 1 x Coût d'achat unitaire \\n ° CV An N = CV N-1 x (1 + Taux de croissance) \\n\\n=> Calcule des Charges Personnel : \\n° Charges Personnel An 1 = ( Salaire mensuel × Effectif × 12) × (1 + Charges sociales%) \\n° Charges Personnel An N = Charges Personnel An N-1 x (1 + Taux de croissance N)\\n\\n=>Calcul des autres Charges : Montant mensuel × Saisonnalité × 12, avec inflation annuelle.\\n\\n=> Amortissements : Montant investissement ÷ Durée (méthode linéaire).\\n\\n=> Résultat avant impôt : CA − Matières − Personnel − Charges − Amortissements − Intérêts.\\n\\n=> Résultat net : Résultat avant impôt × (1 − Taux d'imposition).\"}\n        />\n      </div>\n\n      {/* KPI banner */}\n      <div className=\"kpi-grid\">\n        <div className=\"kpi-card\">\n          <div className=\"kpi-label\">VAN</div>\n          <div className=\"kpi-value\" style={{ color: KPI.npv >= 0 ? 'var(--color-success)' : 'var(--color-danger)' }}>\n            {formatAriary(KPI.npv)}\n          </div>\n          <div className=\"kpi-sub\">Taux : {settings.discountRate} %</div>\n        </div>\n        <div className=\"kpi-card\">\n          <div className=\"kpi-label\">TRI</div>\n          <div className=\"kpi-value\">{KPI.irr !== null ? formatPct(KPI.irr) : 'N/A'}</div>\n        </div>\n        <div className=\"kpi-card\">\n          <div className=\"kpi-label\">Indice de profitabilité</div>\n          <div className=\"kpi-value\" style={{ color: KPI.profitabilityIndex >= 1 ? 'var(--color-success)' : 'var(--color-danger)' }}>\n            {KPI.profitabilityIndex.toFixed(2)}\n          </div>\n          <div className=\"kpi-sub\">{KPI.profitabilityIndex >= 1 ? '✓ Projet rentable' : '✗ Projet non rentable'}</div>\n        </div>\n        <div className=\"kpi-card\">\n          <div className=\"kpi-label\">Délai de récupération</div>\n          <div className=\"kpi-value\">{KPI.paybackYear !== null ? `An ${KPI.paybackYear}` : '> 5 ans'}</div>\n        </div>\n        <div className=\"kpi-card\">\n          <div className=\"kpi-label\">Seuil de rentabilité</div>\n          <div className=\"kpi-value\" style={{ fontSize: 'var(--text-base)' }}>\n            {KPI.breakEvenYear !== null ? `An ${KPI.breakEvenYear}` : '> 5 ans'}\n          </div>\n          <div className=\"kpi-sub\">\n            {formatAriary(PR.breakEvenValueByYear[KPI.breakEvenYear !== null ? KPI.breakEvenYear - 1 : 0])}\n          </div>\n        </div>\n      </div>\n\n      {/* Compte de résultat */}\n      <ResultTable\n        title=\"Compte de résultat prévisionnel\"\n        rows={[\n          { label: \"Chiffre d'affaires\", values: IS.revenueByYear, bold: true },\n          { label: '− Coût des matières', values: IS.materialCostByYear, negative: true },\n          { label: '= Marge brute', values: IS.grossMarginByYear, bold: true, highlight: true },\n          { label: '− Charges de personnel', values: IS.staffCostByYear, negative: true },\n          { label: \"− Charges d'exploitation\", values: IS.expenseCostByYear, negative: true },\n          { label: '= EBITDA', values: IS.ebitdaByYear, bold: true },\n          { label: '− Amortissements', values: IS.depreciationByYear, negative: true },\n          { label: '= EBIT', values: IS.ebitByYear, bold: true },\n          { label: \"− Intérêts d'emprunt\", values: IS.interestByYear, negative: true },\n          { label: \"= Résultat avant impôt\", values: IS.ebtByYear, bold: true },\n          { label: '− Impôts', values: IS.taxByYear, negative: true },\n          { label: '= Résultat net', values: IS.netIncomeByYear, bold: true, highlight: true, colored: true },\n        ]}\n      />\n\n      {/* Tableau d'amortissement */}\n      {DEP.byInvestment.length > 0 && (\n        <div className=\"card\">\n          <div className=\"card-header\"><span className=\"card-title\">Tableau d'amortissement linéaire</span></div>\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Immobilisation</th>\n                  <th style={{ textAlign: 'right' }}>Amort. annuel</th>\n                  {YEARS.map((y) => <th key={y} style={{ textAlign: 'right' }}>VNC {y}</th>)}\n                </tr>\n              </thead>\n              <tbody>\n                {DEP.byInvestment.map((row) => {\n                  const inv = company.investments.find((i) => i.id === row.investmentId)\n                  return (\n                    <tr key={row.investmentId}>\n                      <td>{inv?.name ?? `Inv. #${row.investmentId}`}</td>\n                      <td style={{ textAlign: 'right' }}>{formatAriary(row.annualDepreciation)}</td>\n                      {row.yearlyBook.map((v, i) => <td key={i} style={{ textAlign: 'right' }}>{formatAriary(v)}</td>)}\n                    </tr>\n                  )\n                })}\n              </tbody>\n              <tfoot>\n                <tr>\n                  <td style={{ fontWeight: 600 }}>Total</td>\n                  <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(DEP.totalAnnualDepreciation)}</td>\n                  {YEARS.map((_, i) => <td key={i} />)}\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </div>\n      )}\n\n      {/* Tableau de remboursement des emprunts */}\n      {LOAN.byLoan.length > 0 && (\n        <div className=\"card\">\n          <div className=\"card-header\">\n            <span className=\"card-title\">Tableau de remboursement des emprunts</span>\n          </div>\n          <div className=\"table-wrapper\">\n            {LOAN.byLoan.map((loan, li) => (\n              <div key={li} style={{ marginBottom: li < LOAN.byLoan.length - 1 ? 'var(--space-4)' : 0 }}>\n                {/* En-tête emprunt */}\n                <div style={{\n                  display: 'flex', gap: 'var(--space-4)', alignItems: 'center',\n                  padding: '6px 12px',\n                  background: 'var(--color-primary)', color: '#fff',\n                  fontSize: 'var(--text-sm)', fontWeight: 700,\n                }}>\n                  <span>{loan.label}</span>\n                  <span style={{ fontWeight: 400, opacity: 0.85 }}>\n                    Principal : {formatAriary(loan.principal)} · Taux : {loan.rate.toFixed(1)} % · Durée : {loan.years} ans\n                  </span>\n                  <span style={{ marginLeft: 'auto', fontWeight: 600 }}>\n                    Annuité : {formatAriary(\n                      (loan.annualPayments[0]?.capital ?? 0) + (loan.annualPayments[0]?.interest ?? 0)\n                    )} / an\n                  </span>\n                </div>\n                <table style={{ width: '100%' }}>\n                  <thead>\n                    <tr>\n                      <th style={{ minWidth: 200 }}>Rubrique</th>\n                      {YEARS.map((y) => <th key={y} style={{ textAlign: 'right', minWidth: 120 }}>{y}</th>)}\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {/* Capital remboursé */}\n                    <tr>\n                      <td style={{ paddingLeft: 16, color: 'var(--color-text-muted)' }}>Capital remboursé</td>\n                      {YEARS.map((_, yi) => (\n                        <td key={yi} style={{ textAlign: 'right' }}>\n                          {formatAriary(loan.annualPayments[yi]?.capital ?? 0)}\n                        </td>\n                      ))}\n                    </tr>\n                    {/* Intérêts */}\n                    <tr>\n                      <td style={{ paddingLeft: 16, color: 'var(--color-danger)' }}>Intérêts payés</td>\n                      {YEARS.map((_, yi) => (\n                        <td key={yi} style={{ textAlign: 'right', color: 'var(--color-danger)' }}>\n                          {formatAriary(loan.annualPayments[yi]?.interest ?? 0)}\n                        </td>\n                      ))}\n                    </tr>\n                    {/* Solde restant */}\n                    <tr style={{ background: 'var(--color-surface-2)', fontWeight: 600 }}>\n                      <td style={{ paddingLeft: 16 }}>Solde restant dû</td>\n                      {YEARS.map((_, yi) => (\n                        <td key={yi} style={{ textAlign: 'right' }}>\n                          {formatAriary(loan.annualPayments[yi]?.balance ?? 0)}\n                        </td>\n                      ))}\n                    </tr>\n                  </tbody>\n                </table>\n              </div>\n            ))}\n\n            {/* Totaux si plusieurs emprunts */}\n            {LOAN.byLoan.length > 1 && (\n              <table style={{ width: '100%', marginTop: 'var(--space-3)', borderTop: '2px solid var(--color-border)' }}>\n                <tbody>\n                  <tr>\n                    <td style={{ minWidth: 200, fontWeight: 700 }}>Total capital remboursé</td>\n                    {LOAN.totalCapitalByYear.map((v, i) => (\n                      <td key={i} style={{ textAlign: 'right', minWidth: 120, fontWeight: 700 }}>{formatAriary(v)}</td>\n                    ))}\n                  </tr>\n                  <tr>\n                    <td style={{ fontWeight: 700, color: 'var(--color-danger)' }}>Total intérêts payés</td>\n                    {LOAN.totalInterestByYear.map((v, i) => (\n                      <td key={i} style={{ textAlign: 'right', fontWeight: 700, color: 'var(--color-danger)' }}>{formatAriary(v)}</td>\n                    ))}\n                  </tr>\n                </tbody>\n              </table>\n            )}\n          </div>\n        </div>\n      )}\n\n    </div>\n  )\n}\n\n// ─── Sub-component : generic result table ─────────────────────────────────────\n\ninterface TableRow {\n  label: string\n  values: number[]\n  bold?: boolean\n  highlight?: boolean\n  colored?: boolean\n  negative?: boolean\n}\n\nfunction ResultTable({ title, rows }: { title: string; rows: TableRow[] }) {\n  return (\n    <div className=\"card\">\n      <div className=\"card-header\"><span className=\"card-title\">{title}</span></div>\n      <div className=\"table-wrapper\">\n        <table>\n          <thead>\n            <tr>\n              <th style={{ minWidth: 220 }}>Libellé</th>\n              {YEARS.map((y) => <th key={y} style={{ textAlign: 'right' }}>{y}</th>)}\n            </tr>\n          </thead>\n          <tbody>\n            {rows.map((row) => {\n              const bg = row.highlight ? 'var(--color-surface-2)' : undefined\n              return (\n                <tr key={row.label} style={{ background: bg }}>\n                  <td style={{ fontWeight: row.bold ? 600 : 400 }}>{row.label}</td>\n                  {row.values.map((v, i) => {\n                    const color = row.colored\n                      ? (row.negative\n                          ? (v < 0 ? 'var(--color-danger)' : 'var(--color-success)')\n                          : (v >= 0 ? 'var(--color-success)' : 'var(--color-danger)'))\n                      : undefined\n                    return (\n                      <td key={i} style={{ textAlign: 'right', fontWeight: row.bold ? 700 : 400, color }}>\n                        {formatAriary(v)}\n                      </td>\n                    )\n                  })}\n                </tr>\n              )\n            })}\n          </tbody>\n        </table>\n      </div>\n    </div>\n  )\n}\n","import { useMemo, useState } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport {\n  computeAll,\n  buildMonthlyCashFlow,\n  formatAriary,\n} from '@/calculations/calculations'\nimport { offlineFundingApi } from '@/api/offlineApi'\nimport type { AdditionalFunding } from '@/types'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst YEARS = ['An 1', 'An 2', 'An 3', 'An 4', 'An 5']\nconst MONTHS = ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Jun', 'Jul', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc']\n\nexport default function CashFlowSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const updateAdditionalFundings = useCompanyStore((s) => s.updateAdditionalFundings)\n  const settings = company.settings\n  const [tab, setTab] = useState<'annuel' | 'mensuel'>('annuel')\n  const [isSaving, setIsSaving] = useState(false)\n  const [saved, setSaved] = useState(false)\n\n  // Local state pour les apports — éditable inline\n  const [apports, setApports] = useState<AdditionalFunding[]>(() =>\n    [1, 2, 3, 4, 5].map((yr) => {\n      const found = company.additionalFundings.find((f) => f.yearNumber === yr)\n      return found ?? { yearNumber: yr, equity: 0, loan: 0, loanRate: 0, loanYears: 5, grant: 0 }\n    }),\n  )\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, apports)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, apports])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">💧</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres dans la section Entreprise pour afficher la trésorerie.</p>\n      </div>\n    )\n  }\n\n  const { incomeStatement: IS, loanRepaymentTable: LR } = result\n\n  // ─── Financement initial (An 0) ───────────────────────────────────────────\n  const invEquity = company.investments.reduce((s, i) => s + i.financedEquity, 0)\n  const invLoan   = company.investments.reduce((s, i) => s + i.financedLoan, 0)\n  const invGrant  = company.investments.reduce((s, i) => s + i.financedGrant, 0)\n  const invTotal  = company.investments.reduce((s, i) => s + i.amount, 0)\n  const fdr = settings.fondsRoulement ?? 0\n  const tresoInitiale = invEquity + invLoan + invGrant - invTotal + fdr\n\n  // ─── Calculs annuels An 1-5 ───────────────────────────────────────────────\n  const caf         = IS.netIncomeByYear.map((n, y) => n + IS.depreciationByYear[y])\n  const rembCapital = LR.totalCapitalByYear\n  const opCF        = caf.map((c, y) => c - rembCapital[y])\n\n  const addTotal = apports.map((af) => af.equity + af.loan + af.grant)\n\n  // Trésorerie cumulée (running sum depuis tresoInitiale)\n  const cashCum: number[] = []\n  let running = tresoInitiale\n  for (let y = 0; y < 5; y++) {\n    running += opCF[y] + addTotal[y]\n    cashCum.push(Math.round(running))\n  }\n\n  // Tréso avant apport (pour alerte déficit)\n  const tresoBefore = [0, 1, 2, 3, 4].map((y) => {\n    const prev = y === 0 ? tresoInitiale : cashCum[y - 1]\n    return prev + opCF[y]\n  })\n\n  // ─── Sauvegarder les apports ──────────────────────────────────────────────\n  async function handleSaveApports() {\n    setIsSaving(true)\n    try {\n      const updated = await offlineFundingApi.update(company.id, apports)\n      updateAdditionalFundings(updated)\n      setSaved(true)\n      setTimeout(() => setSaved(false), 2000)\n    } finally {\n      setIsSaving(false)\n    }\n  }\n\n  function setApport(yr: number, field: keyof AdditionalFunding, val: number) {\n    setApports((prev) =>\n      prev.map((af) => af.yearNumber === yr ? { ...af, [field]: val } : af),\n    )\n    setSaved(false)\n  }\n\n  // ─── Trésorerie mensuelle An 1 ────────────────────────────────────────────\n  const monthly = useMemo(() => buildMonthlyCashFlow(\n    company.products, company.materials, company.staffMembers, company.expenses,\n    IS, LR, apports, tresoInitiale,\n  ), [company.products, company.materials, company.staffMembers, company.expenses, IS, LR, apports, tresoInitiale])\n\n  // ─── Helper ───────────────────────────────────────────────────────────────\n  const colored = (v: number) => ({ color: v < 0 ? 'var(--color-danger)' : v > 0 ? 'var(--color-success)' : undefined } as React.CSSProperties)\n  const BOLD: React.CSSProperties = { fontWeight: 700, background: 'var(--color-surface-2)' }\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div className=\"flex items-center justify-between\">\n        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n          <div>\n            <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n              <i className=\"fas fa-water\" style={{ marginRight: 8, color: '#3a7d2e' }} />\n              Trésorerie prévisionnelle\n            </h3>\n            <p className=\"section-subtitle\">Flux de trésorerie sur 5 ans + trésorerie mensuelle An 1</p>\n          </div>\n          <HelpButton\n            title=\"Plan de trésorerie\"\n            content={\"Flux de liquidités réels de l'entreprise.\\n\\n=> Trésorerie initiale (An 0) : Fonds propres + Emprunt + Subventions pour les investissements, moins le total des investissements, plus le Fonds de roulement.\\n\\n=> CAF (Capacité d'Autofinancement) : Résultat net + Amortissements. Cash généré par l'activité.\\n\\n=> Remboursement capital : Calculé par annuité constante sur la durée d'emprunt.\\n\\n=> Flux net An N : CAF − Remboursement capital + Apports complémentaires An N.\\n\\n=> Trésorerie cumulée : Trésorerie initiale + somme des flux nets précédents.\\n\\n=> Vue mensuelle : Encaissements et décaissements répartis selon les coefficients de saisonnalité de chaque produit et charge.\"}\n          />\n        </div>\n        {saved && <span className=\"badge badge-success\">✓ Apports enregistrés</span>}\n      </div>\n\n      {/* Onglets */}\n      <div style={{ display: 'flex', gap: 8, borderBottom: '2px solid var(--color-border)', paddingBottom: 4 }}>\n        {(['annuel', 'mensuel'] as const).map((t) => (\n          <button key={t} className={`btn btn-sm ${tab === t ? 'btn-primary' : 'btn-ghost'}`}\n            onClick={() => setTab(t)}>\n            <i className={`fas ${t === 'annuel' ? 'fa-calendar' : 'fa-calendar-days'}`} style={{ marginRight: 6 }} />\n            {t === 'annuel' ? 'Trésorerie 5 ans' : 'Mensuelle An 1'}\n          </button>\n        ))}\n      </div>\n\n      {/* ══════════════════ TABLE ANNUELLE ══════════════════ */}\n      {tab === 'annuel' && (\n        <div className=\"card\">\n          <div className=\"card-header\">\n            <span className=\"card-title\">Plan de trésorerie — An 0 à An 5</span>\n          </div>\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th style={{ minWidth: 240 }}>Rubrique</th>\n                  <th style={{ textAlign: 'right', minWidth: 130, background: '#2d3748', color: '#fff' }}>An 0 (départ)</th>\n                  {YEARS.map((y) => <th key={y} style={{ textAlign: 'right', minWidth: 130 }}>{y}</th>)}\n                </tr>\n              </thead>\n              <tbody>\n                {/* Financement initial */}\n                <tr><td colSpan={7} style={{ background: 'var(--color-primary)', color: '#fff', fontWeight: 700, fontSize: 'var(--text-xs)', padding: '4px 12px' }}>FINANCEMENT INITIAL (AN 0)</td></tr>\n                {[\n                  { label: 'Fonds propres apportés',   val: invEquity, plus: true  },\n                  { label: 'Emprunts reçus',            val: invLoan,   plus: true  },\n                  { label: 'Subventions reçues',        val: invGrant,  plus: true  },\n                  { label: '(-) Investissements réalisés', val: -invTotal, plus: false },\n                  { label: 'Fonds de roulement initial', val: fdr,      plus: true  },\n                ].map(({ label, val }) => (\n                  <tr key={label}>\n                    <td style={{ paddingLeft: 20 }}>{label}</td>\n                    <td style={{ textAlign: 'right', fontWeight: 600, ...colored(val) }}>{val !== 0 ? formatAriary(val) : '—'}</td>\n                    {YEARS.map((_, i) => <td key={i} style={{ textAlign: 'right', color: 'var(--color-text-muted)' }}>—</td>)}\n                  </tr>\n                ))}\n                <tr style={BOLD}>\n                  <td>= Trésorerie initiale (An 0)</td>\n                  <td style={{ textAlign: 'right', ...colored(tresoInitiale) }}>{formatAriary(tresoInitiale)}</td>\n                  {YEARS.map((_, i) => <td key={i} style={{ textAlign: 'right' }}>—</td>)}\n                </tr>\n\n                {/* Flux opérationnels */}\n                <tr><td colSpan={7} style={{ background: 'var(--color-primary)', color: '#fff', fontWeight: 700, fontSize: 'var(--text-xs)', padding: '4px 12px' }}>FLUX OPÉRATIONNELS (AN 1-5)</td></tr>\n                {[\n                  { label: 'CAF (Résultat net + Amortissements)', data: caf },\n                  { label: '(-) Remboursement capital emprunt',   data: rembCapital.map((v) => -v) },\n                ].map(({ label, data }) => (\n                  <tr key={label}>\n                    <td style={{ paddingLeft: 20 }}>{label}</td>\n                    <td style={{ textAlign: 'right', color: 'var(--color-text-muted)' }}>—</td>\n                    {data.map((v, i) => (\n                      <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                    ))}\n                  </tr>\n                ))}\n                <tr style={BOLD}>\n                  <td>= Flux de trésorerie net (CAF - Remb.)</td>\n                  <td style={{ textAlign: 'right' }}>—</td>\n                  {opCF.map((v, i) => (\n                    <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                  ))}\n                </tr>\n\n                {/* Apports complémentaires — éditables */}\n                <tr><td colSpan={7} style={{ background: '#f5a623', color: '#fff', fontWeight: 700, fontSize: 'var(--text-xs)', padding: '4px 12px' }}>APPORTS COMPLÉMENTAIRES (saisie)</td></tr>\n                {apports.map((af) => {\n                  const y = af.yearNumber - 1\n                  const before = tresoBefore[y]\n                  const total = af.equity + af.loan + af.grant\n                  return (\n                    <tr key={af.yearNumber} style={{ verticalAlign: 'top' }}>\n                      <td style={{ paddingLeft: 20 }}>\n                        <div style={{ fontWeight: 600, marginBottom: 6 }}>Apports An {af.yearNumber}</div>\n                        {before < 0 && (\n                          <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-danger)', marginBottom: 4 }}>\n                            ⚠ Déficit avant apport : {formatAriary(before)}\n                          </div>\n                        )}\n                        <div style={styles.apportGrid}>\n                          <label style={styles.apportLabel}>Fonds propres</label>\n                          <div style={styles.inputRow}>\n                            <input type=\"number\" className=\"form-input\" style={styles.apportInput} min=\"0\" step=\"10000\"\n                              value={af.equity} onChange={(e) => setApport(af.yearNumber, 'equity', +e.target.value)} />\n                            <span style={styles.unit}>Ar</span>\n                          </div>\n                          <label style={styles.apportLabel}>Emprunt</label>\n                          <div style={styles.inputRow}>\n                            <input type=\"number\" className=\"form-input\" style={styles.apportInput} min=\"0\" step=\"10000\"\n                              value={af.loan} onChange={(e) => setApport(af.yearNumber, 'loan', +e.target.value)} />\n                            <span style={styles.unit}>Ar</span>\n                          </div>\n                          {af.loan > 0 && (<>\n                            <label style={styles.apportLabel}>Taux emprunt</label>\n                            <div style={styles.inputRow}>\n                              <input type=\"number\" className=\"form-input\" style={{ ...styles.apportInput, width: 64 }} min=\"0\" max=\"50\" step=\"0.5\"\n                                value={af.loanRate} onChange={(e) => setApport(af.yearNumber, 'loanRate', +e.target.value)} />\n                              <span style={styles.unit}>%</span>\n                            </div>\n                            <label style={styles.apportLabel}>Durée emprunt</label>\n                            <div style={styles.inputRow}>\n                              <input type=\"number\" className=\"form-input\" style={{ ...styles.apportInput, width: 64 }} min=\"1\" max=\"20\"\n                                value={af.loanYears} onChange={(e) => setApport(af.yearNumber, 'loanYears', +e.target.value)} />\n                              <span style={styles.unit}>ans</span>\n                            </div>\n                          </>)}\n                          <label style={styles.apportLabel}>Subvention</label>\n                          <div style={styles.inputRow}>\n                            <input type=\"number\" className=\"form-input\" style={styles.apportInput} min=\"0\" step=\"10000\"\n                              value={af.grant} onChange={(e) => setApport(af.yearNumber, 'grant', +e.target.value)} />\n                            <span style={styles.unit}>Ar</span>\n                          </div>\n                        </div>\n                        {total > 0 && (\n                          <div style={{ marginTop: 6, fontSize: 'var(--text-xs)', color: 'var(--color-success)', fontWeight: 600 }}>\n                            Total : {formatAriary(total)}\n                          </div>\n                        )}\n                      </td>\n                      {/* Colonne An 0 vide */}\n                      <td style={{ textAlign: 'right', color: 'var(--color-text-muted)' }}>—</td>\n                      {/* Colonnes An 1-5 : afficher total uniquement pour cette année */}\n                      {YEARS.map((_, yi) => (\n                        <td key={yi} style={{ textAlign: 'right', fontWeight: yi === y ? 600 : 400, color: yi === y && total > 0 ? 'var(--color-success)' : 'var(--color-text-muted)' }}>\n                          {yi === y && total > 0 ? formatAriary(total) : '—'}\n                        </td>\n                      ))}\n                    </tr>\n                  )\n                })}\n\n                {/* Trésorerie cumulée */}\n                <tr style={{ ...BOLD, borderTop: '2px solid var(--color-primary)' }}>\n                  <td>Trésorerie cumulée fin d'année</td>\n                  <td style={{ textAlign: 'right', ...colored(tresoInitiale) }}>{formatAriary(tresoInitiale)}</td>\n                  {cashCum.map((v, i) => (\n                    <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                  ))}\n                </tr>\n              </tbody>\n            </table>\n          </div>\n\n          {/* Bouton sauvegarder les apports */}\n          <div style={{ padding: 'var(--space-4)', display: 'flex', justifyContent: 'flex-end' }}>\n            <button className=\"btn btn-primary\" onClick={handleSaveApports} disabled={isSaving}>\n              {isSaving ? 'Enregistrement…' : '💾 Enregistrer les apports'}\n            </button>\n          </div>\n        </div>\n      )}\n\n      {/* ══════════════════ TABLE MENSUELLE An 1 ══════════════════ */}\n      {tab === 'mensuel' && (\n        <div className=\"card\">\n          <div className=\"card-header\">\n            <span className=\"card-title\">Trésorerie mensuelle — An 1</span>\n          </div>\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th style={{ minWidth: 220 }}>Rubrique</th>\n                  {MONTHS.map((m) => <th key={m} style={{ textAlign: 'right', minWidth: 90 }}>{m}</th>)}\n                </tr>\n              </thead>\n              <tbody>\n                {[\n                  { label: 'Encaissements (CA)', data: monthly.encaissements, bold: false },\n                  { label: '(-) Coûts variables', data: monthly.coutsVariables.map((v) => -v), bold: false },\n                  { label: '(-) Personnel', data: Array(12).fill(-monthly.personnelMensuel), bold: false },\n                  { label: '(-) Autres charges', data: monthly.autresCharges.map((v) => -v), bold: false },\n                  { label: '(-) Impôt mensuel', data: Array(12).fill(-monthly.impotMensuel), bold: false },\n                  { label: '(-) Frais financiers', data: Array(12).fill(-monthly.fraisFinanciersMensuel), bold: false },\n                  { label: '(-) Remb. capital', data: Array(12).fill(-monthly.rembCapitalMensuel), bold: false },\n                  { label: '(+) Apport complémentaire', data: monthly.apportMois, bold: false },\n                  { label: '= Solde mensuel net', data: monthly.soldeMensuel, bold: true },\n                  { label: 'Solde cumulé', data: monthly.soldeCumule, bold: true },\n                ].map(({ label, data, bold }) => (\n                  <tr key={label} style={bold ? BOLD : undefined}>\n                    <td style={{ fontWeight: bold ? 700 : 400 }}>{label}</td>\n                    {data.map((v, i) => (\n                      <td key={i} style={{ textAlign: 'right', fontWeight: bold ? 700 : 400, ...colored(v) }}>\n                        {v !== 0 ? formatAriary(v) : '—'}\n                      </td>\n                    ))}\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  apportGrid: {\n    display: 'grid',\n    gridTemplateColumns: 'auto 1fr',\n    gap: '4px 12px',\n    alignItems: 'center',\n  },\n  apportLabel: {\n    fontSize: 'var(--text-xs)',\n    color: 'var(--color-text-muted)',\n    whiteSpace: 'nowrap',\n  },\n  apportInput: {\n    width: 100,\n    textAlign: 'right' as const,\n    fontSize: 'var(--text-xs)',\n    padding: '3px 6px',\n  },\n  inputRow: {\n    display: 'flex',\n    alignItems: 'center',\n    gap: 4,\n  },\n  unit: {\n    fontSize: 'var(--text-xs)',\n    color: 'var(--color-text-muted)',\n    whiteSpace: 'nowrap' as const,\n  },\n}\n","import { useMemo } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { computeAll, formatAriary } from '@/calculations/calculations'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst YEARS = ['An 1', 'An 2', 'An 3', 'An 4', 'An 5']\n\nexport default function BalanceSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">⚖️</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres dans la section Entreprise.</p>\n      </div>\n    )\n  }\n\n  const { balanceSheet: B, incomeStatement: IS } = result\n\n  // VNC = somme des yearlyBook de chaque investissement (s'arrête à 0 une fois amorti)\n  const netFixed = YEARS.map((_, y) =>\n    result.depreciationTable.byInvestment.reduce((sum, row) => sum + (row.yearlyBook[y] ?? 0), 0),\n  )\n  const cashByYear = B.cashByYear\n\n  // Total actif\n  const totalActif = YEARS.map((_, y) => netFixed[y] + Math.max(0, cashByYear[y]))\n\n  // Passif v20\n  const invEquity = company.investments.reduce((s, i) => s + i.financedEquity, 0)\n  const invGrant  = company.investments.reduce((s, i) => s + i.financedGrant, 0)\n  // Capitaux propres = fonds propres (invest.) + subventions + cumul résultats\n  const cumResult: number[] = IS.netIncomeByYear.reduce<number[]>((acc, _, y) => {\n    acc.push((acc[y - 1] ?? 0) + (y > 0 ? IS.netIncomeByYear[y - 1] : 0))\n    return acc\n  }, [])\n  const capitalPropres = YEARS.map((_, y) =>\n    invEquity + invGrant + cumResult[y] + IS.netIncomeByYear[y],\n  )\n\n  // Dettes financières restantes\n  const dettes = B.loanBalanceByYear\n\n  // Total passif\n  const totalPassif = YEARS.map((_, y) => capitalPropres[y] + Math.max(0, dettes[y]))\n\n  const BOLD: React.CSSProperties = { fontWeight: 700, background: 'var(--color-surface-2)' }\n  const colored = (v: number) =>\n    ({ color: v < 0 ? 'var(--color-danger)' : undefined } as React.CSSProperties)\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n            <i className=\"fas fa-scale-balanced\" style={{ marginRight: 8, color: '#3a7d2e' }} />\n            Bilans prévisionnels\n          </h3>\n          <p className=\"section-subtitle\">Bilan simplifié sur 5 ans — Actif = Passif</p>\n        </div>\n        <HelpButton\n          title=\"Bilan prévisionnel\"\n          content={\"Situation patrimoniale de l'entreprise à fin de chaque année.\\n\\n── ACTIF ──\\n=> Immobilisations nettes (VNC) : Valeur d'achat moins les amortissements cumulés depuis l'acquisition.\\n\\n=> Trésorerie active : Trésorerie initiale + cumul des flux de trésorerie jusqu'à l'année N (si positif).\\n\\n── PASSIF ──\\n=> Capitaux propres : Fonds propres initiaux + résultats nets cumulés de chaque année.\\n\\n=> Dettes financières : Capital restant dû sur les emprunts = Capital initial − remboursements cumulés.\\n\\n=> Découvert : Si la trésorerie est négative, elle apparaît au passif.\\n\\n=> Équilibre garanti : Total Actif = Total Passif par construction.\"}\n        />\n      </div>\n\n      <div className=\"card\">\n        <div className=\"card-header\"><span className=\"card-title\">Bilan prévisionnel (An 1 à An 5)</span></div>\n        <div className=\"table-wrapper\">\n          <table>\n            <thead>\n              <tr>\n                <th style={{ minWidth: 220 }}>Rubrique</th>\n                {YEARS.map((y) => <th key={y} style={{ textAlign: 'right', minWidth: 130 }}>{y}</th>)}\n              </tr>\n            </thead>\n            <tbody>\n              {/* ACTIF */}\n              <tr>\n                <td colSpan={6} style={{ background: 'var(--color-primary)', color: '#fff', fontWeight: 700, fontSize: 'var(--text-xs)', padding: '4px 12px' }}>\n                  ACTIF\n                </td>\n              </tr>\n              <tr>\n                <td style={{ paddingLeft: 20 }}>Immobilisations nettes (VNC)</td>\n                {netFixed.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right' }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr>\n                <td style={{ paddingLeft: 20 }}>Trésorerie</td>\n                {cashByYear.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr style={BOLD}>\n                <td>= TOTAL ACTIF</td>\n                {totalActif.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n\n              {/* PASSIF */}\n              <tr>\n                <td colSpan={6} style={{ background: 'var(--color-primary)', color: '#fff', fontWeight: 700, fontSize: 'var(--text-xs)', padding: '4px 12px' }}>\n                  PASSIF\n                </td>\n              </tr>\n              <tr>\n                <td style={{ paddingLeft: 20 }}>Capitaux propres</td>\n                {capitalPropres.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr>\n                <td style={{ paddingLeft: 20 }}>Dettes financières</td>\n                {dettes.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right' }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr style={BOLD}>\n                <td>= TOTAL PASSIF</td>\n                {totalPassif.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n\n              {/* Vérification équilibre */}\n              <tr>\n                <td style={{ paddingLeft: 20, color: 'var(--color-text-muted)', fontSize: 'var(--text-xs)' }}>\n                  Écart Actif - Passif\n                </td>\n                {YEARS.map((_, i) => {\n                  const ecart = totalActif[i] - totalPassif[i]\n                  return (\n                    <td key={i} style={{ textAlign: 'right', fontSize: 'var(--text-xs)', color: Math.abs(ecart) < 100 ? 'var(--color-success)' : 'var(--color-danger)' }}>\n                      {Math.abs(ecart) < 100 ? '✓ Équilibré' : formatAriary(ecart)}\n                    </td>\n                  )\n                })}\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      {/* Détail capitaux propres */}\n      <div className=\"card\">\n        <div className=\"card-header\"><span className=\"card-title\">Détail des capitaux propres</span></div>\n        <div className=\"table-wrapper\">\n          <table>\n            <thead>\n              <tr>\n                <th style={{ minWidth: 220 }}>Rubrique</th>\n                {YEARS.map((y) => <th key={y} style={{ textAlign: 'right', minWidth: 130 }}>{y}</th>)}\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>Capital initial + subventions</td>\n                {YEARS.map((_, i) => (\n                  <td key={i} style={{ textAlign: 'right' }}>{formatAriary(invEquity + invGrant)}</td>\n                ))}\n              </tr>\n              <tr>\n                <td>Résultats antérieurs cumulés</td>\n                {cumResult.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr>\n                <td>Résultat net</td>\n                {IS.netIncomeByYear.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n              <tr style={BOLD}>\n                <td>= Total capitaux propres</td>\n                {capitalPropres.map((v, i) => (\n                  <td key={i} style={{ textAlign: 'right', ...colored(v) }}>{formatAriary(v)}</td>\n                ))}\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n    </div>\n  )\n}\n","import { useMemo } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { computeAll, formatAriary } from '@/calculations/calculations'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst YEARS = ['An 1', 'An 2', 'An 3', 'An 4', 'An 5']\n\nexport default function FinancingSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">📊</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres dans la section Entreprise.</p>\n      </div>\n    )\n  }\n\n  const { incomeStatement: IS, loanRepaymentTable: LR } = result\n\n  const invEquity = company.investments.reduce((s, i) => s + i.financedEquity, 0)\n  const invLoan   = company.investments.reduce((s, i) => s + i.financedLoan, 0)\n  const invGrant  = company.investments.reduce((s, i) => s + i.financedGrant, 0)\n  const invTotal  = company.investments.reduce((s, i) => s + i.amount, 0)\n  const fdr       = settings.fondsRoulement ?? 0\n  const tresoInitiale = invEquity + invLoan + invGrant - invTotal + fdr\n\n  const afs = [1, 2, 3, 4, 5].map((yr) => {\n    const af = company.additionalFundings.find((f) => f.yearNumber === yr)\n    return af ?? { yearNumber: yr, equity: 0, loan: 0, loanRate: 0, loanYears: 5, grant: 0 }\n  })\n\n  const addEquity = afs.map((af) => af.equity)\n  const addLoan   = afs.map((af) => af.loan)\n  const addGrant  = afs.map((af) => af.grant)\n  const addTotal  = afs.map((af) => af.equity + af.loan + af.grant)\n\n  // Flux opérationnel = CAF - remb. capital\n  const opCF = IS.netIncomeByYear.map((n, y) => n + IS.depreciationByYear[y] - LR.totalCapitalByYear[y])\n\n  // Trésorerie cumulée\n  const cashCum: number[] = []\n  let running = tresoInitiale\n  for (let y = 0; y < 5; y++) {\n    running += opCF[y] + addTotal[y]\n    cashCum.push(Math.round(running))\n  }\n\n  // Trésorerie avant apport (sans l'apport de l'année)\n  const tresoBefore = [0, 1, 2, 3, 4].map((y) => {\n    const prev = y === 0 ? tresoInitiale : cashCum[y - 1]\n    return Math.round(prev + opCF[y])\n  })\n\n  const pct = (v: number, total: number) => total > 0 ? `${((v / total) * 100).toFixed(1)} %` : '—'\n  const colored = (v: number): React.CSSProperties =>\n    ({ color: v < 0 ? 'var(--color-danger)' : v > 0 ? 'var(--color-success)' : undefined })\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>Plan de financement</h3>\n          <p className=\"section-subtitle\">Financement initial (An 0) et apports complémentaires annuels si la trésorerie est déficitaire.</p>\n        </div>\n        <HelpButton\n          title=\"Plan de financement\"\n          content={\"Équilibre entre les besoins et les ressources financières.\\n\\n── EMPLOIS ──\\n=> Investissements : Total des montants saisis dans la section Investissements.\\n\\n=> Fonds de roulement : Trésorerie de démarrage saisie dans les paramètres.\\n\\n=> Remboursement emprunt : Capital remboursé annuellement (annuité constante).\\n\\n── RESSOURCES ──\\n=> Fonds propres : Apports en capital des associés/promoteurs.\\n\\n=> Emprunts : Montants empruntés, remboursables sur la durée définie.\\n\\n=> Subventions : Aides publiques non remboursables.\\n\\n=> CAF : Résultat net + Amortissements (cash généré par l'activité).\\n\\n=> Apports complémentaires : Nouveaux fonds ou emprunts prévus pour An 2 à An 5.\\n\\n=> Solde : Ressources − Emplois. Doit être ≥ 0 chaque année.\"}\n        />\n      </div>\n\n      {/* ─── Ligne 1 : Financement initial + Récapitulatif apports ─────────── */}\n      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-4)' }}>\n\n        {/* Financement initial */}\n        <div className=\"card\">\n          <div className=\"card-header\"><span className=\"card-title\">💰 Financement initial (An 0)</span></div>\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Source</th>\n                  <th style={{ textAlign: 'right' }}>Montant (Ar)</th>\n                  <th style={{ textAlign: 'right' }}>% total</th>\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td>Fonds propres (investissements)</td>\n                  <td style={{ textAlign: 'right' }}>{formatAriary(invEquity)}</td>\n                  <td style={{ textAlign: 'right' }}>{pct(invEquity, invTotal)}</td>\n                </tr>\n                <tr>\n                  <td>Emprunts initiaux</td>\n                  <td style={{ textAlign: 'right' }}>{formatAriary(invLoan)}</td>\n                  <td style={{ textAlign: 'right' }}>{pct(invLoan, invTotal)}</td>\n                </tr>\n                <tr>\n                  <td>Subventions initiales</td>\n                  <td style={{ textAlign: 'right' }}>{formatAriary(invGrant)}</td>\n                  <td style={{ textAlign: 'right' }}>{pct(invGrant, invTotal)}</td>\n                </tr>\n                <tr style={{ fontWeight: 700, borderTop: '2px solid var(--color-border)' }}>\n                  <td>Total financement investissements</td>\n                  <td style={{ textAlign: 'right' }}>{formatAriary(invTotal)}</td>\n                  <td style={{ textAlign: 'right' }}>100 %</td>\n                </tr>\n                <tr>\n                  <td style={{ color: 'var(--color-text-muted)' }}>+ Fonds de roulement initial</td>\n                  <td style={{ textAlign: 'right' }}>{formatAriary(fdr)}</td>\n                  <td />\n                </tr>\n                <tr style={{ fontWeight: 800, color: 'var(--color-primary)' }}>\n                  <td>→ Trésorerie de départ</td>\n                  <td colSpan={2} style={{ textAlign: 'right' }}>{formatAriary(tresoInitiale)}</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        {/* Récapitulatif apports */}\n        <div className=\"card\">\n          <div className=\"card-header\"><span className=\"card-title\">📊 Récapitulatif des apports</span></div>\n          <div className=\"table-wrapper\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Source</th>\n                  {YEARS.map((y) => <th key={y} style={{ textAlign: 'right' }}>{y}</th>)}\n                  <th style={{ textAlign: 'right' }}>Total</th>\n                </tr>\n              </thead>\n              <tbody>\n                {[\n                  { label: 'Fonds propres additionnels', data: addEquity },\n                  { label: 'Emprunts additionnels',      data: addLoan   },\n                  { label: 'Subventions additionnelles', data: addGrant  },\n                ].map(({ label, data }) => (\n                  <tr key={label}>\n                    <th style={{ fontWeight: 400 }}>{label}</th>\n                    {data.map((v, i) => <td key={i} style={{ textAlign: 'right' }}>{formatAriary(v)}</td>)}\n                    <td style={{ textAlign: 'right', fontWeight: 700 }}>\n                      {formatAriary(data.reduce((s, v) => s + v, 0))}\n                    </td>\n                  </tr>\n                ))}\n                <tr style={{ fontWeight: 700, borderTop: '2px solid var(--color-border)', background: 'var(--color-surface-2)' }}>\n                  <th>Total apports</th>\n                  {addTotal.map((v, i) => (\n                    <td key={i} style={{ textAlign: 'right' }}>{formatAriary(v)}</td>\n                  ))}\n                  <td style={{ textAlign: 'right' }}>\n                    {formatAriary(addTotal.reduce((s, v) => s + v, 0))}\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      {/* ─── Apports complémentaires annuels ────────────────────────────────── */}\n      <div className=\"card\">\n        <div className=\"card-header\">\n          <span className=\"card-title\">📈 Apports complémentaires annuels — Trésorerie avant/après</span>\n        </div>\n        <div className=\"table-wrapper\">\n          <table>\n            <thead>\n              <tr>\n                <th>Année</th>\n                <th style={{ textAlign: 'right' }}>Tréso. avant apport</th>\n                <th style={{ textAlign: 'right' }}>Fonds propres (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Emprunt (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Subvention (Ar)</th>\n                <th style={{ textAlign: 'right' }}>Total apport</th>\n                <th style={{ textAlign: 'right' }}>Tréso. après</th>\n              </tr>\n            </thead>\n            <tbody>\n              {afs.map((af, i) => {\n                const neg = tresoBefore[i] < 0\n                return (\n                  <tr key={i}>\n                    <td>\n                      <strong>An {i + 1}</strong>\n                      {neg && <span style={{ color: 'var(--color-danger)', fontSize: 'var(--text-xs)', marginLeft: 6 }}>⚠</span>}\n                    </td>\n                    <td style={{ textAlign: 'right', fontWeight: 700, ...colored(tresoBefore[i]) }}>\n                      {formatAriary(tresoBefore[i])}\n                    </td>\n                    <td style={{ textAlign: 'right' }}>{formatAriary(af.equity)}</td>\n                    <td style={{ textAlign: 'right' }}>{formatAriary(af.loan)}</td>\n                    <td style={{ textAlign: 'right' }}>{formatAriary(af.grant)}</td>\n                    <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatAriary(addTotal[i])}</td>\n                    <td style={{ textAlign: 'right', fontWeight: 800, ...colored(cashCum[i]) }}>\n                      {formatAriary(cashCum[i])}\n                    </td>\n                  </tr>\n                )\n              })}\n            </tbody>\n          </table>\n        </div>\n        <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', padding: 'var(--space-3) var(--space-4)' }}>\n          ⚠ = trésorerie déficitaire avant apport. Pour modifier les apports, allez dans la section <strong>Trésorerie</strong>.\n        </p>\n      </div>\n    </div>\n  )\n}\n","import { useMemo } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { computeAll, formatAriary, formatPct } from '@/calculations/calculations'\nimport HelpButton from '@/components/ui/HelpButton'\n\nconst YEARS = ['An 1', 'An 2', 'An 3', 'An 4', 'An 5']\n\nexport default function ProfitabilitySection() {\n  const company = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">📈</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres dans la section Entreprise.</p>\n      </div>\n    )\n  }\n\n  const { profitability: KPI, incomeStatement: IS, cashFlowStatement: CF } = result\n\n  // Seuil de rentabilité An 1\n  const rev1 = IS.revenueByYear[0] ?? 0\n  const vc1  = IS.materialCostByYear[0] ?? 0\n  const fc1  = (IS.staffCostByYear[0] ?? 0) + (IS.expenseCostByYear[0] ?? 0) + (IS.depreciationByYear[0] ?? 0)\n  const marginRate1 = rev1 > 0 ? (rev1 - vc1) / rev1 : 0\n  const breakEven   = marginRate1 > 0 ? Math.round(fc1 / marginRate1) : 0\n\n  const vanColor = (KPI.npv ?? 0) >= 0 ? 'var(--color-success)' : 'var(--color-danger)'\n  const paybackLabel = KPI.paybackYear != null ? KPI.paybackYear + ' an(s)' : 'Non atteint sur 5 ans'\n  const triLabel = KPI.irr != null ? formatPct(KPI.irr) : 'N/A'\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>\n        <div>\n          <h3 className=\"section-title\" style={{ marginBottom: 4 }}>Rentabilité</h3>\n          <p className=\"section-subtitle\">Indicateurs de performance financière du projet sur 5 ans.</p>\n        </div>\n        <HelpButton\n          title=\"Indicateurs de rentabilité\"\n          content={\"Mesures de performance financière globale du projet.\\n\\n=> VAN : Somme des flux nets actualisés au taux d'actualisation (paramètres). VAN > 0 = projet rentable.\\n\\n=> TRI : Taux d'actualisation qui annule la VAN, calculé par dichotomie sur les flux nets.\\n\\n=> Indice de profitabilité : VAN ÷ Investissement initial. > 1 = chaque ariary investi rapporte plus d'un ariary.\\n\\n=> Délai de récupération : Première année où la trésorerie cumulée redevient positive.\\n\\n=> Seuil de rentabilité An 1 : Charges fixes ÷ Taux de marge sur coût variable. Taux de marge = (CA − Matières) ÷ CA.\\n\\n=> Marge brute : CA − Coût des matières premières.\\n\\n=> EBE : Marge brute − Charges de personnel − Charges d'exploitation.\\n\\n=> Résultat net / CA : Rentabilité nette en % du chiffre d'affaires.\"}\n        />\n      </div>\n\n      {/* ─── Ligne 1 : Indicateurs + Interprétation ──────────────────────────── */}\n      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-4)' }}>\n\n        {/* Indicateurs financiers */}\n        <div className=\"card\">\n          <div className=\"card-header\"><span className=\"card-title\">Indicateurs financiers</span></div>\n          <div style={{ padding: 'var(--space-4)' }}>\n            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>\n              <Field label=\"VAN\">\n                <span style={{ fontWeight: 800, color: vanColor, fontSize: '1.1rem' }}>\n                  {formatAriary(KPI.npv ?? 0)}\n                </span>\n              </Field>\n              <Field label=\"TRI\">\n                <span style={{ fontWeight: 800, fontSize: '1.1rem' }}>{triLabel}</span>\n              </Field>\n              <Field label=\"Délai de récupération\">\n                <span style={{ fontWeight: 700 }}>{paybackLabel}</span>\n              </Field>\n              <Field label=\"Seuil de rentabilité An 1\">\n                <span style={{ fontWeight: 700 }}>{formatAriary(breakEven)}</span>\n              </Field>\n              <Field label=\"Taux de marge sur coûts variables\">\n                <span>{formatPct(marginRate1 * 100)}</span>\n              </Field>\n              <Field label=\"Taux d'actualisation utilisé\">\n                <span>{formatPct(settings.discountRate)}</span>\n              </Field>\n            </div>\n          </div>\n        </div>\n\n        {/* Interprétation */}\n        <div className=\"card\">\n          <div className=\"card-header\"><span className=\"card-title\">Interprétation</span></div>\n          <div style={{ padding: 'var(--space-4)', display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>\n            <p style={{ margin: 0, lineHeight: 1.6 }}>\n              Une VAN positive signifie que le projet crée de la valeur au-delà du coût du capital.\n              Un TRI supérieur au taux d'actualisation confirme la rentabilité.\n            </p>\n            <p style={{ margin: 0, lineHeight: 1.6 }}>\n              Le seuil de rentabilité est le chiffre d'affaires minimum à atteindre pour couvrir\n              l'ensemble des charges fixes.\n            </p>\n          </div>\n        </div>\n      </div>\n\n      {/* ─── Tableau évolution 5 ans ─────────────────────────────────────────── */}\n      <div className=\"card\">\n        <div className=\"card-header\"><span className=\"card-title\">Évolution du résultat net sur 5 ans</span></div>\n        <div className=\"table-wrapper\">\n          <table>\n            <thead>\n              <tr>\n                <th style={{ minWidth: 220 }}>Indicateur</th>\n                {YEARS.map((y) => <th key={y} style={{ textAlign: 'right' }}>{y}</th>)}\n              </tr>\n            </thead>\n            <tbody>\n              <Row label=\"Chiffre d'affaires\" data={IS.revenueByYear} fmt={formatAriary} />\n              <Row label=\"EBITDA\" data={IS.ebitdaByYear} fmt={formatAriary} colored />\n              <Row label=\"(-) Frais financiers\" data={IS.interestByYear.map((v) => -v)} fmt={formatAriary} colored />\n              <Row label=\"Résultat net\" data={IS.netIncomeByYear} fmt={formatAriary} bold colored />\n              <Row label=\"Trésorerie cumulée\" data={CF.cumulativeCashByYear} fmt={formatAriary} bold colored />\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  )\n}\n\nfunction Field({ label, children }: { label: string; children: React.ReactNode }) {\n  return (\n    <div style={{ background: 'var(--color-surface-2)', borderRadius: 'var(--radius)', padding: 'var(--space-3)' }}>\n      <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', marginBottom: 4 }}>{label}</div>\n      <div>{children}</div>\n    </div>\n  )\n}\n\nfunction Row({ label, data, fmt, bold, colored: useColored }: {\n  label: string\n  data: number[]\n  fmt: (v: number) => string\n  bold?: boolean\n  colored?: boolean\n}) {\n  return (\n    <tr style={{ fontWeight: bold ? 700 : 400, background: bold ? 'var(--color-surface-2)' : undefined }}>\n      <td style={{ fontWeight: bold ? 700 : 400 }}>{label}</td>\n      {data.map((v, i) => (\n        <td key={i} style={{\n          textAlign: 'right',\n          fontWeight: bold ? 700 : 400,\n          color: useColored ? (v < 0 ? 'var(--color-danger)' : v > 0 ? 'var(--color-success)' : undefined) : undefined,\n        }}>\n          {fmt(v)}\n        </td>\n      ))}\n    </tr>\n  )\n}\n","import { useMemo } from 'react'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { computeAll, formatAriary, formatPct } from '@/calculations/calculations'\n\nexport default function SyntheseSection() {\n  const company = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  if (!settings || !result) {\n    return (\n      <div className=\"empty-state\">\n        <div className=\"empty-state-icon\">📄</div>\n        <div className=\"empty-state-title\">Paramètres manquants</div>\n        <p className=\"empty-state-desc\">Définissez les paramètres économiques pour afficher la synthèse.</p>\n      </div>\n    )\n  }\n\n  const { incomeStatement: IS, profitability: KPI } = result\n\n  const rev1  = IS.revenueByYear[0]   ?? 0\n  const rev5  = IS.revenueByYear[4]   ?? 0\n  const net1  = IS.netIncomeByYear[0] ?? 0\n  const net5  = IS.netIncomeByYear[4] ?? 0\n  const van   = KPI.npv ?? 0\n  const tri   = KPI.irr\n  const payback = KPI.paybackYear\n\n  const vc1  = IS.materialCostByYear[0]  ?? 0\n  const fc1  = (IS.staffCostByYear[0]    ?? 0)\n             + (IS.expenseCostByYear[0]  ?? 0)\n             + (IS.depreciationByYear[0] ?? 0)\n  const mr1  = rev1 > 0 ? (rev1 - vc1) / rev1 : 0\n  const breakEven = mr1 > 0 ? Math.round(fc1 / mr1) : 0\n\n  const coloredStyle = (v: number): React.CSSProperties => ({\n    fontWeight: 700,\n    color: v >= 0 ? 'var(--color-success)' : 'var(--color-danger)',\n  })\n\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>\n      <div>\n        <h3 className=\"section-title\" style={{ marginBottom: 4 }}>Synthèse</h3>\n        <p className=\"section-subtitle\">Résumé exécutif des principaux indicateurs financiers.</p>\n      </div>\n\n      <div className=\"card\">\n        <div className=\"card-header\"><span className=\"card-title\">Résumé financier</span></div>\n        <div style={{ padding: 'var(--space-4)' }}>\n          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>\n            <Field label=\"CA An 1\">\n              <span style={{ fontWeight: 700 }}>{formatAriary(rev1)}</span>\n            </Field>\n            <Field label=\"CA An 5\">\n              <span style={{ fontWeight: 700 }}>{formatAriary(rev5)}</span>\n            </Field>\n            <Field label=\"Résultat net An 1\">\n              <span style={coloredStyle(net1)}>{formatAriary(net1)}</span>\n            </Field>\n            <Field label=\"Résultat net An 5\">\n              <span style={coloredStyle(net5)}>{formatAriary(net5)}</span>\n            </Field>\n            <Field label=\"VAN\">\n              <span style={coloredStyle(van)}>{formatAriary(van)}</span>\n            </Field>\n            <Field label=\"TRI\">\n              <span style={{ fontWeight: 700 }}>{tri != null ? formatPct(tri) : 'N/A'}</span>\n            </Field>\n            <Field label=\"Seuil de rentabilité\">\n              <span>{formatAriary(breakEven)}</span>\n            </Field>\n            <Field label=\"Délai de récupération\">\n              <span>{payback != null ? payback + ' an(s)' : 'Non atteint'}</span>\n            </Field>\n          </div>\n        </div>\n      </div>\n    </div>\n  )\n}\n\nfunction Field({ label, children }: { label: string; children: React.ReactNode }) {\n  return (\n    <div style={{ background: 'var(--color-surface-2)', borderR