onst MONTHS  = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc']\n\n// ─── Palette ──────────────────────────────────────────────────────────────────\nconst C = {\n  darkBg:     '1E2433',\n  primary:    '3A7D2E',\n  primaryLt:  '2D6324',\n  accent:     'F5A623',\n  lightGreen: 'EAF5E6',\n  lightBlue:  'EFF6FF',\n  lightGray:  'F8FAFC',\n  border:     'E2E8F0',\n  white:      'FFFFFF',\n  textDark:   '1A1A1A',\n  textMuted:  '6B7280',\n  danger:     'DC2626',\n  dangerLt:   'FEF2F2',\n  success:    '16A34A',\n  blue:       '2563EB',\n  purple:     '7C3AED',\n  orange:     'B45309',\n  rowAlt:     'F0FDF4',\n}\n\n// ─── Helpers de style ─────────────────────────────────────────────────────────\nfunction allBorder(color = C.border) {\n  const side = { style: 'thin', color: { rgb: color } }\n  return { top: side, bottom: side, left: side, right: side }\n}\n\nfunction hdr(text: string): object {\n  return { v: text, t: 's', s: {\n    font: { bold: true, sz: 10, color: { rgb: C.white } },\n    fill: { fgColor: { rgb: C.darkBg } },\n    alignment: { horizontal: 'center', vertical: 'center', wrapText: true },\n    border: allBorder(),\n  }}\n}\n\nfunction subHdr(text: string, bg = C.primary): object {\n  return { v: text, t: 's', s: {\n    font: { bold: true, sz: 10, color: { rgb: C.white } },\n    fill: { fgColor: { rgb: bg } },\n    alignment: { horizontal: 'center', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\nfunction sectionRow(text: string, bg = C.primary): object {\n  return { v: text, t: 's', s: {\n    font: { bold: true, sz: 10, color: { rgb: C.white } },\n    fill: { fgColor: { rgb: bg } },\n    alignment: { horizontal: 'left', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\nfunction lbl(text: string, bold = false, indent = false, bg?: string): object {\n  return { v: text, t: 's', s: {\n    font: { bold, sz: 10, color: { rgb: C.textDark } },\n    fill: { fgColor: { rgb: bg ?? C.white } },\n    alignment: { horizontal: 'left', vertical: 'center', indent: indent ? 1 : 0 },\n    border: allBorder(),\n  }}\n}\n\nfunction num(value: number, bold = false, colored = false, bg?: string): object {\n  const color = colored ? (value >= 0 ? C.success : C.danger) : C.textDark\n  return { v: value, t: 'n', z: '#,##0', s: {\n    font: { sz: 10, color: { rgb: color }, bold },\n    fill: { fgColor: { rgb: bg ?? C.white } },\n    alignment: { horizontal: 'right', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\nfunction numPct(value: number, bold = false, colored = false): object {\n  const color = colored ? (value >= 0 ? C.success : C.danger) : C.textDark\n  return { v: value / 100, t: 'n', z: '0.0%', s: {\n    font: { sz: 10, color: { rgb: color }, bold },\n    fill: { fgColor: { rgb: C.white } },\n    alignment: { horizontal: 'right', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\n/** Cellule avec formule Excel (valeur mise en cache pour compatibilité xlsx) */\nfunction numF(formula: string, v: number, bold = false, colored = false, bg?: string): object {\n  const color = colored ? (v >= 0 ? C.success : C.danger) : C.textDark\n  return { f: formula, v, t: 'n', z: '#,##0', s: {\n    font: { sz: 10, color: { rgb: color }, bold },\n    fill: { fgColor: { rgb: bg ?? C.white } },\n    alignment: { horizontal: 'right', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\n/** Cellule % avec formule (la formule renvoie un ratio décimal 0–1) */\nfunction numPctF(formula: string, v: number, bold = false, colored = false): object {\n  const color = colored ? (v >= 0 ? C.success : C.danger) : C.textDark\n  return { f: formula, v: v / 100, t: 'n', z: '0.0%', s: {\n    font: { sz: 10, color: { rgb: color }, bold },\n    fill: { fgColor: { rgb: C.white } },\n    alignment: { horizontal: 'right', vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\n/** Lettre(s) de colonne Excel à partir d'un index 0-basé (A=0, Z=25, AA=26…) */\nfunction colLetter(i: number): string {\n  return i < 26\n    ? String.fromCharCode(65 + i)\n    : String.fromCharCode(64 + Math.floor(i / 26)) + String.fromCharCode(65 + (i % 26))\n}\n\n/** Adresse Excel d'une cellule (r et c sont tous les deux 0-indexés) */\nfunction cellAddr(r: number, c: number): string { return colLetter(c) + (r + 1) }\n\nfunction txt(text: string, bold = false, color = C.textDark, bg?: string, align: 'left'|'center'|'right' = 'left'): object {\n  return { v: text, t: 's', s: {\n    font: { bold, sz: 10, color: { rgb: color } },\n    fill: { fgColor: { rgb: bg ?? C.white } },\n    alignment: { horizontal: align, vertical: 'center' },\n    border: allBorder(),\n  }}\n}\n\nfunction empty(bg = C.white): object {\n  return { v: '', t: 's', s: { fill: { fgColor: { rgb: bg } }, border: allBorder() } }\n}\n\nfunction setRow(ws: Record<string,unknown>, row: object[], rowIdx: number) {\n  ;(row as Array<Record<string,unknown>>).forEach((cell, col) => {\n    ws[XLSXStyle.utils.encode_cell({ r: rowIdx, c: col })] = cell\n  })\n}\n\nfunction merge(ws: Record<string,unknown>, r1: number, c1: number, r2: number, c2: number) {\n  ws['!merges'] = ws['!merges'] || []\n  ;(ws['!merges'] as object[]).push({ s: { r: r1, c: c1 }, e: { r: r2, c: c2 } })\n}\n\nfunction setRange(ws: Record<string,unknown>, rows: number, cols: number) {\n  ws['!ref'] = XLSXStyle.utils.encode_range({ s: { r:0, c:0 }, e: { r: rows-1, c: cols-1 } })\n}\n\nfunction titleBlock(ws: Record<string,unknown>, company: string, title: string, cols: number, r0: number): number {\n  ws[XLSXStyle.utils.encode_cell({ r: r0, c: 0 })] = {\n    v: company, t: 's', s: {\n      font: { bold: true, sz: 14, color: { rgb: C.white } },\n      fill: { fgColor: { rgb: C.darkBg } },\n      alignment: { horizontal: 'center', vertical: 'center' },\n    },\n  }\n  merge(ws, r0, 0, r0, cols-1)\n  ws[XLSXStyle.utils.encode_cell({ r: r0+1, c: 0 })] = {\n    v: title, t: 's', s: {\n      font: { bold: true, sz: 11, color: { rgb: C.white } },\n      fill: { fgColor: { rgb: C.primary } },\n      alignment: { horizontal: 'center', vertical: 'center' },\n    },\n  }\n  merge(ws, r0+1, 0, r0+1, cols-1)\n  return r0+2\n}\n\n// ─── Feuille 1 : Synthèse ─────────────────────────────────────────────────────\nfunction buildSyntheseSheet(\n  result: ReturnType<typeof computeAll>,\n  company: { name: string; secteur?: string; [k:string]: unknown },\n  settings: { discountRate: number; taxRegime: string; fondsRoulement?: number },\n  products: { length: number },\n  staffMembers: Array<{ headcount: number }>,\n  investments: Investment[],\n): Record<string,unknown> {\n  const IS = result.incomeStatement\n  const CF = result.cashFlowStatement\n  const KPI = result.profitability\n  const R = result.profitabilityRatios\n  const ws: Record<string,unknown> = {}\n  const COLS = 7\n  let r = 0\n\n  r = titleBlock(ws, company.name as string, 'SYNTHÈSE DU BUSINESS PLAN', COLS, r)\n\n  // ── Infos entreprise ──────────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('📋  INFORMATIONS GÉNÉRALES')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  const infoRows: [string, string][] = [\n    ['Nom de l\\'entreprise', company.name as string],\n    ['Secteur d\\'activité', (company.secteur as string) || '—'],\n    ['Promoteur', (company as Record<string,unknown>).promoteur as string || '—'],\n    ['Régime fiscal', settings.taxRegime],\n    ['Taux d\\'actualisation', `${settings.discountRate} %`],\n    ['Nombre de produits', String(products.length)],\n    ['Effectif total', `${staffMembers.reduce((s,m) => s + m.headcount, 0)} personnes`],\n  ]\n  infoRows.forEach(([k, v]) => {\n    setRow(ws, [lbl(k, true, false, C.lightGray), txt(v, false, C.textDark, C.white), ...Array(COLS-2).fill(empty())], r++)\n  })\n  r++ // blank\n\n  // ── Indicateurs de décision ───────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('🎯  INDICATEURS DE DÉCISION')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Indicateur'), hdr('Valeur'), hdr('Interprétation'), ...Array(COLS-3).fill(empty(C.darkBg))], r++)\n\n  const kpiRows: [string, string, boolean][] = [\n    ['VAN (Valeur Actuelle Nette)', formatAriary(KPI.npv), KPI.npv >= 0],\n    ['TRI (Taux de Rentabilité Interne)', KPI.irr !== null ? `${KPI.irr.toFixed(1)} %` : 'N/A', KPI.irr !== null && KPI.irr > settings.discountRate],\n    ['Indice de profitabilité (IP)', KPI.profitabilityIndex.toFixed(2), KPI.profitabilityIndex >= 1],\n    ['Délai de récupération', KPI.paybackYear !== null ? `An ${KPI.paybackYear}` : '> 5 ans', KPI.paybackYear !== null && KPI.paybackYear <= 3],\n    ['Seuil de rentabilité (1ère année positive)', KPI.breakEvenYear !== null ? `An ${KPI.breakEvenYear}` : '> 5 ans', KPI.breakEvenYear !== null],\n  ]\n  const kpiNotes: Record<string,string> = {\n    'VAN (Valeur Actuelle Nette)':               KPI.npv >= 0 ? '✅ Projet crée de la valeur' : '❌ Projet détruit de la valeur',\n    'TRI (Taux de Rentabilité Interne)':         KPI.irr !== null ? (KPI.irr > settings.discountRate ? `✅ TRI > taux actualisation (${settings.discountRate} %)` : `⚠️  TRI < taux actualisation (${settings.discountRate} %)`) : 'Flux insuffisants',\n    'Indice de profitabilité (IP)':              KPI.profitabilityIndex >= 1 ? '✅ Chaque Ar investi génère un gain' : '❌ Rendement insuffisant',\n    'Délai de récupération':                     KPI.paybackYear !== null ? (KPI.paybackYear <= 3 ? '✅ Récupération rapide' : '⚠️  Récupération lente') : '❌ Non récupéré sur 5 ans',\n    'Seuil de rentabilité (1ère année positive)': KPI.breakEvenYear !== null ? '✅ Bénéfice atteint dans la période' : '❌ Pas de bénéfice sur 5 ans',\n  }\n  kpiRows.forEach(([ind, val, ok]) => {\n    const valColor = ok ? C.success : C.danger\n    const valBg    = ok ? C.lightGreen : C.dangerLt\n    setRow(ws, [\n      lbl(ind, true),\n      { v: val, t: 's', s: { font: { bold: true, sz: 11, color: { rgb: valColor } }, fill: { fgColor: { rgb: valBg } }, alignment: { horizontal: 'center', vertical: 'center' }, border: allBorder() } },\n      txt(kpiNotes[ind] ?? '', false, C.textMuted),\n      ...Array(COLS-3).fill(empty()),\n    ], r++)\n  })\n  r++\n\n  // ── Synthèse financière 5 ans ─────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('📊  SYNTHÈSE FINANCIÈRE 5 ANS (en Ar)')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Indicateur'), ...YEARS.map(y => hdr(y)), empty(C.darkBg)].slice(0, COLS), r++)\n\n  const finRows: [string, number[], boolean, boolean][] = [\n    [\"Chiffre d'affaires\",  IS.revenueByYear,        true,  false],\n    ['Marge brute',         IS.grossMarginByYear,     false, false],\n    ['Marge brute %',       R.grossMarginPctByYear,   false, false],\n    ['EBITDA',              IS.ebitdaByYear,          true,  false],\n    ['EBITDA margin %',     R.ebitdaMarginPctByYear,  false, false],\n    ['Résultat net',        IS.netIncomeByYear,       true,  true ],\n    ['Marge nette %',       R.netMarginPctByYear,     false, true ],\n    ['Trésorerie cumulée',  CF.cumulativeCashByYear,  true,  true ],\n  ]\n  const pctFields = new Set(['Marge brute %', 'EBITDA margin %', 'Marge nette %'])\n  finRows.forEach(([label_, data, bold, colored]) => {\n    const bg = bold ? C.lightGreen : undefined\n    const isPct = pctFields.has(label_)\n    setRow(ws, [\n      lbl(label_, bold, !bold),\n      ...data.map(v => isPct ? numPct(v, bold, colored) : num(v, bold, colored, bg)),\n      empty(),\n    ].slice(0, COLS), r++)\n  })\n  r++\n\n  // ── Structure du financement ──────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('💰  STRUCTURE DU FINANCEMENT INITIAL')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  const totalInv   = investments.reduce((s,i) => s + i.amount, 0)\n  const totalEq    = investments.reduce((s,i) => s + i.financedEquity, 0)\n  const totalLoan  = investments.reduce((s,i) => s + i.financedLoan, 0)\n  const totalGrant = investments.reduce((s,i) => s + i.financedGrant, 0)\n\n  setRow(ws, [hdr('Source'), hdr('Montant (Ar)'), hdr('Part %'), ...Array(COLS-3).fill(empty(C.darkBg))], r++)\n  const fundRows: [string, number][] = [\n    ['Investissement total', totalInv],\n    ['Fonds propres',        totalEq],\n    ['Emprunts',             totalLoan],\n    ['Subventions',          totalGrant],\n  ]\n  fundRows.forEach(([name, val], i) => {\n    const pct = totalInv > 0 ? val / totalInv : 0\n    setRow(ws, [\n      lbl(name, i === 0, false, i === 0 ? C.lightGreen : undefined),\n      num(val, i === 0, false, i === 0 ? C.lightGreen : undefined),\n      { v: pct, t: 'n', z: '0.0%', s: { font: { sz: 10, color: { rgb: C.textDark } }, fill: { fgColor: { rgb: i === 0 ? C.lightGreen : C.white } }, alignment: { horizontal: 'right' }, border: allBorder() } },\n      ...Array(COLS-3).fill(empty()),\n    ], r++)\n  })\n\n  ws['!cols'] = [220, 140, 90, 90, 90, 90, 90].map(w => ({ wpx: w }))\n  ws['!rows'] = [{ hpx: 28 }, { hpx: 22 }]\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Références inter-feuilles (données de base → autres feuilles) ────────────\ninterface DataSheetRefs {\n  totalCAExcelRow: number      // ligne Excel (1-indexée) du total CA\n  totalMatExcelRow: number     // ligne Excel du total matières\n  totalStaffExcelRow: number   // ligne Excel du total personnel\n  totalChargesExcelRow: number // ligne Excel du total charges\n  caAnCol: number              // index colonne 0-basé pour An 1 (produits/matières/charges) = 3 → D\n  staffAnCol: number           // index colonne 0-basé pour An 1 (personnel) = 4 → E\n}\n\n// ─── Feuille 2 : Données de base ─────────────────────────────────────────────\nfunction buildDataSheet(\n  result: ReturnType<typeof computeAll>,\n  products: Product[],\n  materials: Material[],\n  staffMembers: StaffMember[],\n  expenses: Expense[],\n  companyName: string,\n): { ws: Record<string,unknown>; refs: DataSheetRefs } {\n  const ws: Record<string,unknown> = {}\n  const COLS = 8\n  let r = 0\n  r = titleBlock(ws, companyName, 'DONNÉES DE BASE', COLS, r)\n  // r = 2 ici\n\n  // ── Produits ──────────────────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('🛒  PRODUITS & VENTES')\n  merge(ws, r, 0, r, COLS-1); r++ // r=3\n\n  setRow(ws, [hdr('Produit'), hdr('Prix unit. (Ar)'), hdr('Qté base/an'), ...YEARS.map(y => hdr(`CA ${y}`))].slice(0, COLS), r++) // r=4\n\n  // Lignes produits : r=4 .. 3+n  (Excel 5..4+n)\n  const prodFirstRow = r // = 4, Excel row = 5\n  products.forEach(p => {\n    const baseQty = p.monthlyQty.reduce((a,b) => a+b, 0)\n    setRow(ws, [\n      lbl(p.name, true),\n      num(p.price),\n      num(baseQty),\n      ...Array.from({ length: 5 }, (_, y) => num(productRevenueByYear(p, y))),\n    ].slice(0, COLS), r++)\n  })\n  // TOTAL CA : r=4+n → Excel row 5+n\n  const totalCARow = r // 0-indexed\n  const caAnCol = 3    // colonne D (An 1)\n  setRow(ws, [\n    lbl('TOTAL CA', true, false, C.lightGreen),\n    empty(C.lightGreen),\n    empty(C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      products.length > 0\n        ? numF(\n            `SUM(${colLetter(caAnCol + yi)}${prodFirstRow + 1}:${colLetter(caAnCol + yi)}${r})`,\n            result.incomeStatement.revenueByYear[yi],\n            true, false, C.lightGreen,\n          )\n        : num(result.incomeStatement.revenueByYear[yi], true, false, C.lightGreen),\n    ),\n  ].slice(0, COLS), r++)\n  r++ // blank\n\n  // ── Matières premières ────────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('📦  MATIÈRES PREMIÈRES')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Matière'), hdr('Coût unit. (Ar)'), hdr('Qté base/an'), ...YEARS.map(y => hdr(`Coût ${y}`))].slice(0, COLS), r++)\n\n  const matFirstRow = r\n  materials.forEach(m => {\n    const baseQty = m.monthlyQty.reduce((a,b) => a+b, 0)\n    setRow(ws, [\n      lbl(m.name, true),\n      num(m.unitCost),\n      num(baseQty),\n      ...Array.from({ length: 5 }, (_, y) => num(materialCostByYear(m, y))),\n    ].slice(0, COLS), r++)\n  })\n  const totalMatRow = r\n  setRow(ws, [\n    lbl('TOTAL MATIÈRES', true, false, C.lightGreen),\n    empty(C.lightGreen),\n    empty(C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      materials.length > 0\n        ? numF(\n            `SUM(${colLetter(caAnCol + yi)}${matFirstRow + 1}:${colLetter(caAnCol + yi)}${r})`,\n            result.incomeStatement.materialCostByYear[yi],\n            true, false, C.lightGreen,\n          )\n        : num(result.incomeStatement.materialCostByYear[yi], true, false, C.lightGreen),\n    ),\n  ].slice(0, COLS), r++)\n  r++ // blank\n\n  // ── Personnel ─────────────────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('👥  PERSONNEL')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Poste'), hdr('Salaire mens. (Ar)'), hdr('Effectif'), hdr('Charges soc. %'), ...YEARS.map(y => hdr(`Coût ${y}`))].slice(0, COLS), r++)\n\n  const staffFirstRow = r\n  const staffAnCol = 4 // colonne E (An 1)\n  staffMembers.forEach(s => {\n    setRow(ws, [\n      lbl(s.roleName, true),\n      num(s.monthlySalary),\n      num(s.headcount),\n      numPct(s.chargesRate),\n      ...Array.from({ length: 5 }, (_, y) => num(staffAnnualCostByYear(s, y))),\n    ].slice(0, COLS), r++)\n  })\n  const totalStaffRow = r\n  setRow(ws, [\n    lbl('TOTAL PERSONNEL', true, false, C.lightGreen),\n    empty(C.lightGreen),\n    empty(C.lightGreen),\n    empty(C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      staffMembers.length > 0\n        ? numF(\n            `SUM(${colLetter(staffAnCol + yi)}${staffFirstRow + 1}:${colLetter(staffAnCol + yi)}${r})`,\n            result.incomeStatement.staffCostByYear[yi],\n            true, false, C.lightGreen,\n          )\n        : num(result.incomeStatement.staffCostByYear[yi], true, false, C.lightGreen),\n    ),\n  ].slice(0, COLS), r++)\n  r++ // blank\n\n  // ── Charges d'exploitation ────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('🧾  CHARGES D\\'EXPLOITATION')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Désignation'), hdr('Montant mens. (Ar)'), hdr(''), ...YEARS.map(y => hdr(`Coût ${y}`))].slice(0, COLS), r++)\n\n  const expFirstRow = r\n  expenses.forEach(e => {\n    setRow(ws, [\n      lbl(e.name, true),\n      num(e.monthlyAmount),\n      empty(),\n      ...Array.from({ length: 5 }, (_, y) => num(expenseTotalByYear(e, y))),\n    ].slice(0, COLS), r++)\n  })\n  const totalChargesRow = r\n  setRow(ws, [\n    lbl('TOTAL CHARGES', true, false, C.lightGreen),\n    empty(C.lightGreen),\n    empty(C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      expenses.length > 0\n        ? numF(\n            `SUM(${colLetter(caAnCol + yi)}${expFirstRow + 1}:${colLetter(caAnCol + yi)}${r})`,\n            result.incomeStatement.expenseCostByYear[yi],\n            true, false, C.lightGreen,\n          )\n        : num(result.incomeStatement.expenseCostByYear[yi], true, false, C.lightGreen),\n    ),\n  ].slice(0, COLS), r++)\n\n  ws['!cols'] = [200, 130, 110, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n\n  const refs: DataSheetRefs = {\n    totalCAExcelRow:      totalCARow + 1,\n    totalMatExcelRow:     totalMatRow + 1,\n    totalStaffExcelRow:   totalStaffRow + 1,\n    totalChargesExcelRow: totalChargesRow + 1,\n    caAnCol,\n    staffAnCol,\n  }\n  return { ws, refs }\n}\n\n// ─── Feuille 3 : Compte de résultat ──────────────────────────────────────────\nfunction buildIncomeSheet(\n  result: ReturnType<typeof computeAll>,\n  companyName: string,\n  refs: DataSheetRefs,\n): Record<string,unknown> {\n  const IS = result.incomeStatement\n  const R  = result.profitabilityRatios\n  const ws: Record<string,unknown> = {}\n  const COLS = 6\n  let r = 0\n  r = titleBlock(ws, companyName, 'COMPTE DE RÉSULTAT PRÉVISIONNEL (en Ar)', COLS, r)\n  // r = 2\n\n  setRow(ws, [hdr('Libellé'), ...YEARS.map(y => hdr(y))], r++)\n  // r = 3 → headers on Excel row 3, data starts at Excel row 4 (r=3 0-indexed)\n\n  // On définit les indices de ligne (0-indexés) pour chaque poste afin de pouvoir\n  // écrire des formules qui se référencent entre elles.\n  const rCA   = r;   r++ // Excel row rCA+1\n  const rMat  = r;   r++ // Excel row rMat+1\n  const rMB   = r;   r++ // Marge brute = CA − Mat\n  const rMBpct= r;   r++ // Marge brute %\n  const rSta  = r;   r++ // Personnel\n  const rExp  = r;   r++ // Charges d'exploitation\n  const rEBIT = r;   r++ // EBITDA (libellé = EBITDA)\n  const rEBITpct=r;  r++ // EBITDA margin %\n  const rDep  = r;   r++ // Amortissements\n  const rEBIT2= r;   r++ // EBIT\n  const rInt  = r;   r++ // Intérêts\n  const rEBT  = r;   r++ // Résultat avant impôt\n  const rTax  = r;   r++ // Impôts\n  const rNI   = r;   r++ // Résultat net\n  const rNIpct= r;   r++ // Marge nette %\n\n  // Colonnes données : B (An1) = index 1, C=2, D=3, E=4, F=5\n  // Pour l'année i (0-basé), col Excel = colLetter(1+i), Excel row = rXxx+1\n\n  // Helper : formule de référence croisée vers 'Données de base' pour l'année yi\n  const dbRef = (totalExcelRow: number, anColBase: number, yi: number) =>\n    `'Données de base'!${colLetter(anColBase + yi)}${totalExcelRow}`\n\n  // Helper : adresse locale dans cette feuille\n  function local(rowIdx: number, yi: number) { return cellAddr(rowIdx, 1 + yi) }\n\n  // ── Chiffre d'affaires ────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl(\"Chiffre d'affaires\", true, false, C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(dbRef(refs.totalCAExcelRow, refs.caAnCol, yi), IS.revenueByYear[yi], true, false, C.lightGreen),\n    ),\n  ], rCA)\n\n  // ── Coût des matières ─────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('− Coût des matières', false, false),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(dbRef(refs.totalMatExcelRow, refs.caAnCol, yi), IS.materialCostByYear[yi]),\n    ),\n  ], rMat)\n\n  // ── Marge brute = CA − Matières ───────────────────────────────────────────\n  setRow(ws, [\n    lbl('= Marge brute', true, false, C.lightGray),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${local(rCA,yi)}-${local(rMat,yi)}`, IS.grossMarginByYear[yi], true, false, C.lightGray),\n    ),\n  ], rMB)\n\n  // ── Marge brute % ─────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('Marge brute %', false, true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numPctF(`IF(${local(rCA,yi)}<>0,${local(rMB,yi)}/${local(rCA,yi)},0)`, R.grossMarginPctByYear[yi]),\n    ),\n  ], rMBpct)\n\n  // ── Personnel ─────────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('− Charges de personnel', false, false),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(dbRef(refs.totalStaffExcelRow, refs.staffAnCol, yi), IS.staffCostByYear[yi]),\n    ),\n  ], rSta)\n\n  // ── Charges d'exploitation ────────────────────────────────────────────────\n  setRow(ws, [\n    lbl(\"− Charges d'exploitation\", false, false),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(dbRef(refs.totalChargesExcelRow, refs.caAnCol, yi), IS.expenseCostByYear[yi]),\n    ),\n  ], rExp)\n\n  // ── EBITDA = Marge brute − Personnel − Charges ───────────────────────────\n  setRow(ws, [\n    lbl('= EBITDA', true, false, C.lightGray),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${local(rMB,yi)}-${local(rSta,yi)}-${local(rExp,yi)}`, IS.ebitdaByYear[yi], true, false, C.lightGray),\n    ),\n  ], rEBIT)\n\n  // ── EBITDA margin % ───────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('EBITDA margin %', false, true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numPctF(`IF(${local(rCA,yi)}<>0,${local(rEBIT,yi)}/${local(rCA,yi)},0)`, R.ebitdaMarginPctByYear[yi]),\n    ),\n  ], rEBITpct)\n\n  // ── Amortissements ────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('− Amortissements', false, false),\n    ...IS.depreciationByYear.map(v => num(v)),\n  ], rDep)\n\n  // ── EBIT = EBITDA − Amortissements ───────────────────────────────────────\n  setRow(ws, [\n    lbl('= EBIT', true, false, C.lightGray),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${local(rEBIT,yi)}-${local(rDep,yi)}`, IS.ebitByYear[yi], true, false, C.lightGray),\n    ),\n  ], rEBIT2)\n\n  // ── Intérêts ──────────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl(\"− Intérêts d'emprunt\", false, false),\n    ...IS.interestByYear.map(v => num(v)),\n  ], rInt)\n\n  // ── Résultat avant impôt = EBIT − Intérêts ───────────────────────────────\n  setRow(ws, [\n    lbl('= Résultat avant impôt', true, false, C.lightGray),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${local(rEBIT2,yi)}-${local(rInt,yi)}`, IS.ebtByYear[yi], true, false, C.lightGray),\n    ),\n  ], rEBT)\n\n  // ── Impôts ────────────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('− Impôts', false, false),\n    ...IS.taxByYear.map(v => num(v)),\n  ], rTax)\n\n  // ── Résultat net = Résultat avant impôt − Impôts ─────────────────────────\n  setRow(ws, [\n    lbl('= Résultat net', true, false, C.lightGreen),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${local(rEBT,yi)}-${local(rTax,yi)}`, IS.netIncomeByYear[yi], true, true, C.lightGreen),\n    ),\n  ], rNI)\n\n  // ── Marge nette % ─────────────────────────────────────────────────────────\n  setRow(ws, [\n    lbl('Marge nette %', false, true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numPctF(`IF(${local(rCA,yi)}<>0,${local(rNI,yi)}/${local(rCA,yi)},0)`, R.netMarginPctByYear[yi], false, true),\n    ),\n  ], rNIpct)\n\n  ws['!cols'] = [230, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n  ws['!rows'] = [{ hpx: 28 }, { hpx: 22 }, { hpx: 20 }]\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 4 : Trésorerie 5 ans ────────────────────────────────────────────\nfunction buildCashFlowSheet(result: ReturnType<typeof computeAll>, companyName: string): Record<string,unknown> {\n  const CF = result.cashFlowStatement\n  const ws: Record<string,unknown> = {}\n  const COLS = 6\n  let r = 0\n  r = titleBlock(ws, companyName, 'TABLEAU DE FLUX DE TRÉSORERIE (en Ar)', COLS, r)\n  // r=2\n\n  setRow(ws, [hdr('Libellé'), ...YEARS.map(y => hdr(y))], r++)\n  // r=3\n\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = subHdr('📊 FLUX OPÉRATIONNEL')\n  merge(ws, r, 0, r, COLS-1); r++\n  // r=4\n\n  const rNI  = r; r++ // Résultat net\n  const rDep = r; r++ // Amortissements\n  const rCAF = r; r++ // CAF = NI + Dep\n\n  setRow(ws, [lbl('Résultat net', false, true), ...CF.netIncomeByYear.map(v => num(v))], rNI)\n  setRow(ws, [lbl('+ Amortissements', false, true), ...CF.depreciationByYear.map(v => num(v))], rDep)\n  setRow(ws, [\n    lbl('= CAF (flux opérationnel)', true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(`${cellAddr(rNI,1+yi)}+${cellAddr(rDep,1+yi)}`, CF.operatingCashFlowByYear[yi], true, false, C.lightGreen),\n    ),\n  ], rCAF)\n  r++ // blank\n\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = subHdr('🏗️  FLUX D\\'INVESTISSEMENT & FINANCEMENT')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  ;[\n    ['− Investissements',         CF.investmentByYear],\n    ['+ Fonds propres apportés',  CF.equityByYear],\n    ['+ Emprunts mobilisés',      CF.loanByYear],\n    ['+ Subventions / Apports',   CF.grantByYear],\n    ['− Remboursements capital',  CF.loanRepaymentByYear],\n  ].forEach(([l, d]) => setRow(ws, [lbl(l as string, false, true), ...(d as number[]).map(v => num(v))], r++))\n  r++\n\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = subHdr('💧 SOLDE DE TRÉSORERIE')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  // Trésorerie nette annuelle (valeur hardcodée — dépend de tous les flux)\n  const rNet = r\n  setRow(ws, [\n    lbl('= Trésorerie nette annuelle', true),\n    ...CF.netCashByYear.map(v => num(v, true, true, C.lightGreen)),\n  ], r++)\n\n  // Trésorerie cumulée = SUM des soldes nets jusqu'à l'année courante\n  setRow(ws, [\n    lbl(\"Trésorerie cumulée fin d'an\", true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(\n        `SUM(${cellAddr(rNet,1)}:${cellAddr(rNet,1+yi)})`,\n        CF.cumulativeCashByYear[yi],\n        true, true, C.lightGreen,\n      ),\n    ),\n  ], r++)\n\n  ws['!cols'] = [230, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 5 : Trésorerie mensuelle An 1 ───────────────────────────────────\nfunction buildMonthlySheet(\n  result: ReturnType<typeof computeAll>,\n  products: Product[],\n  materials: Material[],\n  staffMembers: StaffMember[],\n  expenses: Expense[],\n  additionalFundings: AdditionalFunding[],\n  settings: CompanySettings,\n  investments: Investment[],\n  companyName: string,\n): Record<string,unknown> {\n  const ws: Record<string,unknown> = {}\n  const COLS = 14\n  let r = 0\n  r = titleBlock(ws, companyName, 'TRÉSORERIE MENSUELLE — ANNÉE 1 (en Ar)', COLS, r)\n\n  const invEquity = investments.reduce((s,i) => s + i.financedEquity, 0)\n  const invLoan   = investments.reduce((s,i) => s + i.financedLoan, 0)\n  const invGrant  = investments.reduce((s,i) => s + i.financedGrant, 0)\n  const invTotal  = investments.reduce((s,i) => s + i.amount, 0)\n  const fdr       = settings.fondsRoulement ?? 0\n  const tresoInitiale = invEquity + invLoan + invGrant - invTotal + fdr\n\n  const monthly = buildMonthlyCashFlow(\n    products, materials, staffMembers, expenses,\n    result.incomeStatement, result.loanRepaymentTable,\n    additionalFundings, tresoInitiale,\n  )\n\n  // Info trésorerie initiale\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = lbl(`Trésorerie initiale (An 0) : ${formatAriary(tresoInitiale)}`, true, false, C.lightBlue)\n  merge(ws, r, 0, r, COLS-1); r++\n  r++\n\n  setRow(ws, [hdr('Poste'), ...MONTHS.map(m => hdr(m)), hdr('TOTAL An 1')], r++)\n\n  type MonthlyRow = { l: string; d: number[]; bold: boolean; colored: boolean; bg?: string }\n  const totalAn1 = (arr: number[]) => arr.reduce((a,b) => a+b, 0)\n\n  const rows: MonthlyRow[] = [\n    { l: 'Encaissements (CA)',              d: monthly.encaissements,                                                          bold: true,  colored: false, bg: C.lightGreen },\n    { l: '− Coûts variables (matières)',    d: monthly.coutsVariables,                                                         bold: false, colored: false },\n    { l: '− Charges de personnel',         d: Array(12).fill(monthly.personnelMensuel),                                        bold: false, colored: false },\n    { l: \"− Charges d'exploitation\",       d: monthly.autresCharges,                                                           bold: false, colored: false },\n    { l: '− Impôts & taxes',               d: Array(12).fill(monthly.impotMensuel),                                            bold: false, colored: false },\n    { l: '− Frais financiers',             d: Array(12).fill(monthly.fraisFinanciersMensuel),                                  bold: false, colored: false },\n    { l: '− Remboursement capital',        d: Array(12).fill(monthly.rembCapitalMensuel),                                      bold: false, colored: false },\n    { l: '+ Apports complémentaires',      d: monthly.apportMois,                                                              bold: false, colored: false },\n    { l: '= Solde mensuel net',            d: monthly.soldeMensuel,                                                            bold: true,  colored: true,  bg: C.lightGray },\n    { l: 'Trésorerie cumulée',             d: monthly.soldeCumule,                                                             bold: true,  colored: true,  bg: C.lightGreen },\n  ]\n\n  rows.forEach(({ l: label_, d, bold, colored, bg }) => {\n    setRow(ws, [\n      lbl(label_, bold, !bold, bg),\n      ...d.map(v => num(v, bold, colored, bg)),\n      num(totalAn1(d), bold, colored, bg),\n    ], r++)\n  })\n\n  ws['!cols'] = [200, ...Array(12).fill(80), 100].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 6 : Bilan ───────────────────────────────────────────────────────\nfunction buildBalanceSheet(\n  result: ReturnType<typeof computeAll>,\n  companyName: string,\n  investments: Investment[],\n): Record<string,unknown> {\n  const BS  = result.balanceSheet\n  const IS  = result.incomeStatement\n  const ws: Record<string,unknown> = {}\n  const COLS = 6\n  let r = 0\n  r = titleBlock(ws, companyName, 'BILAN PRÉVISIONNEL (en Ar)', COLS, r)\n\n  setRow(ws, [hdr('Rubrique'), ...YEARS.map(y => hdr(y))], r++)\n\n  // ── ACTIF — même calcul que l'appli (sans BFR) ───────────────────────────\n  const invTotal  = investments.reduce((s, i) => s + i.amount, 0)\n  const annualDep = result.depreciationTable.totalAnnualDepreciation\n  const netFixed  = Array.from({ length: 5 }, (_, y) => Math.max(0, invTotal - annualDep * (y + 1)))\n  const cashByYear = BS.cashByYear\n  const totalActif = Array.from({ length: 5 }, (_, y) => netFixed[y] + Math.max(0, cashByYear[y]))\n\n  setRow(ws, [sectionRow('ACTIF'), ...YEARS.map(() => empty(C.primary))], r++)\n  setRow(ws, [lbl('Immobilisations nettes (VNC)', false, true), ...netFixed.map(v => num(v))], r++)\n  setRow(ws, [lbl('Trésorerie', false, true), ...cashByYear.map(v => num(v, false, v < 0))], r++)\n  setRow(ws, [lbl('= TOTAL ACTIF', true), ...totalActif.map(v => num(v, true, false, C.lightGreen))], r++)\n  r++\n\n  // ── PASSIF — même calcul que l'appli ─────────────────────────────────────\n  const invEquity = investments.reduce((s, i) => s + i.financedEquity, 0)\n  const invGrant  = investments.reduce((s, i) => s + i.financedGrant, 0)\n  // Résultats antérieurs cumulés (= résultats des années précédentes)\n  const cumResult: number[] = IS.netIncomeByYear.reduce<number[]>((acc, _, y) => {\n    acc.push((acc[y - 1] ?? 0) + (y > 0 ? IS.netIncomeByYear[y - 1] : 0))\n    return acc\n  }, [])\n  const capitalPropres = Array.from({ length: 5 }, (_, y) =>\n    invEquity + invGrant + cumResult[y] + IS.netIncomeByYear[y],\n  )\n  const dettes     = BS.loanBalanceByYear\n  const totalPassif = Array.from({ length: 5 }, (_, y) => capitalPropres[y] + Math.max(0, dettes[y]))\n\n  setRow(ws, [sectionRow('PASSIF'), ...YEARS.map(() => empty(C.primary))], r++)\n  setRow(ws, [lbl('Capitaux propres', false, true), ...capitalPropres.map(v => num(v, false, v < 0))], r++)\n  setRow(ws, [lbl('Dettes financières', false, true), ...dettes.map(v => num(v))], r++)\n  setRow(ws, [lbl('= TOTAL PASSIF', true), ...totalPassif.map(v => num(v, true, false, C.lightGreen))], r++)\n  r++\n\n  // ── Écart de contrôle ─────────────────────────────────────────────────────\n  const ecarts = totalActif.map((a, i) => a - totalPassif[i])\n  setRow(ws, [\n    lbl('Écart Actif − Passif', false, true, C.lightGray),\n    ...ecarts.map(v => ({\n      v: Math.abs(v) < 100 ? '✓ Équilibré' : String(v),\n      t: 's',\n      s: {\n        font: { sz: 10, bold: false, color: { rgb: Math.abs(v) < 100 ? C.success : C.danger } },\n        fill: { fgColor: { rgb: C.lightGray } },\n        alignment: { horizontal: 'center' },\n        border: allBorder(),\n      },\n    })),\n  ], r++)\n  r++\n\n  // ── Détail capitaux propres ───────────────────────────────────────────────\n  setRow(ws, [sectionRow('DÉTAIL DES CAPITAUX PROPRES'), ...YEARS.map(() => empty(C.primary))], r++)\n  setRow(ws, [hdr('Rubrique'), ...YEARS.map(y => hdr(y))], r++)\n  ;[\n    ['Capital initial + subventions', Array(5).fill(invEquity + invGrant)],\n    ['Résultats antérieurs cumulés',  cumResult],\n    [\"Résultat de l\\'exercice\",      IS.netIncomeByYear],\n  ].forEach(([l, d]) =>\n    setRow(ws, [lbl(l as string, false, true), ...(d as number[]).map(v => num(v, false, (v as number) < 0))], r++),\n  )\n  setRow(ws, [lbl('= Total capitaux propres', true), ...capitalPropres.map(v => num(v, true, v < 0, C.lightGreen))], r++)\n  r++\n\n  // ── Détail dettes financières ─────────────────────────────────────────────\n  const LOAN = result.loanRepaymentTable\n  if (LOAN.byLoan.length > 0) {\n    const DCOLS = 10 // Emprunt | Principal | Taux | Durée | An1..An5\n    setRow(ws, [sectionRow('DÉTAIL DES DETTES FINANCIÈRES'), ...Array(DCOLS - 1).fill(empty(C.primary))], r++)\n    setRow(ws, [\n      hdr('Emprunt'), hdr('Principal (Ar)'), hdr('Taux %'), hdr('Durée'),\n      ...YEARS.map(y => hdr(`Solde ${y}`)),\n    ], r++)\n\n    LOAN.byLoan.forEach(loan => {\n      setRow(ws, [\n        lbl(loan.label, true),\n        num(loan.principal),\n        { v: loan.rate / 100, t: 'n', z: '0.0%', s: { font: { sz: 10 }, fill: { fgColor: { rgb: C.white } }, alignment: { horizontal: 'right' }, border: allBorder() } },\n        txt(`${loan.years} ans`, false, C.textDark, C.white, 'center'),\n        ...YEARS.map((_, yi) => num(loan.annualPayments[yi]?.balance ?? 0)),\n      ], r++)\n    })\n\n    // Total dettes\n    setRow(ws, [\n      lbl('= Total dettes financières', true), empty(C.lightGreen), empty(C.lightGreen), empty(C.lightGreen),\n      ...dettes.map(v => num(v, true, false, C.lightGreen)),\n    ], r++)\n\n    // Remboursements capital cumulés\n    const rembCumul = YEARS.map((_, yi) =>\n      LOAN.totalCapitalByYear.slice(0, yi + 1).reduce((a, b) => a + b, 0),\n    )\n    setRow(ws, [\n      lbl('Remboursements capital cumulés', false, true, C.lightGray),\n      empty(C.lightGray), empty(C.lightGray), empty(C.lightGray),\n      ...rembCumul.map(v => num(v, false, false, C.lightGray)),\n    ], r++)\n\n    // Intérêts payés cumulés\n    const intCumul = YEARS.map((_, yi) =>\n      LOAN.totalInterestByYear.slice(0, yi + 1).reduce((a, b) => a + b, 0),\n    )\n    setRow(ws, [\n      lbl('Intérêts payés cumulés', false, true, C.lightGray),\n      empty(C.lightGray), empty(C.lightGray), empty(C.lightGray),\n      ...intCumul.map(v => num(v, false, false, C.lightGray)),\n    ], r++)\n\n    // Update range for wider sheet\n    ws['!cols'] = [220, 120, 70, 65, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n    setRange(ws, r, DCOLS)\n  } else {\n    ws['!cols'] = [250, 120, 120, 120, 120, 120].map(w => ({ wpx: w }))\n    setRange(ws, r, COLS)\n  }\n  return ws\n}\n\n// ─── Feuille 7 : Plan de financement ─────────────────────────────────────────\nfunction buildFinancingSheet(result: ReturnType<typeof computeAll>, companyName: string): Record<string,unknown> {\n  const FP = result.financingPlan\n  const ws: Record<string,unknown> = {}\n  const COLS = 6\n  let r = 0\n  r = titleBlock(ws, companyName, 'PLAN DE FINANCEMENT (en Ar)', COLS, r)\n  // r=2\n\n  setRow(ws, [hdr('Libellé'), ...YEARS.map(y => hdr(y))], r++)\n  // r=3\n\n  // ── RESSOURCES ───────────────────────────────────────────────────────────\n  setRow(ws, [sectionRow('RESSOURCES'), ...YEARS.map(() => empty(C.primary))], r++)\n  // r=4\n\n  const resLabels: [string, number[]][] = [\n    [\"Capacité d'autofinancement (CAF)\", FP.cafByYear],\n    ['Fonds propres apportés', FP.equityByYear],\n    ['Emprunts mobilisés', FP.loanByYear],\n    ['Subventions & apports', FP.grantByYear],\n  ]\n  const rResStart = r\n  resLabels.forEach(([l, d]) => setRow(ws, [lbl(l, false, true), ...d.map(v => num(v))], r++))\n  const rResTot = r\n  setRow(ws, [\n    lbl('= Total Ressources', true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(\n        `SUM(${cellAddr(rResStart,1+yi)}:${cellAddr(rResTot-1,1+yi)})`,\n        FP.totalResourcesByYear[yi],\n        true, false, C.lightGreen,\n      ),\n    ),\n  ], r++)\n  r++ // blank\n\n  // ── EMPLOIS ──────────────────────────────────────────────────────────────\n  setRow(ws, [sectionRow('EMPLOIS'), ...YEARS.map(() => empty(C.primary))], r++)\n\n  const empLabels: [string, number[]][] = [\n    ['Investissements', FP.investmentByYear],\n    ['Remboursements capital', FP.loanRepaymentByYear],\n    ['Variation BFR', FP.bfrByYear],\n  ]\n  const rEmpStart = r\n  empLabels.forEach(([l, d]) => setRow(ws, [lbl(l, false, true), ...d.map(v => num(v))], r++))\n  const rEmpTot = r\n  setRow(ws, [\n    lbl('= Total Emplois', true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(\n        `SUM(${cellAddr(rEmpStart,1+yi)}:${cellAddr(rEmpTot-1,1+yi)})`,\n        FP.totalUsesByYear[yi],\n        true, false, C.lightGreen,\n      ),\n    ),\n  ], r++)\n  r++ // blank\n\n  // ── SOLDES ───────────────────────────────────────────────────────────────\n  const rSoldeAn = r\n  setRow(ws, [\n    lbl('Solde annuel', true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(\n        `${cellAddr(rResTot,1+yi)}-${cellAddr(rEmpTot,1+yi)}`,\n        FP.balanceByYear[yi],\n        true, true,\n      ),\n    ),\n  ], r++)\n\n  setRow(ws, [\n    lbl('Solde cumulé', true),\n    ...Array.from({ length: 5 }, (_, yi) =>\n      numF(\n        `SUM(${cellAddr(rSoldeAn,1)}:${cellAddr(rSoldeAn,1+yi)})`,\n        FP.cumulativeBalanceByYear[yi],\n        true, true, C.lightGreen,\n      ),\n    ),\n  ], r++)\n\n  ws['!cols'] = [250, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 8 : Rentabilité ──────────────────────────────────────────────────\nfunction buildProfitabilitySheet(\n  result: ReturnType<typeof computeAll>,\n  companyName: string,\n  discountRate: number,\n): Record<string,unknown> {\n  const KPI = result.profitability\n  const IS  = result.incomeStatement\n  const R   = result.profitabilityRatios\n  const ws: Record<string,unknown> = {}\n  const COLS = 6\n  let r = 0\n  r = titleBlock(ws, companyName, 'INDICATEURS DE RENTABILITÉ', COLS, r)\n\n  // ── KPIs globaux ──────────────────────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('🎯  INDICATEURS GLOBAUX')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Indicateur'), hdr('Valeur'), hdr('Commentaire'), empty(C.darkBg), empty(C.darkBg), empty(C.darkBg)], r++)\n\n  ;[\n    ['VAN (Valeur Actuelle Nette)', formatAriary(KPI.npv), KPI.npv >= 0 ? '✅ Projet rentable' : '❌ Projet non rentable', KPI.npv >= 0],\n    ['TRI (Taux de Rentabilité Interne)', KPI.irr !== null ? `${KPI.irr.toFixed(1)} %` : 'N/A', KPI.irr !== null && KPI.irr > discountRate ? `✅ TRI > taux actualisation (${discountRate} %)` : `⚠️  TRI ≤ taux actualisation`, KPI.irr !== null && KPI.irr > discountRate],\n    ['Indice de profitabilité (IP)', KPI.profitabilityIndex.toFixed(2), KPI.profitabilityIndex >= 1 ? '✅ IP ≥ 1 : Acceptable' : '❌ IP < 1', KPI.profitabilityIndex >= 1],\n    ['Délai de récupération', KPI.paybackYear !== null ? `An ${KPI.paybackYear}` : '> 5 ans', KPI.paybackYear !== null ? (KPI.paybackYear <= 3 ? '✅ Récupération rapide' : '⚠️  Récupération lente') : '❌ Non récupéré', KPI.paybackYear !== null && KPI.paybackYear <= 3],\n    ['1ère année profitable', KPI.breakEvenYear !== null ? `An ${KPI.breakEvenYear}` : '> 5 ans', KPI.breakEvenYear !== null ? '✅ Bénéfice atteint' : '❌ Pas de bénéfice sur 5 ans', KPI.breakEvenYear !== null],\n  ].forEach(([ind, val, com, ok]) => {\n    const color = ok ? C.success : C.danger\n    const bg    = ok ? C.lightGreen : C.dangerLt\n    setRow(ws, [\n      lbl(ind as string, true),\n      { v: val as string, t: 's', s: { font: { bold: true, sz: 11, color: { rgb: color } }, fill: { fgColor: { rgb: bg } }, alignment: { horizontal: 'center' }, border: allBorder() } },\n      txt(com as string, false, C.textMuted),\n      empty(), empty(), empty(),\n    ], r++)\n  })\n  r++\n\n  // ── Tableau de résultats sur 5 ans ────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('📊  RÉSULTATS ANNUELS (en Ar)')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Indicateur'), ...YEARS.map(y => hdr(y))], r++)\n\n  const resRows: Array<{ l: string; d: number[]; bold: boolean; colored: boolean; isPct?: boolean }> = [\n    { l: \"Chiffre d'affaires\",     d: IS.revenueByYear,              bold: true,  colored: false },\n    { l: 'EBITDA',                 d: IS.ebitdaByYear,               bold: true,  colored: false },\n    { l: '  EBITDA margin %',      d: R.ebitdaMarginPctByYear,       bold: false, colored: false, isPct: true },\n    { l: '  (−) Frais financiers', d: IS.interestByYear,             bold: false, colored: false },\n    { l: 'Résultat net',           d: IS.netIncomeByYear,            bold: true,  colored: true  },\n    { l: '  Marge nette %',        d: R.netMarginPctByYear,          bold: false, colored: true,  isPct: true },\n    { l: '  Marge brute %',        d: R.grossMarginPctByYear,        bold: false, colored: false, isPct: true },\n    { l: 'Trésorerie cumulée',     d: result.cashFlowStatement.cumulativeCashByYear, bold: true, colored: true },\n  ]\n  resRows.forEach(({ l: label_, d, bold, colored, isPct }) => {\n    const indent = label_.startsWith('  ')\n    const bg = bold ? C.lightGreen : undefined\n    setRow(ws, [\n      lbl(label_.trim(), bold, indent, bg),\n      ...d.map(v => isPct ? numPct(v, bold, colored) : num(v, bold, colored, bg)),\n    ], r++)\n  })\n  r++\n\n  // ── Seuil de rentabilité par année ────────────────────────────────────────\n  ws[XLSXStyle.utils.encode_cell({ r, c: 0 })] = sectionRow('📉  SEUIL DE RENTABILITÉ ANNUEL (en Ar)')\n  merge(ws, r, 0, r, COLS-1); r++\n\n  setRow(ws, [hdr('Indicateur'), ...YEARS.map(y => hdr(y))], r++)\n  ;[\n    ['Seuil de rentabilité (Ar)',   R.breakEvenValueByYear],\n    ['Point mort (mois)',           R.breakEvenMonthByYear],\n  ].forEach(([l, d]) => setRow(ws, [lbl(l as string, true), ...(d as number[]).map(v => num(v, false, false))], r++))\n\n  ws['!cols'] = [250, 130, 130, 130, 130, 130].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 9 : Amortissements ───────────────────────────────────────────────\nfunction buildDepreciationSheet(\n  result: ReturnType<typeof computeAll>,\n  companyName: string,\n  investments: Array<{ id: number; name: string }>,\n): Record<string,unknown> {\n  const DEP = result.depreciationTable\n  const ws: Record<string,unknown> = {}\n  const COLS = 8\n  let r = 0\n  r = titleBlock(ws, companyName, \"TABLEAU D'AMORTISSEMENT LINÉAIRE (en Ar)\", COLS, r)\n\n  setRow(ws, [hdr('Immobilisation'), hdr('Amort. annuel'), ...YEARS.map(y => hdr(`VNC ${y}`)), hdr('Total amorti')], r++)\n\n  DEP.byInvestment.forEach((row) => {\n    const inv = investments.find(i => i.id === row.investmentId)\n    setRow(ws, [\n      lbl(inv?.name ?? `#${row.investmentId}`, true),\n      num(row.annualDepreciation),\n      ...row.yearlyBook.map(v => num(v)),\n      num(row.annualDepreciation * 5, false, false, C.lightGray),\n    ], r++)\n  })\n  setRow(ws, [\n    lbl('TOTAL', true),\n    num(DEP.totalAnnualDepreciation, true, false, C.lightGreen),\n    ...YEARS.map(() => empty(C.lightGray)),\n    empty(C.lightGray),\n  ], r++)\n\n  ws['!cols'] = [220, 110, 110, 110, 110, 110, 110, 110].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Feuille 10 : Emprunts ────────────────────────────────────────────────────\nfunction buildLoanSheet(result: ReturnType<typeof computeAll>, companyName: string): Record<string,unknown> {\n  const LOAN = result.loanRepaymentTable\n  const ws: Record<string,unknown> = {}\n  const COLS = 11\n  let r = 0\n  r = titleBlock(ws, companyName, 'TABLEAU DE REMBOURSEMENT DES EMPRUNTS (en Ar)', COLS, r)\n\n  setRow(ws, [hdr('Emprunt'), ...YEARS.flatMap(y => [hdr(y), empty(C.darkBg)])], r++)\n  setRow(ws, [empty(C.darkBg), ...YEARS.flatMap(() => [subHdr('Capital'), subHdr('Intérêts')])], r++)\n\n  LOAN.byLoan.forEach(loan => {\n    setRow(ws, [\n      lbl(loan.label, true),\n      ...YEARS.flatMap((_, yi) => [\n        num(loan.annualPayments[yi]?.capital ?? 0),\n        num(loan.annualPayments[yi]?.interest ?? 0, false, false, C.lightGray),\n      ]),\n    ], r++)\n  })\n  setRow(ws, [\n    lbl('TOTAL', true),\n    ...YEARS.flatMap((_, yi) => [\n      num(LOAN.totalCapitalByYear[yi], true, false, C.lightGreen),\n      num(LOAN.totalInterestByYear[yi], false, false, C.lightGray),\n    ]),\n  ], r++)\n\n  ws['!cols'] = [200, ...Array(10).fill(100)].map(w => ({ wpx: w }))\n  setRange(ws, r, COLS)\n  return ws\n}\n\n// ─── Composant principal ──────────────────────────────────────────────────────\nexport default function ExportSection() {\n  const company  = useCompanyStore((s) => s.company)!\n  const settings = company.settings\n  const [isExporting, setIsExporting] = useState(false)\n\n  const result = useMemo(() => {\n    if (!settings) return null\n    return computeAll(settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings)\n  }, [settings, company.products, company.materials, company.staffMembers,\n      company.expenses, company.investments, company.additionalFundings])\n\n  async function exportXLSX() {\n    if (!result || !settings) return\n    setIsExporting(true)\n    try {\n      const wb = XLSXStyle.utils.book_new()\n      const cn = company.name\n\n      XLSXStyle.utils.book_append_sheet(wb, buildSyntheseSheet(result, company as never, settings, company.products, company.staffMembers, company.investments), 'Synthèse')\n      const { ws: dataWs, refs: dataRefs } = buildDataSheet(result, company.products, company.materials, company.staffMembers, company.expenses, cn)\n      XLSXStyle.utils.book_append_sheet(wb, dataWs, 'Données de base')\n      XLSXStyle.utils.book_append_sheet(wb, buildIncomeSheet(result, cn, dataRefs), 'Compte de résultat')\n      XLSXStyle.utils.book_append_sheet(wb, buildCashFlowSheet(result, cn), 'Trésorerie 5 ans')\n      XLSXStyle.utils.book_append_sheet(wb, buildMonthlySheet(result, company.products, company.materials, company.staffMembers, company.expenses, company.additionalFundings, settings, company.investments, cn), 'Trésorerie mensuelle')\n      XLSXStyle.utils.book_append_sheet(wb, buildBalanceSheet(result, cn, company.investments), 'Bilan')\n      XLSXStyle.utils.book_append_sheet(wb, buildFinancingSheet(result, cn), 'Plan de financement')\n      XLSXStyle.utils.book_append_sheet(wb, buildProfitabilitySheet(result, cn, settings.discountRate), 'Rentabilité')\n      XLSXStyle.utils.book_append_sheet(wb, buildDepreciationSheet(result, cn, company.investments), 'Amortissements')\n      if (result.loanRepaymentTable.byLoan.length > 0) {\n        XLSXStyle.utils.book_append_sheet(wb, buildLoanSheet(result, cn), 'Emprunts')\n      }\n\n      const date = new Date().toISOString().slice(0, 10)\n      const filename = `BusinessPlan_${cn.replace(/\\s+/g,'_')}_${date}.xlsx`\n\n      // Étape 1 : générer le xlsx via xlsx-js-style\n      const xlsxBuffer: ArrayBuffer = XLSXStyle.write(wb, { type: 'array', bookType: 'xlsx' })\n\n      // Étape 2 : injecter le logo via JSZip (sans passer par ExcelJS qui corrompt le XML)\n      let finalBuffer: ArrayBuffer = xlsxBuffer\n      try {\n        const JSZip = (await import('jszip')).default\n        const zip = await JSZip.loadAsync(xlsxBuffer)\n\n        // 2. Lister les feuilles pour savoir combien en injecter\n        const sheetFiles = Object.keys(zip.files).filter(f => f.match(/^xl\\/worksheets\\/sheet\\d+\\.xml$/))\n\n        // Charger le logo depuis /public/logo-aides.jpg\n        const logoRes = await fetch('/logo-aides.jpg')\n        if (logoRes.ok) {\n          const logoBytes = await logoRes.arrayBuffer()\n\n          // 1. Ajouter l'image dans xl/media/\n          zip.file('xl/media/logo.jpg', logoBytes)\n\n          for (const sheetPath of sheetFiles) {\n            const sheetNum = sheetPath.match(/sheet(\\d+)\\.xml$/)?.[1] ?? '1'\n\n            // 3. Drawing XML — image flottante en haut à droite (col J=9, row 0)\n            const drawingXml = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<xdr:wsDr xmlns:xdr=\"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">\n  <xdr:oneCellAnchor>\n    <xdr:from><xdr:col>7</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>\n    <xdr:ext cx=\"1714500\" cy=\"685800\"/>\n    <xdr:pic>\n      <xdr:nvPicPr>\n        <xdr:cNvPr id=\"2\" name=\"Logo AIDES\"/>\n        <xdr:cNvPicPr><a:picLocks noChangeAspect=\"1\"/></xdr:cNvPicPr>\n      </xdr:nvPicPr>\n      <xdr:blipFill>\n        <a:blip r:embed=\"rId1\"/>\n        <a:stretch><a:fillRect/></a:stretch>\n      </xdr:blipFill>\n      <xdr:spPr>\n        <a:xfrm><a:off x=\"0\" y=\"0\"/><a:ext cx=\"1714500\" cy=\"685800\"/></a:xfrm>\n        <a:prstGeom prst=\"rect\"><a:avLst/></a:prstGeom>\n      </xdr:spPr>\n    </xdr:pic>\n    <xdr:clientData/>\n  </xdr:oneCellAnchor>\n</xdr:wsDr>`\n\n            // 4. Relationship du drawing → image\n            const drawingRelsXml = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">\n  <Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"../media/logo.jpg\"/>\n</Relationships>`\n\n            const drawingFile = `xl/drawings/drawing${sheetNum}.xml`\n            const drawingRelsFile = `xl/drawings/_rels/drawing${sheetNum}.xml.rels`\n            zip.file(drawingFile, drawingXml)\n            zip.file(drawingRelsFile, drawingRelsXml)\n\n            // 5. Relationship du sheet → drawing\n            const sheetRelsPath = `xl/worksheets/_rels/sheet${sheetNum}.xml.rels`\n            const drawingRel = `<Relationship Id=\"rIdDrw\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing\" Target=\"../drawings/drawing${sheetNum}.xml\"/>`\n\n            let sheetRels = ''\n            if (zip.files[sheetRelsPath]) {\n              sheetRels = await zip.files[sheetRelsPath].async('string')\n              sheetRels = sheetRels.replace('</Relationships>', drawingRel + '</Relationships>')\n            } else {\n              sheetRels = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">\n  ${drawingRel}\n</Relationships>`\n            }\n            zip.file(sheetRelsPath, sheetRels)\n\n            // 6. Ajouter <drawing r:id=\"rIdDrw\"/> dans le sheet XML (avant </worksheet>)\n            let sheetXml = await zip.files[sheetPath].async('string')\n            if (!sheetXml.includes('<drawing ')) {\n              sheetXml = sheetXml.replace(\n                '</worksheet>',\n                '<drawing r:id=\"rIdDrw\"/></worksheet>'\n              )\n              // S'assurer que le namespace r est déclaré dans <worksheet>\n              if (!sheetXml.includes('xmlns:r=')) {\n                sheetXml = sheetXml.replace(\n                  '<worksheet ',\n                  '<worksheet xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" '\n                )\n              }\n            }\n            zip.file(sheetPath, sheetXml)\n          }\n        }\n\n        // Ajouter les overrides drawing dans [Content_Types].xml (obligatoire pour Excel)\n        let contentTypes = await zip.files['[Content_Types].xml'].async('string')\n        for (const sheetPath of sheetFiles) {\n          const sNum = sheetPath.match(/sheet(\\d+)\\.xml$/)?.[1] ?? '1'\n          const override = `<Override PartName=\"/xl/drawings/drawing${sNum}.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.drawing+xml\"/>`\n          if (!contentTypes.includes('drawing' + sNum + '.xml')) {\n            contentTypes = contentTypes.replace('</Types>', override + '</Types>')\n          }\n        }\n        zip.file('[Content_Types].xml', contentTypes)\n\n        // Recompresser le zip\n        const zipBuffer = await zip.generateAsync({ type: 'arraybuffer', compression: 'DEFLATE' })\n        finalBuffer = zipBuffer\n      } catch (err) {\n        console.warn('[Export] JSZip logo injection failed, using plain xlsx:', err)\n      }\n\n      const blob = new Blob([finalBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' })\n      const url = URL.createObjectURL(blob)\n      const a = document.createElement('a')\n      a.href = url\n      a.download = filename\n      a.click()\n      URL.revokeObjectURL(url)\n    } finally {\n      setIsExporting(false)\n    }\n  }\n\n  const hasData = !!(\n    company.products.length > 0 ||\n    company.materials.length > 0 ||\n    company.staffMembers.length > 0 ||\n    company.expenses.length > 0 ||\n    company.investments.length > 0\n  )\n\n  return (\n    <div>\n      {/* En-tête */}\n      <div style={{ marginBottom: 'var(--space-5)' }}>\n        <h3 className=\"section-title\" style={{ marginBottom: 4 }}>\n          <i className=\"fas fa-file-excel\" style={{ marginRight: 8, color: 'var(--color-primary)' }} />\n          Export Excel\n        </h3>\n        <p className=\"section-subtitle\">\n          Générez un classeur Excel complet avec toutes les projections financières sur 5 ans.\n          Le logo AIDES est ajouté automatiquement sur chaque feuille.\n        </p>\n      </div>\n\n      {/* Bouton export */}\n      <div className=\"card\" style={{ padding: 'var(--space-6)' }}>\n        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-5)', flexWrap: 'wrap' }}>\n          <button\n            className=\"btn btn-primary\"\n            onClick={exportXLSX}\n            disabled={isExporting || !hasData || !result}\n            style={{ fontSize: 15, padding: '10px 28px', display: 'flex', alignItems: 'center', gap: 8 }}\n          >\n            {isExporting\n              ? <><i className=\"fas fa-spinner fa-spin\" /> Génération…</>\n              : <><i className=\"fas fa-file-excel\" /> Exporter en Excel</>\n            }\n          </button>\n          <div style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>\n            {!hasData && <span style={{ color: 'var(--color-danger)' }}>⚠ Ajoutez des données avant d'exporter.</span>}\n            {hasData && !result && <span style={{ color: 'var(--color-warning)' }}>⚠ Paramètres manquants dans la section Entreprise.</span>}\n            {hasData && result && <span>✓ {company.products.length} produit(s) · {company.staffMembers.length} poste(s) · {company.investments.length} investissement(s)</span>}\n          </div>\n        </div>\n\n        {/* Contenu des feuilles */}\n        <div style={{ marginTop: 'var(--space-5)', borderTop: '1px solid var(--color-border)', paddingTop: 'var(--space-4)' }}>\n          <p style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: 'var(--color-text)', marginBottom: 'var(--space-3)' }}>\n            Feuilles générées :\n          </p>\n          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 'var(--space-2)' }}>\n            {[\n              { icon: 'fa-star', label: 'Synthèse' },\n              { icon: 'fa-database', label: 'Données de base' },\n              { icon: 'fa-table-list', label: 'Compte de résultat' },\n              { icon: 'fa-water', label: 'Trésorerie 5 ans' },\n              { icon: 'fa-calendar', label: 'Trésorerie mensuelle' },\n              { icon: 'fa-scale-balanced', label: 'Bilan' },\n              { icon: 'fa-chart-pie', label: 'Plan de financement' },\n              { icon: 'fa-chart-line', label: 'Rentabilité' },\n              { icon: 'fa-arrows-down-to-line', label: 'Amortissements' },\n              { icon: 'fa-building-columns', label: 'Emprunts' },\n            ].map(({ icon, label }) => (\n              <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)' }}>\n                <i className={`fas ${icon}`} style={{ color: 'var(--color-primary)', width: 14 }} />\n                {label}\n              </div>\n            ))}\n          </div>\n        </div>\n      </div>\n    </div>\n  )\n}\n","import { useEffect, useCallback, useState } from 'react'\nimport { useParams, useNavigate } from 'react-router-dom'\nimport { companyApi } from '@/api/api'\nimport { syncService } from '@/services/syncService'\nimport { useNetworkStore } from '@/stores/networkStore'\nimport { useCompanyStore } from '@/stores/companyStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport SyncIndicator from '@/components/ui/SyncIndicator'\nimport EditorSidebar from '@/components/editor/EditorSidebar'\nimport SettingsSection from '@/components/editor/sections/SettingsSection'\nimport ProductsSection from '@/components/editor/sections/ProductsSection'\nimport MaterialsSection from '@/components/editor/sections/MaterialsSection'\nimport StaffSection from '@/components/editor/sections/StaffSection'\nimport ExpensesSection from '@/components/editor/sections/ExpensesSection'\nimport InvestmentsSection from '@/components/editor/sections/InvestmentsSection'\nimport FundingSection from '@/components/editor/sections/FundingSection'\nimport ResultsSection from '@/components/editor/sections/ResultsSection'\nimport CashFlowSection from '@/components/editor/sections/CashFlowSection'\nimport BalanceSection from '@/components/editor/sections/BalanceSection'\nimport FinancingSection from '@/components/editor/sections/FinancingSection'\nimport ProfitabilitySection from '@/components/editor/sections/ProfitabilitySection'\nimport SyntheseSection from '@/components/editor/sections/SyntheseSection'\nimport ExportSection from '@/components/editor/sections/ExportSection'\n\nexport default function EditorPage() {\n  const { companyId } = useParams<{ companyId: string }>()\n  const navigate = useNavigate()\n  const user = useAuthStore((s) => s.user)\n  const isOnline = useNetworkStore((s) => s.isOnline)\n\n  const company = useCompanyStore((s) => s.company)\n  const activeSection = useCompanyStore((s) => s.activeSection)\n  const setCompany = useCompanyStore((s) => s.setCompany)\n  const resetCompany = useCompanyStore((s) => s.resetCompany)\n\n  const [sidebarOpen, setSidebarOpen] = useState(false)\n  const [offlineMode, setOfflineMode] = useState(false)\n  const [apiError, setApiError] = useState<string | null>(null)\n\n  const loadCompany = useCallback(async () => {\n    if (!companyId) return\n    const id = Number(companyId)\n    setApiError(null)\n\n    if (isOnline) {\n      try {\n        const data = await companyApi.get(id)\n        setCompany(data)\n        // Mettre en cache pour usage offline ultérieur\n        await syncService.saveCompanyCache(data)\n        setOfflineMode(false)\n        return\n      } catch (err) {\n        // Erreur HTTP (500, 403…) — pas une déconnexion réseau\n        // On reste sur le cache mais on n'affiche PAS la bannière offline\n        const msg = err instanceof Error ? err.message : 'Erreur serveur'\n        setApiError(msg)\n        const cached = await syncService.loadCompanyCache(id)\n        if (cached) {\n          setCompany(cached)\n        }\n        return\n      }\n    }\n\n    // Vraiment hors-ligne : charger depuis IndexedDB\n    const cached = await syncService.loadCompanyCache(id)\n    if (cached) {\n      setCompany(cached)\n      setOfflineMode(true)\n    } else {\n      // Pas de cache disponible → retour au dashboard\n      navigate('/', { replace: true })\n    }\n  }, [companyId, isOnline, setCompany, navigate])\n\n  useEffect(() => {\n    loadCompany()\n    return () => resetCompany()\n  }, [loadCompany, resetCompany])\n\n  // Recharger depuis le serveur quand on revient en ligne\n  useEffect(() => {\n    if (isOnline && offlineMode && companyId) {\n      loadCompany()\n    }\n  }, [isOnline]) // eslint-disable-line react-hooks/exhaustive-deps\n\n  if (!company) {\n    return (\n      <div className=\"app-layout\">\n        <EditorSidebar companyName=\"Chargement…\" isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />\n        <main className=\"main-content\">\n          <div className=\"mobile-topbar\">\n            <button className=\"hamburger-btn\" onClick={() => setSidebarOpen(true)} aria-label=\"Ouvrir le menu\">\n              <i className=\"fas fa-bars\" />\n            </button>\n            <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ height: 32 }} />\n          </div>\n          <div className=\"loading-overlay\">\n            <div className=\"spinner\" />\n            {isOnline ? \"Chargement de l'entreprise…\" : 'Chargement depuis le cache…'}\n          </div>\n        </main>\n      </div>\n    )\n  }\n\n  return (\n    <div className=\"app-layout\">\n      <EditorSidebar companyName={company.name} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />\n\n      <main className=\"main-content\">\n        {/* Mobile top bar */}\n        <div className=\"mobile-topbar\">\n          <button className=\"hamburger-btn\" onClick={() => setSidebarOpen(true)} aria-label=\"Ouvrir le menu\">\n            <i className=\"fas fa-bars\" />\n          </button>\n          <span style={{ fontWeight: 700, fontSize: 'var(--text-sm)', color: 'var(--color-text)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>\n            {company.name}\n          </span>\n          {user && <span style={{ ...styles.userChip, marginLeft: 'auto' }}>{user.initials}</span>}\n        </div>\n\n        {/* Top bar */}\n        <div style={styles.topBar}>\n          {/* Gauche */}\n          <button\n            className=\"btn btn-ghost btn-sm\"\n            onClick={() => navigate('/')}\n          >\n            <i\n              className=\"fas fa-arrow-left\"\n              style={{ marginRight: 6, fontSize: 11 }}\n            />\n            Tableau de bord\n          </button>\n\n          {/* Spacer */}\n          <div style={{ flex: 1 }} />\n\n          {/* Droite */}\n          <div style={styles.rightSection}>\n            {/* Infos entreprise */}\n            <div style={styles.companyInfo}>\n              <h2 style={styles.companyName}>{company.name}</h2>\n\n              {company.secteur && (\n                <span style={styles.sector}>\n                  <i\n                    className=\"fas fa-tag\"\n                    style={{ marginRight: 5, fontSize: 10 }}\n                  />\n                  {company.secteur}\n                </span>\n              )}\n            </div>\n\n            <SyncIndicator />\n          </div>\n        </div>\n\n        {/* Bannière mode offline — uniquement si vraiment sans réseau */}\n        {offlineMode && !apiError && (\n          <div style={styles.offlineBanner}>\n            <i className=\"fas fa-database\" style={{ marginRight: 8 }} />\n            Mode hors-ligne — vous travaillez sur une copie locale.\n            Les modifications seront synchronisées automatiquement au retour en ligne.\n          </div>\n        )}\n\n        {/* Bannière erreur serveur (500, DB…) — en ligne mais API en erreur */}\n        {apiError && (\n          <div style={styles.errorBanner}>\n            <i className=\"fas fa-circle-exclamation\" style={{ marginRight: 8 }} />\n            Erreur serveur : {apiError}. Vérifiez que l'API fonctionne correctement.\n          </div>\n        )}\n\n        {/* Section content */}\n        <div style={{ marginTop: 'var(--space-6)' }}>\n          {activeSection === 'entreprise'    && <SettingsSection />}\n          {activeSection === 'products'       && <ProductsSection />}\n          {activeSection === 'materials'      && <MaterialsSection />}\n          {activeSection === 'staff'          && <StaffSection />}\n          {activeSection === 'expenses'       && <ExpensesSection />}\n          {activeSection === 'investments'    && <InvestmentsSection />}\n          {activeSection === 'funding'        && <FundingSection />}\n          {activeSection === 'results'        && <ResultsSection />}\n          {activeSection === 'cashflow'       && <CashFlowSection />}\n          {activeSection === 'balance'        && <BalanceSection />}\n          {activeSection === 'profitability'  && <ProfitabilitySection />}\n          {activeSection === 'financing'      && <FinancingSection />}\n          {activeSection === 'synthese'       && <SyntheseSection />}\n          {activeSection === 'export'         && <ExportSection />}\n        </div>\n      </main>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\ntopBar: {\n  display: 'flex',\n  alignItems: 'center',\n  borderBottom: '1px solid var(--color-border)',\n  paddingBottom: 'var(--space-4)',\n  marginBottom: 'var(--space-2)',\n},\n\nrightSection: {\n  display: 'flex',\n  alignItems: 'center',\n  gap: 'var(--space-4)',\n},\n\ncompanyInfo: {\n  textAlign: 'left',\n},\n\ncompanyName: {\n  fontSize: 'var(--text-2xl)',\n  fontWeight: 700,\n  color: 'var(--color-text)',\n  lineHeight: 1.2,\n  margin: 0,\n},\n\nsector: {\n  fontSize: 'var(--text-sm)',\n  color: 'var(--color-accent)',\n  display: 'block',\n  marginTop: 4,\n},\n  userChip: {\n    width: 32, height: 32,\n    borderRadius: '50%',\n    background: 'var(--color-primary)',\n    color: '#fff',\n    display: 'flex', alignItems: 'center', justifyContent: 'center',\n    fontSize: 12, fontWeight: 700, flexShrink: 0,\n  },\n  offlineBanner: {\n    marginTop: 'var(--space-4)',\n    padding: 'var(--space-3) var(--space-4)',\n    background: '#fffbeb',\n    border: '1px solid #f5a623',\n    borderRadius: 'var(--radius)',\n    color: '#92400e',\n    fontSize: 'var(--text-sm)',\n    display: 'flex',\n    alignItems: 'center',\n  },\n  errorBanner: {\n    marginTop: 'var(--space-4)',\n    padding: 'var(--space-3) var(--space-4)',\n    background: '#fef2f2',\n    border: '1px solid #fca5a5',\n    borderRadius: 'var(--radius)',\n    color: '#dc2626',\n    fontSize: 'var(--text-sm)',\n    display: 'flex',\n    alignItems: 'center',\n  },\n}\n","import { useState, useEffect, useCallback } from 'react'\nimport { useNavigate } from 'react-router-dom'\nimport { userApi, ApiError, type UserSummary } from '@/api/api'\nimport AppSidebar from '@/components/layout/AppSidebar'\n\n/** Génère un mot de passe sécurisé de 12 caractères */\nfunction generatePassword(): string {\n  const upper  = 'ABCDEFGHJKMNPQRSTUVWXYZ'\n  const lower  = 'abcdefghjkmnpqrstuvwxyz'\n  const digits = '23456789'\n  const special = '!@#$%&*'\n  const all = upper + lower + digits + special\n  // Garantir au moins 1 de chaque catégorie\n  const required = [\n    upper[Math.floor(Math.random() * upper.length)],\n    lower[Math.floor(Math.random() * lower.length)],\n    digits[Math.floor(Math.random() * digits.length)],\n    special[Math.floor(Math.random() * special.length)],\n  ]\n  const rest = Array.from({ length: 8 }, () => all[Math.floor(Math.random() * all.length)])\n  return [...required, ...rest].sort(() => Math.random() - 0.5).join('')\n}\n\ninterface CreatedResult {\n  user: UserSummary\n  tempPassword: string\n}\n\nexport default function UserManagementPage() {\n  const navigate = useNavigate()\n  const [users, setUsers]           = useState<UserSummary[]>([])\n  const [isLoading, setIsLoading]   = useState(true)\n  const [sidebarOpen, setSidebarOpen] = useState(false)\n\n  const [showForm, setShowForm]     = useState(false)\n  const [formEmail, setFormEmail]   = useState('')\n  const [formFirst, setFormFirst]   = useState('')\n  const [formLast, setFormLast]     = useState('')\n  const [isCreating, setIsCreating] = useState(false)\n  const [formError, setFormError]   = useState<string | null>(null)\n\n  const [created, setCreated]       = useState<CreatedResult | null>(null)\n  const [copied, setCopied]         = useState(false)\n\n  const loadUsers = useCallback(async () => {\n    setIsLoading(true)\n    try {\n      const data = await userApi.list()\n      setUsers(data)\n    } finally {\n      setIsLoading(false)\n    }\n  }, [])\n\n  useEffect(() => { loadUsers() }, [loadUsers])\n\n  function openForm() {\n    setFormEmail(''); setFormFirst(''); setFormLast('')\n    setFormError(null); setCreated(null); setCopied(false)\n    setShowForm(true)\n  }\n\n  async function handleCreate(e: React.FormEvent) {\n    e.preventDefault()\n    if (!formEmail.trim()) return\n    setFormError(null)\n    setIsCreating(true)\n\n    const tempPassword = generatePassword()\n\n    try {\n      const newUser = await userApi.create(\n        formEmail.trim(),\n        tempPassword,\n        formFirst.trim(),\n        formLast.trim(),\n      )\n      setCreated({ user: newUser, tempPassword })\n      setShowForm(false)\n      setUsers((prev) => [newUser, ...prev])\n    } catch (err) {\n      setFormError(err instanceof ApiError ? err.message : \"Erreur lors de la création.\")\n    } finally {\n      setIsCreating(false)\n    }\n  }\n\n  async function handleCopy(text: string) {\n    try {\n      await navigator.clipboard.writeText(text)\n      setCopied(true)\n      setTimeout(() => setCopied(false), 2500)\n    } catch {\n      // fallback : sélection manuelle\n    }\n  }\n\n  return (\n    <div className=\"app-layout\">\n      <AppSidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />\n\n      <main className=\"main-content\">\n        {/* Mobile topbar */}\n        <div className=\"mobile-topbar\">\n          <button className=\"hamburger-btn\" onClick={() => setSidebarOpen(true)} aria-label=\"Menu\">\n            <i className=\"fas fa-bars\" />\n          </button>\n          <img src=\"/AIDES Développement HD.png\" alt=\"AIDES\" style={{ height: 32 }} />\n        </div>\n\n        {/* Header */}\n        <div style={styles.topBar}>\n          <div>\n            <button className=\"btn btn-ghost btn-sm\" onClick={() => navigate('/')} style={{ marginBottom: 4 }}>\n              <i className=\"fas fa-arrow-left\" style={{ marginRight: 6, fontSize: 11 }} />\n              Tableau de bord\n            </button>\n            <h2 style={styles.title}>\n              <i className=\"fas fa-users\" style={{ marginRight: 10, color: 'var(--color-primary)' }} />\n              Gestion des utilisateurs\n            </h2>\n            <p style={styles.subtitle}>Créez des comptes pour les membres de l'équipe AIDES.</p>\n          </div>\n          <button className=\"btn btn-primary\" onClick={openForm}>\n            <i className=\"fas fa-user-plus\" style={{ marginRight: 6 }} />\n            Nouveau compte\n          </button>\n        </div>\n\n        {/* ── Mot de passe temporaire affiché après création ── */}\n        {created && (\n          <div style={styles.successBox}>\n            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>\n              <i className=\"fas fa-check-circle\" style={{ fontSize: 22, color: 'var(--color-success)' }} />\n              <div>\n                <div style={{ fontWeight: 700, color: 'var(--color-text)' }}>\n                  Compte créé — {created.user.fullName}\n                </div>\n                <div style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>\n                  {created.user.email}\n                </div>\n              </div>\n            </div>\n\n            <p style={{ fontSize: 'var(--text-sm)', color: '#92400e', fontWeight: 500, marginBottom: 10 }}>\n              <i className=\"fas fa-triangle-exclamation\" style={{ marginRight: 6 }} />\n              Mot de passe temporaire — affiché une seule fois. Transmettez-le à l'utilisateur de façon sécurisée.\n            </p>\n\n            <div style={styles.passwordBox}>\n              <code style={styles.passwordText}>{created.tempPassword}</code>\n              <button\n                style={styles.copyBtn}\n                onClick={() => handleCopy(created.tempPassword)}\n              >\n                {copied\n                  ? <><i className=\"fas fa-check\" style={{ marginRight: 6 }} />Copié !</>\n                  : <><i className=\"fas fa-copy\" style={{ marginRight: 6 }} />Copier</>\n                }\n              </button>\n            </div>\n\n            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', marginTop: 10 }}>\n              L'utilisateur se connecte avec cet email et ce mot de passe, puis peut le modifier depuis son profil.\n            </p>\n\n            <button\n              className=\"btn btn-ghost btn-sm\"\n              style={{ marginTop: 8 }}\n              onClick={() => setCreated(null)}\n            >\n              <i className=\"fas fa-times\" style={{ marginRight: 6 }} />\n              Fermer\n            </button>\n          </div>\n        )}\n\n        {/* ── Formulaire de création ── */}\n        {showForm && (\n          <div className=\"card\" style={{ marginBottom: 'var(--space-6)', borderLeft: '4px solid var(--color-primary)' }}>\n            <div className=\"card-header\">\n              <span className=\"card-title\">\n                <i className=\"fas fa-user-plus\" style={{ marginRight: 8 }} />\n                Créer un nouvel utilisateur\n              </span>\n              <button className=\"btn btn-ghost btn-sm\" onClick={() => setShowForm(false)}>\n                <i className=\"fas fa-times\" />\n              </button>\n            </div>\n            <div className=\"card-body\">\n              {formError && (\n                <div className=\"alert alert-error\" style={{ marginBottom: 'var(--space-4)' }}>\n                  <i className=\"fas fa-exclamation-circle\" style={{ marginRight: 8 }} />\n                  {formError}\n                </div>\n              )}\n              <form onSubmit={handleCreate}>\n                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 'var(--space-4)', marginBottom: 'var(--space-5)' }}>\n                  <div className=\"form-group\" style={{ marginBottom: 0 }}>\n                    <label className=\"form-label\">Prénom</label>\n                    <input className=\"form-input\" placeholder=\"Jean\" value={formFirst}\n                      onChange={(e) => setFormFirst(e.target.value)} />\n                  </div>\n                  <div className=\"form-group\" style={{ marginBottom: 0 }}>\n                    <label className=\"form-label\">Nom</label>\n                    <input className=\"form-input\" placeholder=\"Dupont\" value={formLast}\n                      onChange={(e) => setFormLast(e.target.value)} />\n                  </div>\n                  <div className=\"form-group\" style={{ marginBottom: 0, gridColumn: '1 / -1' }}>\n                    <label className=\"form-label\">Email professionnel *</label>\n                    <input type=\"email\" className=\"form-input\" required\n                      placeholder=\"jean.dupont@aides-mada.com\"\n                      value={formEmail} onChange={(e) => setFormEmail(e.target.value)} />\n                  </div>\n                </div>\n\n                <div style={{ background: 'var(--color-surface-2)', border: '1px solid var(--color-border)', borderRadius: 'var(--radius)', padding: '10px 14px', marginBottom: 'var(--space-5)', fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)', display: 'flex', gap: 8 }}>\n                  <i className=\"fas fa-shield-halved\" style={{ color: 'var(--color-primary)', marginTop: 1, flexShrink: 0 }} />\n                  <span>Un mot de passe sécurisé sera généré automatiquement et affiché une seule fois après la création. Transmettez-le à l'utilisateur de façon confidentielle.</span>\n                </div>\n\n                <div style={{ display: 'flex', gap: 'var(--space-3)' }}>\n                  <button type=\"submit\" className=\"btn btn-primary\" disabled={isCreating || !formEmail.trim()}>\n                    {isCreating\n                      ? <><span className=\"spinner\" style={{ width: 14, height: 14 }} /> Création…</>\n                      : <><i className=\"fas fa-user-plus\" style={{ marginRight: 6 }} />Créer le compte</>\n                    }\n                  </button>\n                  <button type=\"button\" className=\"btn btn-ghost\" onClick={() => setShowForm(false)}>\n                    Annuler\n                  </button>\n                </div>\n              </form>\n            </div>\n          </div>\n        )}\n\n        {/* ── Liste des utilisateurs ── */}\n        {isLoading ? (\n          <div className=\"loading-overlay\"><div className=\"spinner\" />Chargement…</div>\n        ) : users.length === 0 ? (\n          <div className=\"empty-state\">\n            <div className=\"empty-state-icon\"><i className=\"fas fa-users\" /></div>\n            <div className=\"empty-state-title\">Aucun utilisateur</div>\n            <p className=\"empty-state-desc\">Créez le premier compte membre de l'équipe.</p>\n          </div>\n        ) : (\n          <div className=\"card\">\n            <div className=\"card-header\">\n              <span className=\"card-title\">\n                <i className=\"fas fa-users\" style={{ marginRight: 8 }} />\n                Membres de l'équipe ({users.length})\n              </span>\n            </div>\n            <div className=\"table-wrapper\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Utilisateur</th>\n                    <th>Email</th>\n                    <th>Statut</th>\n                    <th>Membre depuis</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  {users.map((u) => (\n                    <tr key={u.id}>\n                      <td>\n                        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>\n                          <div style={styles.avatar}>{u.initials}</div>\n                          <span style={{ fontWeight: 600 }}>{u.fullName}</span>\n                        </div>\n                      </td>\n                      <td style={{ color: 'var(--color-text-muted)' }}>{u.email}</td>\n                      <td>\n                        <span style={{\n                          display: 'inline-flex', alignItems: 'center',\n                          padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600,\n                          background: u.isActive ? '#dcfce7' : '#fee2e2',\n                          color: u.isActive ? '#166534' : '#991b1b',\n                        }}>\n                          <i className=\"fas fa-circle\" style={{ fontSize: 6, marginRight: 5 }} />\n                          {u.isActive ? 'Actif' : 'Inactif'}\n                        </span>\n                      </td>\n                      <td style={{ color: 'var(--color-text-muted)', fontSize: 'var(--text-sm)' }}>\n                        {new Date(u.createdAt).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' })}\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n          </div>\n        )}\n      </main>\n    </div>\n  )\n}\n\nconst styles: Record<string, React.CSSProperties> = {\n  topBar: {\n    display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between',\n    gap: 'var(--space-4)', borderBottom: '1px solid var(--color-border)',\n    paddingBottom: 'var(--space-4)', marginBottom: 'var(--space-6)',\n  },\n  title: { fontSize: 'var(--text-2xl)', fontWeight: 700, color: 'var(--color-text)', lineHeight: 1.2 },\n  subtitle: { fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)', marginTop: 4 },\n  successBox: {\n    background: '#fffbeb', border: '1px solid #fbbf24',\n    borderLeft: '4px solid var(--color-success)',\n    borderRadius: 'var(--radius-md)', padding: 'var(--space-5)',\n    marginBottom: 'var(--space-6)',\n  },\n  passwordBox: {\n    display: 'flex', alignItems: 'center', gap: 10,\n    background: '#1e2433', borderRadius: 'var(--radius)',\n    padding: '10px 16px',\n  },\n  passwordText: {\n    flex: 1, fontSize: 20, fontWeight: 700, letterSpacing: 3,\n    color: '#f5a623', fontFamily: 'monospace',\n  },\n  copyBtn: {\n    background: 'var(--color-primary)', border: 'none', borderRadius: 'var(--radius)',\n    color: '#fff', padding: '6px 14px', cursor: 'pointer',\n    fontSize: 'var(--text-sm)', fontWeight: 600, display: 'flex', alignItems: 'center',\n    flexShrink: 0,\n  },\n  avatar: {\n    width: 34, height: 34, borderRadius: '50%',\n    background: 'var(--color-primary)', color: '#fff',\n    display: 'flex', alignItems: 'center', justifyContent: 'center',\n    fontSize: 13, fontWeight: 700, flexShrink: 0,\n  },\n}\n","import { useEffect, useState } from 'react'\nimport { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom'\nimport { useAuthStore } from '@/stores/authStore'\nimport { authApi, ApiError } from '@/api/api'\nimport { syncService } from '@/services/syncService'\nimport LoginPage from '@/pages/LoginPage'\nimport RegisterPage from '@/pages/RegisterPage'\nimport DashboardPage from '@/pages/DashboardPage'\nimport EditorPage from '@/pages/EditorPage'\nimport UserManagementPage from '@/pages/UserManagementPage'\n\nfunction RequireAuth({ children }: { children: React.ReactNode }) {\n  const isAuthenticated = useAuthStore((s) => s.isAuthenticated)\n  return isAuthenticated ? <>{children}</> : <Navigate to=\"/login\" replace />\n}\n\nexport default function App() {\n  const token = useAuthStore((s) => s.token)\n  const user = useAuthStore((s) => s.user)\n  const setUser = useAuthStore((s) => s.setUser)\n  const logout = useAuthStore((s) => s.logout)\n  const [ready, setReady] = useState(false)\n\n  // Initialise le service de synchronisation offline (listeners online/offline)\n  useEffect(() => {\n    const cleanup = syncService.init()\n    return cleanup\n  }, [])\n\n  // Restaure le profil utilisateur au démarrage si token présent mais user absent\n  useEffect(() => {\n    if (token && !user) {\n      authApi.me()\n        .then((u) => { setUser(u); setReady(true) })\n        .catch((err) => {\n          if (err instanceof ApiError && err.status === 401) {\n            logout()\n          }\n          setReady(true)\n        })\n    } else {\n      setReady(true)\n    }\n  }, []) // eslint-disable-line react-hooks/exhaustive-deps\n\n  if (!ready) {\n    return (\n      <div style={{\n        minHeight: '100vh', display: 'flex', alignItems: 'center',\n        justifyContent: 'center', background: '#1e2433',\n      }}>\n        <div className=\"spinner\" style={{ width: 32, height: 32 }} />\n      </div>\n    )\n  }\n\n  return (\n    <BrowserRouter>\n      <Routes>\n        <Route path=\"/login\" element={<LoginPage />} />\n        <Route path=\"/register\" element={<RegisterPage />} />\n        <Route\n          path=\"/\"\n          element={\n            <RequireAuth>\n              <DashboardPage />\n            </RequireAuth>\n          }\n        />\n        <Route\n          path=\"/users\"\n          element={\n            <RequireAuth>\n              <UserManagementPage />\n            </RequireAuth>\n          }\n        />\n        <Route\n          path=\"/editor/:companyId\"\n          element={\n            <RequireAuth>\n              <EditorPage />\n            </RequireAuth>\n          }\n        />\n        <Route path=\"*\" element={<Navigate to=\"/\" replace />} />\n      </Routes>\n    </BrowserRouter>\n  )\n}\n","import { StrictMode } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport '@/styles/globals.css'\nimport App from '@/App'\n\nconst root = document.getElementById('root')\nif (!root) throw new Error('Root element not found')\n\ncreateRoot(root).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n)\n"],"file":"assets/index-C00dHF1E.js"}